fn is_word_separator(grapheme: &str) -> bool {
    let mut characters = grapheme.chars();
    let is_separator = matches!(
        characters.next(),
        Some(' ' | '\u{00a0}' | '\u{1361}' | '\u{10100}' | '\u{10101}' | '\u{1039f}' | '\u{1091f}')
    );
    is_separator
}

