fn scroll_reverse(style: &Style) -> (bool,bool) {
    let rtl=style.used_direction()==css::Direction::Rtl;
    match style.writing_mode {
        css::WritingMode::HorizontalTb=>(rtl,false),
        css::WritingMode::VerticalRl|css::WritingMode::SidewaysRl=>(true,rtl),
        css::WritingMode::VerticalLr=>(false,rtl),
        css::WritingMode::SidewaysLr=>(false,!rtl),
    }
}

