/// Overflow edges stay in the owning box's layout coordinate space; rounded
/// paint origins never participate in scrolling-area calculations.
#[derive(Clone, Copy, Debug, PartialEq)]
struct OverflowRect { left:f64,top:f64,right:f64,bottom:f64 }
impl OverflowRect {
    fn new(x:f64,y:f64,width:f32,height:f32)->Option<Self> {
        let value=Self {left:x,top:y,right:x+f64::from(width),bottom:y+f64::from(height)};
        (width>=0.0&&height>=0.0&&value.left.is_finite()&&value.top.is_finite()&&value.right.is_finite()&&value.bottom.is_finite()).then_some(value)
    }
    fn shifted(self,x:f64,y:f64)->Self {Self {left:self.left+x,right:self.right+x,top:self.top+y,bottom:self.bottom+y}}
    fn union(self,other:Self)->Self {Self {left:self.left.min(other.left),top:self.top.min(other.top),right:self.right.max(other.right),bottom:self.bottom.max(other.bottom)}}
    fn intersection(self,other:Self)->Option<Self> {
        let value=Self {left:self.left.max(other.left),top:self.top.max(other.top),right:self.right.min(other.right),bottom:self.bottom.min(other.bottom)};
        (value.right>=value.left&&value.bottom>=value.top).then_some(value)
    }
    fn transformed(self,matrix:crate::paint::Affine)->Option<Self> {
        let mut result:Option<Self>=None;
        for (x,y) in [(self.left,self.top),(self.right,self.top),(self.right,self.bottom),(self.left,self.bottom)] {
            let point=(f64::from(matrix.a)*x+f64::from(matrix.c)*y+f64::from(matrix.e),f64::from(matrix.b)*x+f64::from(matrix.d)*y+f64::from(matrix.f));
            let rect=Self::new(point.0,point.1,0.0,0.0)?;
            result=Some(result.map_or(rect,|old|old.union(rect)));
        }
        result
    }
    fn bounds(self,node:NodeId,port:Self,reverse:(bool,bool),axes:(bool,bool))->ScrollBounds {ScrollBounds::from_overflow(node,port,self,reverse,axes)}
}

#[derive(Clone, Copy, Default)]
struct OverflowMetrics { parent:Option<OverflowRect>,border:Option<OverflowRect> }
#[derive(Clone, Copy)]
enum OverflowRoute { Parent,ContainingBlock(NodeId),Root,ViewportFixed }
struct OverflowContribution { rect:OverflowRect,hits:Range<usize>,key:(usize,usize),paint_owner:Option<core::num::NonZeroU32> }
struct OverflowFrame {
    node:NodeId,extent:Option<OverflowRect>,padding_box:Option<OverflowRect>,
    paint_origin:(f32,f32),placement:(f64,f64),format_offset:(f64,f64),containing_origin:Option<(f64,f64)>,border_box:Option<OverflowRect>,projection_clip:Option<OverflowRect>,
    children:Vec<OverflowContribution>,retain_to_parent:bool,content_anchor:Option<((f32,f32),(f64,f64))>,flow_cursor:Option<(f32,f64)>,block_cursor:Option<(f32,f64)>,
    clip_x:bool,clip_y:bool,scroll_adjust:(f32,f32),scroll_container:bool,scroll_reverse:(bool,bool),route:OverflowRoute,
}
impl OverflowFrame {
    fn new(node:NodeId,clip_x:bool,clip_y:bool,scroll_adjust:(f32,f32),scroll_container:bool,route:OverflowRoute)->Self {
        Self {node,extent:None,padding_box:None,paint_origin:(0.0,0.0),placement:(0.0,0.0),format_offset:(0.0,0.0),containing_origin:None,border_box:None,projection_clip:None,children:Vec::new(),retain_to_parent:false,content_anchor:None,flow_cursor:None,block_cursor:None,clip_x,clip_y,scroll_adjust,scroll_container,scroll_reverse:(false,false),route}
    }
    fn viewport(node:NodeId,viewport:Rect,scroll_adjust:(f32,f32))->Self {
        let rect=OverflowRect::new(0.0,0.0,viewport.width,viewport.height);
        Self {extent:rect,padding_box:rect,paint_origin:(viewport.x,viewport.y),..Self::new(node,false,false,scroll_adjust,false,OverflowRoute::Root)}
    }
    fn include(&mut self,rect:OverflowRect) {self.extent=Some(self.extent.map_or(rect,|old|old.union(rect)));}
    fn combined_extent(&self)->Option<OverflowRect> {
        self.children.iter().fold(self.extent,|old,value|Some(old.map_or(value.rect,|old|old.union(value.rect))))
    }
    fn set_padding_box(&mut self,rect:OverflowRect) {self.padding_box=Some(rect);self.include(rect);}
    fn translate(&mut self,dx:f32,dy:f32) {let (x,y)=(f64::from(dx),f64::from(dy));self.extent=self.extent.map(|rect|rect.shifted(x,y));self.padding_box=self.padding_box.map(|rect|rect.shifted(x,y));for value in &mut self.children {value.rect=value.rect.shifted(x,y);}}
    fn metrics(&self,transform:Option<crate::paint::Affine>)->OverflowMetrics {
        let mut parent=self.combined_extent();
        if let Some(clip)=self.projection_clip {parent=parent.and_then(|rect|rect.intersection(clip));}
        if self.clip_x||self.clip_y {
            parent=self.padding_box.and_then(|port| {
                let clip=OverflowRect {left:if self.clip_x {port.left}else{f64::NEG_INFINITY},right:if self.clip_x {port.right}else{f64::INFINITY},top:if self.clip_y {port.top}else{f64::NEG_INFINITY},bottom:if self.clip_y {port.bottom}else{f64::INFINITY}};
                parent.and_then(|rect|rect.intersection(clip))
            });
        }
        // Descendant overflow is clipped; this box's own nonzero-area border
        // remains scrollable overflow (Overflow 3 §3.3). Collapsed-cell track
        // projection is a separate policy and still constrains that border.
        if let Some(border)=self.border_box.filter(|rect|rect.right>rect.left&&rect.bottom>rect.top) {
            let border=if let Some(clip)=self.projection_clip {border.intersection(clip)}else{Some(border)};
            if let Some(border)=border {parent=Some(parent.map_or(border,|rect|rect.union(border)));}
        }
        let Some(mut parent)=parent else{return OverflowMetrics::default()};
        if let Some(matrix)=transform {
            let Some(value)=parent.transformed(matrix)else{return OverflowMetrics::default()};
            parent=parent.union(value);
        }
        OverflowMetrics {parent:Some(parent),border:self.border_box}
    }

}

fn union_rect(left: Rect, right: Rect) -> Rect {
    let x = left.x.min(right.x);
    let y = left.y.min(right.y);
    // Measure extents relative to the shared origin. Adding world-coordinate
    // edges and subtracting the origin loses local dimensions during scrolling.
    let width = ((left.x - x) + left.width).max((right.x - x) + right.width);
    let height = ((left.y - y) + left.height).max((right.y - y) + right.height);
    Rect {
        x,
        y,
        width,
        height,
    }
}

pub(crate) fn transformed_bounds(
    rect: Rect,
    transforms: impl Iterator<Item = crate::paint::Affine>,
) -> Option<Rect> {
    if !rect.is_valid() {
        return None;
    }
    let mut corners = [
        (rect.x, rect.y),
        (rect.x + rect.width, rect.y),
        (rect.x, rect.y + rect.height),
        (rect.x + rect.width, rect.y + rect.height),
    ];
    for transform in transforms {
        for point in &mut corners {
            *point = transform.apply(point.0, point.1);
        }
    }
    let left = corners
        .iter()
        .map(|point| point.0)
        .fold(f32::INFINITY, f32::min);
    let top = corners
        .iter()
        .map(|point| point.1)
        .fold(f32::INFINITY, f32::min);
    let right = corners
        .iter()
        .map(|point| point.0)
        .fold(f32::NEG_INFINITY, f32::max);
    let bottom = corners
        .iter()
        .map(|point| point.1)
        .fold(f32::NEG_INFINITY, f32::max);
    Rect {
        x: left,
        y: top,
        width: right - left,
        height: bottom - top,
    }
    .is_valid()
    .then_some(Rect {
        x: left,
        y: top,
        width: right - left,
        height: bottom - top,
    })
}

