        let collapsed_vertical_sum = collapsed_y_widths.as_ref().map_or(0.0, |edges| {
            (edges.first().copied().unwrap_or(0.0) + edges.last().copied().unwrap_or(0.0)) * 0.5
        });
        let has_collapsed_rows = (0..rows.len()).any(|row| row_is_collapsed(row));
