                // the winning grid borders; table padding is ignored.
                let first = collapsed_edge_width(vertical, 0, 0, rows.len().min(1)) * 0.5;
                let last = collapsed_edge_width(vertical, columns, 0, rows.len().min(1)) * 0.5;
                let top = collapsed_edge_width(horizontal, 0, 0, columns) * 0.5;
                let bottom = collapsed_edge_width(horizontal, rows.len(), 0, columns) * 0.5;
