        let mut assigned_bytes=cells.len().checked_mul(core::mem::size_of::<AssignedCellPaint>()).filter(|bytes|*bytes<=MAX_DISPLAY_LIST_BYTES).ok_or(LayoutError::CommandLimit)?;
        let mut assigned_cells=Vec::new();assigned_cells.try_reserve_exact(cells.len()).map_err(|_|LayoutError::CommandLimit)?;
