                let style=&paragraph.frames[frame].style;
                let rtl=paragraph.frames[frame].parent.map_or(paragraph.inline_parent_rtl.get(),|parent|paragraph.frames[parent].style.used_direction() ==Direction::Rtl);
                let left=token.advance_opening!=rtl;
