    #[test]
    fn specification_standalone_svg_canvas_transform_owner_restores_on_primitive_error() {
        let document=crate::xml::parse("<svg xmlns='http://www.w3.org/2000/svg' width='40' height='32' viewBox='0 0 20 16' style='background:red;filter:url(#good);transform:scale(2);transform-origin:0 0'><defs><filter id='good' filterUnits='userSpaceOnUse' x='0' y='0' width='20' height='16'><feFlood/></filter><filter id='bad'><feTurbulence/></filter></defs><g filter='url(#bad)'/></svg>",32).unwrap();
        let node=document.document_element_at(document.root()).unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let style=css::compute_node(&document,node,None,&rules).unwrap();
        let NodeKind::Element{attributes,..}=document.kind(node).unwrap()else{unreachable!()};
        let text=NoShape;let text_uses=core::cell::Cell::new(0);let cache=RefCell::default();
        let mut layout=Layout::new(&document,&text,&text_uses,&rules,None,Rect{x:0.0,y:0.0,width:40.0,height:32.0},None,&[],&cache,None);
        assert!(layout.active_box.is_none(),"standalone dispatcher enters the root formatter directly");
        let prior=Some(Affine{e:3.0,f:2.0,..Affine::IDENTITY});layout.svg_filter_source_transform=prior;
        assert!(layout.paint_svg_root(node,attributes,&style,0.0,0.0,40.0,0,None).is_err(),"unsupported descendant primitive returns its real error");
        assert_eq!(layout.svg_filter_source_transform,prior);
        assert_eq!(layout.transform_depth,0,"deferred root content transform does not leak on child error");
        assert!(layout.svg_geometry_operation.is_none());
        assert!(DisplayList(layout.commands).validate().is_ok(),"viewport, content and root effect scopes close before error return");
    }

    #[test]
    fn specification_svg_url_source_owner_restores_world_coordinate_context_on_child_error() {
        let document=crate::html::parse("<svg width='40' height='40'><defs><filter id=paint filterUnits='userSpaceOnUse' x='0' y='0' width='20' height='20'><feFlood/></filter></defs><svg width='20' height='20' overflow='hidden' transform='translate(4 5)' filter='url(#paint)'><g filter='url(other.svg#paint)'></g></svg></svg>",64).unwrap();
        let node=crate::selector::query_selector(&document,document.root(),"svg").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let style=css::compute_node(&document,node,None,&rules).unwrap();
        let NodeKind::Element{attributes,..}=document.kind(node).unwrap()else{unreachable!()};
        let text=NoShape;let text_uses=core::cell::Cell::new(0);let cache=RefCell::default();
        let mut layout=Layout::new(&document,&text,&text_uses,&rules,None,Rect{x:0.0,y:0.0,width:40.0,height:40.0},None,&[],&cache,None);
        let prior=Some(Affine{e:3.0,f:2.0,..Affine::IDENTITY});layout.svg_filter_source_transform=prior;
        assert!(layout.paint_svg_root(node,attributes,&style,0.0,0.0,40.0,0,None).is_err(),"external resource remains an honest unsupported consumer");
        assert!(layout.filter_source_uses>=2,"failure follows entry into the actual parent URL owner");
        assert_eq!(layout.svg_filter_source_transform,prior,"failed descendant cannot leak its local source coordinate system");
        assert!(layout.svg_geometry_operation.is_none(),"resource failure restores the shared geometry operation");
    }

    #[test]
    fn specification_svg_object_geometry_capture_restores_on_failure() {
        let document=crate::html::parse("<svg></svg>",16).unwrap();let rules=stylesheets(&document).unwrap();
        let text=NoShape;let text_uses=core::cell::Cell::new(0);let cache=RefCell::default();
        let mut layout=Layout::new(&document,&text,&text_uses,&rules,None,
            Rect{x:0.0,y:0.0,width:10.0,height:10.0},None,&[],&cache,None);
        let result:Result<(),LayoutError>=layout.with_svg_geometry_capture(true,|layout|{
            assert!(layout.svg_geometry_capture);
            layout.with_svg_geometry_capture(false,|layout|{assert!(layout.svg_geometry_capture);Err(LayoutError::DepthLimit)})
        });
        assert_eq!(result,Err(LayoutError::DepthLimit));assert!(!layout.svg_geometry_capture);
    }

    #[test]
    fn specification_spatial_source_capture_restores_paint_participation_on_error() {
        let document=crate::html::parse("<div></div>",16).unwrap();
        let rules=stylesheets(&document).unwrap();
        let text=NoShape;let text_uses=core::cell::Cell::new(0);let cache=RefCell::default();
        let viewport=Rect{x:0.0,y:0.0,width:10.0,height:10.0};
        let mut layout=Layout::new(&document,&text,&text_uses,&rules,None,viewport,None,&[],&cache,None);
        let result:Result<(),LayoutError>=layout.with_spatial_source_capture(true,|layout|{
            assert_eq!(layout.source_capture_depth,1);
            assert_eq!(layout.cull,viewport,"capture cannot alter layout or scroll bounds");
            layout.with_spatial_source_capture(true,|layout|{
                assert_eq!(layout.source_capture_depth,2);Err(LayoutError::DepthLimit)
            })
        });
        assert_eq!(result,Err(LayoutError::DepthLimit));assert_eq!(layout.source_capture_depth,0);
        layout.source_capture_depth=512;
        assert_eq!(layout.with_spatial_source_capture(true,|_|Ok(())),Err(LayoutError::DepthLimit));
        assert_eq!(layout.source_capture_depth,512);
    }

