    #[test]
    fn specification_principal_paint_context_empty_scopes_preserve_canvas_and_hit_boundaries() {
        for property in ["transform:scale(-1)", "opacity:0.5", "transform:translateX(2px);opacity:0.5"] {
            for body in ["", "<div style='transform:scale(1)'></div><div style='opacity:0.5'></div>"] {
                let markup = alloc::format!("<!doctype html><style>html{{background:green;{property}}}body{{margin:0}}</style><body>{body}</body>");
                let document = crate::html::parse(&markup, 64).unwrap();
                let rules = stylesheets(&document).unwrap();
                for collect_geometry in [false, true] {
                    let cache = RefCell::default();
                    let mut retained = RetainedLayoutCache::default();
                    let mut previous = None;
                    for _ in 0..2 {
                        retained.begin_frame();
                        let mut geometry = LayoutGeometry::default();
                        let list = display_list_with_retained_layout_and_root(&document, 300, 150, &NoShape,
                            &rules, None, collect_geometry.then_some(&mut geometry), &[], &cache,
                            Some(&mut retained), None, None).expect("empty scopes retain valid paint and hit boundaries");
                        if property == "transform:scale(-1)" {
                            assert!(matches!(list.0.first(), Some(Command::FillRect { color, .. }) if *color == Rgba { r:0, g:128, b:0, a:255 }),
                                "CSS Transforms keeps propagated canvas paint outside the root transform");
                        }
                        if let Some(previous) = previous { assert_eq!(list, previous); }
                        previous = Some(list);
                    }
                }
            }
        }
    }

    #[test]
    fn specification_principal_paint_context_empty_positioned_siblings_preserve_real_ranges() {
        for ratio in ["50%", "100%"] {
            let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}div{{position:relative;width:192px}}#a{{position:absolute;width:100%;border-bottom:3px solid red}}#b{{margin-bottom:{ratio}}}#c{{border-bottom:3px solid black;margin-top:-96px}}</style><div id=wrapper><div id=a></div><div id=b></div><div id=c></div></div>");
            let document = crate::html::parse(&markup, 64).unwrap();
            let styles = stylesheets(&document).unwrap();
            for collect_geometry in [false, true] {
                let mut geometry = LayoutGeometry::default();
                let list = display_list_with_styles(&document, 800, 600, &FixedText, &styles, None,
                    collect_geometry.then_some(&mut geometry), &[]).unwrap();
                assert!(!list.0.is_empty(), "border surfaces remain in the real display list");
                let style_cache = RefCell::default();
                let mut retained = RetainedLayoutCache::default();
                for _ in 0..2 {
                    retained.begin_frame();
                    let mut replay_geometry = LayoutGeometry::default();
                    let replay = display_list_with_retained_layout(&document, 800, 600, &FixedText,
                        &styles, None, collect_geometry.then_some(&mut replay_geometry), &[],
                        &style_cache, Some(&mut retained)).unwrap();
                    assert_eq!(replay, list, "coincident intervals preserve every border on replay");
                    if collect_geometry {
                        assert_eq!(replay_geometry.hits.len(), geometry.hits.len());
                        for (actual, expected) in replay_geometry.hits.iter().zip(&geometry.hits) {
                            assert_eq!(actual.node, expected.node, "paint and hit order stay aligned");
                            assert_eq!(actual.rect, expected.rect);
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn specification_background_size_math_real_layers_and_retained_commands() {
        for (area, first, second) in [(40,20,30),(100,50,60),(200,80,110)] {
            let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}div{{width:{area}px;height:100px;background:linear-gradient(green,green) 0/min(50%, 80px) 20px no-repeat,linear-gradient(blue,blue) 0/calc(50% + 10px) 20px no-repeat}}</style><div><span style='display:block;background:none;background-size:inherit;width:3px;height:3px'></span></div>");
            let expected=markup.replace("min(50%, 80px)",&alloc::format!("{first}px"))
                .replace("calc(50% + 10px)",&alloc::format!("{second}px"));
            let document=crate::html::parse(&markup,64).unwrap();let reference=crate::html::parse(&expected,64).unwrap();
            let rules=stylesheets(&document).unwrap();let styles=RefCell::default();let mut retained=RetainedLayoutCache::default();
            for frame in 0..2 {
                retained.begin_frame();let mut geometry=LayoutGeometry::default();
                let list=display_list_with_retained_layout(&document,300,150,&NoShape,&rules,None,Some(&mut geometry),&[],&styles,Some(&mut retained)).unwrap();
                assert_eq!(list,display_list(&reference,300,150,&NoShape).unwrap());
                if frame != 0 {assert!(retained.stats().hits>0,"eligible child retaining computed size math actually replays");}
            }
        }
        let source="<!doctype html><style>html,body{margin:0}div{width:100px;height:50px;background:linear-gradient(red,red) 0/calc(-10px) 20px no-repeat}</style><div></div>";
        let document=crate::html::parse(source,32).unwrap();
        let list=display_list(&document,200,100,&NoShape).unwrap();
        assert!(list.0.iter().filter_map(|command|if let Command::FillBackground(value)=command{Some(value)}else{None})
            .all(|value|value.image_rect.width==0.0),"negative calculated size clamps only at used geometry");
    }

    #[test]
    fn specification_font_unit_layout_preserves_zero_advance_and_selected_metrics() {
        struct Selected;
        impl TextShaper for Selected {
            fn shape(&self, _: &str, _: f32) -> Result<ShapedRun, ()> { panic!("unit metrics must not shape text") }
            fn ascent(&self, _: f32) -> f32 { 10.0 }
            fn line_height(&self, _: f32) -> f32 { 20.0 }
            fn font_unit_metrics_styled(&self, _: f32, _: &FontSpec, _: bool, _: bool) -> crate::paint::FontUnitMetrics {
                crate::paint::FontUnitMetrics { cap: Some(8.0), ch: Some(0.0), ic: Some(12.0) }
            }
        }
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}#target{width:calc(100px + 5ch);height:2ic;padding-top:1cap}</style><div id=target></div>",64).unwrap();
        let node=crate::selector::get_element_by_id(&document,document.root(),"target").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,300,100,&Selected,&rules,None,Some(&mut geometry),&[]).unwrap();
        let rect=geometry.hits.iter().find(|hit|hit.node==node).unwrap().rect;
        assert_eq!((rect.width,rect.height),(100.0,32.0),"actual rendering keeps zero ch and selected cap/ic metrics through its accounting wrapper");
    }

    struct NoShape;

    impl TextShaper for NoShape {
        fn shape(&self, _: &str, _: f32) -> Result<ShapedRun, ()> {
            panic!("offscreen text was shaped")
        }
        fn ascent(&self, _: f32) -> f32 {
            10.0
        }
        fn line_height(&self, _: f32) -> f32 {
            20.0
        }
    }

#[test]
fn specification_local_overflow_fractional_ancestor_preserves_actual_bounds_and_retained_replay() {
    let document=crate::html::parse("<style>html,body{margin:0}#outer{width:100px;height:100px;overflow:scroll}#inner{width:200px;height:200px;overflow:scroll}#target{width:400px;height:400px}</style><div id=outer><div id=inner><div id=target></div></div>",64).unwrap();
    let rules=stylesheets(&document).unwrap();
    let lookup=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
    let outer=lookup("#outer");let inner=lookup("#inner");
    let styles=RefCell::default();let mut cache=RetainedLayoutCache::default();
    for fraction in [56.07899856567383f32,0.01,56.07901,99.99999] {
        let scrolls=[ScrollOffset {node:outer,x:fraction,y:fraction},ScrollOffset {node:inner,x:200.0,y:200.0}];
        for replay in 0..2 {
            cache.begin_frame();let mut retained=LayoutGeometry::default();
            let list=display_list_with_retained_layout(&document,800,600,&RecordingText::default(),&rules,None,Some(&mut retained),&scrolls,&styles,Some(&mut cache)).unwrap();
            let mut fresh=LayoutGeometry::default();
            let fresh_list=display_list_with_styles(&document,800,600,&RecordingText::default(),&rules,None,Some(&mut fresh),&scrolls).unwrap();
            assert_eq!(list,fresh_list);
            for geometry in [&retained,&fresh] {
                let bounds=geometry.scroll_extents.iter().find(|bounds|bounds.node==inner).unwrap();
                assert_eq!((bounds.min_x,bounds.max_x,bounds.min_y,bounds.max_y),(0.0,200.0,0.0,200.0),"fraction {fraction}");
            }
            if replay!=0 {assert!(cache.stats().hits>0,"actual ordinary target replay");}
        }
    }
}

