            let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{border-collapse:collapse;direction:{direction}}}td{{padding:0;font:16px/16px serif;border:none}}{owner}{{border:6px solid green}}</style><table id=t><colgroup><col><col></colgroup><tbody><tr><td>A</td><td>B</td></tr></tbody></table>");
