#[test]
fn specification_collapsed_border_junctions_close_outer_corners_and_preserve_grid_winners() {
    for direction in ["ltr","rtl"] {
        let markup=alloc::format!("<style>html,body{{margin:0}}table{{border-collapse:collapse;direction:{direction}}}td{{width:0;height:0;padding:0;border:20px solid green}}td:not(:first-child){{border-left-color:red}}tr:not(:first-child) td{{border-top-color:red}}</style><table><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></table>");
        let document=crate::html::parse(&markup,96).unwrap();let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        let list=display_list_with_styles(&document,120,120,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let table=crate::selector::query_selector(&document,document.root(),"table").unwrap().unwrap();
        let rect=geometry.hits.iter().find(|hit|hit.node==table).unwrap().rect;
        assert_eq!((rect.width,rect.height),(100.0,100.0));
        for (x,y) in [(1.0,1.0),(99.0,1.0),(1.0,99.0),(99.0,99.0)] {
            assert!(list.0.iter().any(|command|matches!(command,Command::FillRect{rect:paint,color}
                if color.a==255&&color.b==0&&color.g!=255&&paint.contains_rounded(rect.x+x,rect.y+y,0.0))),"{direction} corner {x},{y}");
        }
        if direction=="ltr" {
            assert!(!list.0.iter().any(|command|matches!(command,Command::FillRect{color,..} if color.r==255&&color.g==0&&color.b==0)),"top/left conflict winners stay green");
        }
    }
    let document=crate::html::parse("<style>html,body{margin:0}table{border-collapse:collapse}td{width:20px;height:20px;padding:0;border:3px solid green}tr:first-child td{border-bottom:7px solid blue}</style><table><tr><td></td><td></td></tr><tr></tr><tr><td></td><td></td></tr></table>",64).unwrap();
    let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
    let list=display_list_with_styles(&document,100,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
    for command in &list.0 {if let Command::FillRect{rect,..}=command {assert!(rect.is_valid());}}
    assert!(list.0.iter().any(|command|matches!(command,Command::FillRect{rect,color} if color.b==255&&color.r==0&&rect.height==7.0)));
    let table=crate::selector::query_selector(&document,document.root(),"table").unwrap().unwrap();
    let rect=geometry.hits.iter().find(|hit|hit.node==table).unwrap().rect;
    assert!(list.0.iter().any(|command|matches!(command,Command::FillRect{rect:paint,color}
        if color.g==128&&color.a==255&&paint.contains_rounded(rect.x+0.5,rect.y+0.5,0.0))));
}

#[test]
fn specification_collapsed_junction_patterns_visibility_and_retained_replay_use_shared_border_geometry() {
    for pattern in ["solid","dashed","double","groove"] {
        let markup=alloc::format!("<style>html,body{{margin:0}}#retained{{width:80px}}table{{border-collapse:collapse}}td{{padding:0;width:20px;height:20px;border:5px {pattern} green}}</style><div id=retained><table><tr><td></td></tr></table></div>");
        let document=crate::html::parse(&markup,64).unwrap();let rules=stylesheets(&document).unwrap();
        let table=crate::selector::query_selector(&document,document.root(),"table").unwrap().unwrap();
        let styles=core::cell::RefCell::default();let mut fragments=RetainedLayoutCache::default();let mut previous=None;
        for _frame in 0..2 {
            fragments.begin_frame();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_retained_layout(&document,100,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[],&styles,Some(&mut fragments)).unwrap();
            list.validate().unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==table).unwrap().rect;
            assert_eq!((rect.width,rect.height),(30.0,30.0));
            if pattern!="solid" {
                assert!(list.0.iter().any(|command|matches!(command,Command::StrokeBoxBorder(border)
                    if border.rect.width==5.0&&border.rect.height==5.0)),"{pattern} outer junction uses border renderer");
            }
            let hits=geometry.hits.iter().map(|hit|(hit.node,hit.rect)).collect::<Vec<_>>();
            if let Some((prior_list,prior_hits))=previous {assert_eq!(list,prior_list);assert_eq!(hits,prior_hits);assert!(fragments.stats().hits>0);}
            previous=Some((list,hits));
        }
    }
    for paint in ["color:transparent","visibility:hidden"] {
        let markup=alloc::format!("<style>html,body{{margin:0}}table{{border-collapse:collapse;position:relative;left:120px}}td{{padding:0;width:20px;height:20px;border:5px solid;{paint}}}</style><table><tr><td></td></tr></table>");
        let document=crate::html::parse(&markup,64).unwrap();let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        let list=display_list_with_styles(&document,100,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        assert!(geometry.scroll_extents.iter().any(|bounds|bounds.node==document.root()&&bounds.max_x>=50.0),"{paint} border geometry remains scrollable overflow");
        assert!(!list.0.iter().any(|command|matches!(command,Command::StrokeBoxBorder(_))));
        assert!(!list.0.iter().any(|command|matches!(command,Command::FillRect{color,rect} if color.a!=0&&rect.width<=30.0&&rect.height<=30.0)),"{paint} does not paint a junction");
    }
}

#[test]
fn specification_root_reverse_vertical_block_start_keeps_initial_containing_edge_and_overflow() {
    for width in ["auto","1600px"] {
        let markup=alloc::format!("<style>html{{writing-mode:vertical-rl;width:{width}}}#test{{position:absolute;top:5px;right:7px;margin:5px 7px;border:solid;border-width:5px 7px;padding:5px 7px;width:7px;height:5px}}#wide{{width:200vw}}</style><div id=test></div><div id=wide></div>");
        let document=crate::html::parse(&markup,64).unwrap();let mut rules=stylesheets(&document).unwrap();
        rules.environment.width=800.0;rules.environment.height=600.0;
        let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,800,600,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let html=crate::selector::query_selector(&document,document.root(),"html").unwrap().unwrap();
        let root_box=geometry.hits.iter().find(|hit|hit.node==html).unwrap().rect;
        assert_eq!(root_box.x+root_box.width,800.0,"{width} root block start");
        let test=crate::selector::query_selector(&document,document.root(),"#test").unwrap().unwrap();
        let target=geometry.hits.iter().find(|hit|hit.node==test).unwrap().rect;
        assert_eq!(target.x+target.width,786.0,"absolute target uses initial containing block");
        let bounds=geometry.scroll_extents.iter().find(|entry|entry.node==document.root()).unwrap();
        assert!(bounds.min_x<=-14.0,"root content must permit revealing the target border");
        assert_eq!(bounds.max_x,0.0);
    }
}

    #[test]
    fn specification_float_bfc_admission_uses_border_constraints_and_generated_box_sources() {
        for (declarations,x,y,width,height) in [
            ("width:50px;height:100px;margin-right:1px",50.0,0.0,50.0,100.0),
            ("width:50px;min-width:75px;height:100px",0.0,100.0,75.0,100.0),
            ("width:50px;height:100px;box-sizing:border-box;padding:5px;border:5px solid blue",50.0,0.0,50.0,100.0),
        ] {
            let markup=alloc::format!("<style>html,body{{margin:0}}main{{display:flow-root;width:100px;margin-top:100px}}</style><main><div style='float:left;width:50px;height:100px'></div><div style='display:flow-root;background:green;{declarations}'></div></main>");
            let boxes=colored_boxes_in(&markup,300,500);
            assert_eq!(boxes.len(),1,"{declarations}");
            assert_eq!((boxes[0].x,boxes[0].y,boxes[0].width,boxes[0].height),(x,y+100.0,width,height),"{declarations}");
        }
        let markup="<style>html,body{margin:0}main{display:flow-root;width:100px;margin-top:100px}#origin{display:contents}#origin::before{content:'';display:flow-root;width:50px;height:100px;margin-right:1px;background:green}</style><main><div style='float:left;width:50px;height:100px'></div><span id=origin></span></main>";
        let document=crate::html::parse(markup,64).unwrap();let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        let list=display_list_with_styles(&document,300,500,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
        let origin=crate::selector::query_selector(&document,document.root(),"#origin").unwrap().unwrap();
        let hit=geometry.hits.iter().find(|hit|hit.node==origin&&hit.pseudo==Some(css::PseudoElement::Before)).unwrap();
        assert_eq!(hit.rect,Rect{x:50.0,y:100.0,width:50.0,height:100.0},"generated BFC uses the same border-plane admission");
        assert!(list.0.iter().any(|command|matches!(command,Command::FillRect{rect,color} if color.g==128&&rect==&hit.rect)),"actual generated paint agrees with original pseudo identity");
    }

