    #[test]
    fn specification_clearing_forced_break_uses_matching_float_bottoms_and_paragraph_provenance() {
        assert_eq!(core::mem::size_of::<InlineForcedBreak>(),8);
        for nested in [false,true] { for (clear,top) in [("none",10.0),("left",37.0),("right",55.0),("both",55.0)] {
            let breaker=alloc::format!("<br style='clear:{clear}'>");
            let content=if nested {alloc::format!("<span>A{breaker}<i id=after style='display:inline-block;width:5px;height:10px;background:green'></i></span>")}
                else {alloc::format!("A{breaker}<i id=after style='display:inline-block;width:5px;height:10px;background:green'></i>")};
            let markup=alloc::format!("<style>html,body{{margin:0}}main{{width:100px;font:10px/10px monospace}}#left{{float:left;width:10px;height:30px;margin-bottom:7px}}#right{{float:right;width:10px;height:50px;margin-bottom:5px}}</style><main><i id=left></i><i id=right></i>{content}</main>");
            let document=crate::html::parse(&markup,96).unwrap();let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,120,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();list.validate().unwrap();
            let after=crate::selector::query_selector(&document,document.root(),"#after").unwrap().unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==after&&!hit.virtual_generated).unwrap().rect;
            assert_eq!(rect.y,top,"nested={nested},clear={clear}: clearance is next-line top, with the matching float's bottom margin once");
        } }
        // A later BFC does not inherit the outer float's clearing boundary.
        let markup="<style>html,body{margin:0}main{font:10px/10px monospace}#float{float:left;width:10px;height:80px}section{display:flow-root;width:80px}i{display:inline-block;width:5px;height:10px}</style><main><div id=float></div><section>A<br style='clear:both'><i id=after></i></section></main>";
        let (document,geometry)=intrinsic_keyword_geometry(markup);
        assert_eq!(intrinsic_keyword_rect(&document,&geometry,"#after").y,10.0);
    }

