    #[test]
    fn specification_ancestor_inline_alignment_owns_nested_text_and_fragment_geometry() {
        let text=RecordingText::default();
        for depth in [1,3,5] {for (alignment,child_alignment) in [
            ("super","baseline"),("sub","baseline"),("3px","baseline"),("25%","baseline"),
            ("middle","baseline"),("top","baseline"),("bottom","baseline"),
            ("top","3px"),("top","sub"),("top","super"),
            ("bottom","3px"),("bottom","sub"),("bottom","super"),
            ("super","3px"),("super","sub"),("super","super"),
        ] {
            let nested=alloc::format!("{}<span style='vertical-align:{child_alignment}'>f</span>{}",
                "<span>".repeat(depth),"</span>".repeat(depth));
            let source=alloc::format!("<style>html,body{{margin:0}}main{{font:16px/20px monospace}}#aligned{{vertical-align:{alignment};background:red}}#after{{color:blue}}</style><main>of<span id=aligned>{nested}</span><span id=after>ice</span></main>");
            let reference=source.replace("<span id=aligned>","<span id=aligned style='display:inline-block'>");
            let positions=|list:&DisplayList| {
                let mut values=list.0.iter().flat_map(|command|match command {
                    Command::GlyphRun{origin_x,baseline_y,size,color,glyphs}=>glyphs.iter().map(|glyph|
                        (glyph.id,*origin_x+glyph.x,*baseline_y+glyph.y,*size,[color.r,color.g,color.b,color.a])).collect::<Vec<_>>(),
                    _=>Vec::new(),
                }).collect::<Vec<_>>();
                values.sort_by(|a,b|a.1.total_cmp(&b.1).then(a.2.total_cmp(&b.2)).then(a.0.cmp(&b.0)));
                values
            };
            let document=crate::html::parse(&source,128).unwrap();
            let aligned=crate::selector::query_selector(&document,document.root(),"#aligned").unwrap().unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let actual=session.display_list(160,120,&text).unwrap().clone();
            let expected_document=crate::html::parse(&reference,128).unwrap();
            let expected=display_list(&expected_document,160,120,&text).unwrap();
            assert_eq!(positions(&actual),positions(&expected),"ancestor owns nested anonymous text once: {depth}/{alignment}/{child_alignment}");
            let fragments=session.client_rects(aligned);
            assert_eq!(fragments.len(),1,"one real aligned inline fragment");
            let painted=actual.0.iter().find_map(|command|match command {
                Command::FillRect{rect,color} if color.r==255 && color.g==0 && color.b==0=>Some(*rect),_=>None,
            }).unwrap();
            assert_eq!(fragments[0],painted,"paint and hit use the same frame baseline: {depth}/{alignment}/{child_alignment}");
            assert_eq!(actual,session.display_list(160,120,&text).unwrap().clone(),"warm aligned frame");
            assert_eq!(actual,display_list(session.document(),160,120,&text).unwrap(),"fresh aligned frame");
        }}
    }

    #[test]
    fn specification_nested_atomic_inline_group_keeps_outer_open_line_and_sibling_alignment() {
        for alignment in ["left","center","right"] {
            let mut reference=None;
            for effect in ["none","invert(0)","invert()"] {
                let markup=alloc::format!("<style>html,body{{margin:0}}main{{width:80px;font:10px/12px monospace;text-align:{alignment}}}#host{{filter:{effect};color:red}}#atom{{display:inline-block;width:24px;text-align:left}}#inner{{filter:invert(0)}}#sibling{{color:blue}}</style><main><span id=host>AA<span id=atom><span id=inner>AA AA</span></span>AA</span><span id=sibling>BB</span></main>");
                let document=crate::html::parse(&markup,128).unwrap();
                let nodes=["#host","#atom","#inner","#sibling"].map(|selector|
                    crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap());
                let mut session=crate::session::RenderSession::new(document);let text=RecordingText::default();
                let list=session.display_list(80,100,&text).unwrap().clone();list.validate().unwrap();
                let rects=nodes.map(|node|session.client_rects(node).to_vec());
                assert!(rects[2].len()>=2,"inner atomic source genuinely wraps: {alignment}/{effect}");
                let mut positions=list.0.iter().filter_map(|command|match command {
                    Command::GlyphRun{origin_x,baseline_y,size,color,glyphs}=>
                        Some((*origin_x,*baseline_y,*size,[color.r,color.g,color.b,color.a],glyphs.clone())),_=>None,
                }).collect::<Vec<_>>();
                // Stacking adoption may move the following sibling before the
                // complete filtered group. Compare source glyphs and geometry,
                // independently of that correct phase ordering.
                positions.sort_by(|a,b|a.0.total_cmp(&b.0).then(a.1.total_cmp(&b.1))
                    .then(a.2.total_cmp(&b.2)).then(a.3.cmp(&b.3)));
                if let Some(reference)=&reference {assert_eq!(&(rects,positions),reference,
                    "inner adoption preserves all outer atomic source ink before final open-line alignment: {alignment}/{effect}");}
                else {reference=Some((rects,positions));}
                assert_eq!(list,session.display_list(80,100,&text).unwrap().clone());
                assert_eq!(list,display_list(session.document(),80,100,&text).unwrap());
            }
        }
    }

    #[test]
    fn specification_inline_opacity_keeps_block_child_surfaces_in_one_source() {
        for nested in [false,true] {for filtered in [false,true] {
            let inner=if nested {"<span style='opacity:.25;background:lime'>"}else{""};
            let close=if nested {"</span>"}else{""};
            let filter=if filtered {"filter:invert(0);"}else{""};
            let markup=alloc::format!("<style>html,body{{margin:0}}#host{{display:inline;opacity:.5;background:red;{filter}}}#child{{width:4px;height:4px;background:blue}}#sibling{{width:4px;height:4px;background:magenta}}</style><div id=host>{inner}<div id=child></div>{close}</div><div id=sibling></div>");
            let document=crate::html::parse(&markup,64).unwrap();let text=RecordingText::default();
            let mut session=crate::session::RenderSession::new(document);
            let list=session.display_list(20,40,&text).unwrap().clone();list.validate().unwrap();
            let mut layers=Vec::new();let mut half=0;let mut red=0;let mut blue=0;let mut sibling=0;
            for command in &list.0 {match command {
                Command::PushLayer{opacity,..}=>{layers.push(*opacity);half+=usize::from(*opacity==0.5);},
                Command::PopLayer=>{layers.pop().unwrap();},
                Command::FillRect{color,..} if color.r==255&&color.g==0&&color.b==0=>{red+=1;assert!(layers.contains(&0.5));},
                Command::FillRect{color,..} if color.r==0&&color.g==0&&color.b==255=>{blue+=1;assert!(layers.contains(&0.5),"block child remains inside actual inline group");if nested{assert!(layers.contains(&0.25));}},
                Command::FillRect{color,..} if color.r==255&&color.g==0&&color.b==255=>{sibling+=1;assert!(!layers.contains(&0.5));},_=>{}
            }}
            assert_eq!((half,red,blue,sibling),(1,1,1,1),"one owner composites its complete source once");assert!(layers.is_empty());
            assert_eq!(list,session.display_list(20,40,&text).unwrap().clone());
            assert_eq!(list,display_list(session.document(),20,40,&text).unwrap());
        }}
    }

    #[test]
    fn specification_wrapped_spatial_source_captures_only_owned_offscreen_ink() {
        let markup="<style>html,body{margin:0}main{width:24px;padding-top:50px;font:10px/12px monospace}#host{color:red;filter:blur(20px)}#sibling{color:blue}</style><main><span id=host>AA AA</span><span id=sibling>BB BB BB BB</span></main>";
        let document=crate::html::parse(markup,128).unwrap();let text=RecordingText::default();let rules=stylesheets(&document).unwrap();
        for collect_geometry in [false,true] {
            let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,24,10,&text,&rules,None,
                collect_geometry.then_some(&mut geometry),&[]).unwrap();list.validate().unwrap();
            let mut host=0;let mut sibling=0;
            for command in &list.0 {if let Command::GlyphRun{color,..}=command {
                if color.r==255&&color.b==0 {host+=1;}
                if color.r==0&&color.b==255 {sibling+=1;}
            }}
            assert!(host>0,"offscreen source contributes blur ink; geometry={collect_geometry}");
            assert_eq!(sibling,0,"unrelated offscreen sibling retains ordinary paint culling; geometry={collect_geometry}");
        }
    }

    #[test]
    fn specification_wrapped_inline_group_preserves_real_fragment_geometry_and_paint_ownership() {
        for mode in ["horizontal-tb","vertical-rl","vertical-lr","sideways-rl","sideways-lr"] {
        for alignment in ["left","center","right"] {for nested in [false,true] {
            let mut reference=None;
            for effect in ["none","invert(0)","invert()"] {
                let inner=if nested {"<span style='filter:invert(0)'>AA</span>"}else{"AA"};
                let markup=alloc::format!("<style>html,body{{margin:0}}main{{width:24px;height:24px;writing-mode:{mode};font:10px/12px monospace;text-align:{alignment}}}#host{{color:red;background:magenta;filter:{effect}}}#sibling{{color:blue}}</style><main><span id=host>AA AA {inner} AA</span><span id=sibling>BB BB</span></main>");
                let document=crate::html::parse(&markup,128).unwrap();
                let host=crate::selector::query_selector(&document,document.root(),"#host").unwrap().unwrap();
                let sibling=crate::selector::query_selector(&document,document.root(),"#sibling").unwrap().unwrap();
                let mut session=crate::session::RenderSession::new(document);let text=RecordingText::default();
                let list=session.display_list(80,160,&text).unwrap().clone();list.validate().unwrap();
                let rects=(session.client_rects(host).to_vec(),session.client_rects(sibling).to_vec());
                assert!(rects.0.len()>=2,"actual host wraps: {alignment}/{nested}/{effect}");
                if let Some(reference)=&reference {assert_eq!(&rects,reference,"filter does not alter ordinary font/content fragments or following sibling placement: {alignment}/{nested}/{effect}");}
                else {reference=Some(rects);}
                let layers=list.0.iter().filter(|command|matches!(command,Command::PushLayer{filters:Some(_),..})).count();
                assert_eq!(layers,usize::from(effect!="none")+usize::from(nested),"one group per actual owner, not per line");
                assert_eq!(list,session.display_list(80,160,&text).unwrap().clone(),"warm source ownership");
                assert_eq!(list,display_list(session.document(),80,160,&text).unwrap(),"fresh source ownership");
                let mut groups=0;let mut stack=Vec::new();
                for command in &list.0 {match command {
                    Command::PushLayer{filters,..}=>{stack.push(filters.is_some());groups+=usize::from(filters.is_some());},
                    Command::PopLayer=>{groups-=usize::from(stack.pop().unwrap());},
                    Command::GlyphRun{color,..} if color.r==255 && color.b==0=>assert!(effect=="none"||groups>0,"every host text fragment belongs to its one filter"),
                    Command::GlyphRun{color,..} if color.b==255 && color.r==0=>assert_eq!(groups,0,"following sibling ink stays outside the inline source"),_=>{}
                }}assert!(stack.is_empty());
                session.document_mut().set_attribute(host,"style","filter:invert(0);padding-left:2px;padding-right:3px").unwrap();
                let mutated=session.display_list(80,160,&text).unwrap().clone();
                assert_eq!(mutated,display_list(session.document(),80,160,&text).unwrap(),"changed used edges recreate one owner from actual fragments");
            }
        }}}
    }

    #[test]
    fn specification_float_outer_height_counts_margins_once_and_ignores_degenerate_bands() {
        for side in [Float::Left,Float::Right] {
            for extent in [0.0,-5.0] {
                let band=Rect{x:20.0,y:10.0,width:40.0,height:extent};
                assert_eq!(float_edges([(band,side)],0.0,100.0,0.0,20.0),(0.0,100.0),
                    "zero/negative outer height cannot shorten a line crossing its top");
            }
            let band=Rect{x:20.0,y:10.0,width:40.0,height:5.0};
            assert_eq!(float_edges([(band,side)],0.0,100.0,0.0,20.0),
                if side==Float::Left {(60.0,40.0)} else {(0.0,20.0)});
        }
        let markup="<!doctype html><style>html,body{margin:0}main{margin-top:8px;font:16px/16px monospace}#float{float:left;width:20px;height:20px;margin-top:10px;margin-bottom:-20px;background:red}p{margin:40px 0 0;clear:left}</style><main id=parent><div id=float></div><p id=line>X</p></main>";
        let document=crate::html::parse(markup,64).unwrap();let mut geometry=LayoutGeometry::default();let rules=stylesheets(&document).unwrap();
        let list=display_list_with_styles(&document,100,120,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        for (selector,top) in [("#parent",8.0),("#float",18.0),("#line",40.0)] {
            let node=crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
            assert_eq!(geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect.y,top,
                "positive outer height is 20+10-20, never 20+2*(10-20): {selector}");
        }
        assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{origin_x,baseline_y,..}
            if *origin_x==0.0 && *baseline_y==50.0)),"real clearance uses the actual margin edge");
    }

