            assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{origin_x,baseline_y,..} if *origin_x==20.0 && *baseline_y==top+10.0)),"the line must avoid the float at the admitted origin, rather than being shifted after line breaking");
