let markup="<style>html,body{margin:0}body{display:flow-root}#earlier{float:right;width:70px;height:50px}main{margin-top:20px;font:16px/16px monospace}#float{float:left;width:50px;height:0}p{margin:30px 0 0;clear:left}</style><div id=earlier></div><main id=parent><div id=float></div><p id=line>X</p></main>";
