for (selector,top) in [("#parent",20.0),("#float",50.0),("#line",50.0)] {
    let node=crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
    assert_eq!(geometry.hits.iter().find(|hit|hit.node==node).unwrap().rect.y,top,"opposite collision {selector}");
}
        // An earlier BFC float remains in the occupancy solver. The new float
