    #[test]
    fn specification_computed_parent_preserves_query_percentage_through_used_layout() {
        for (expression, computed) in [
            ("calc(10cqw + 10%)", "calc(30px + 10%)"),
            ("min(calc(10cqw + 10%), 70px)", "min(calc(30px + 10%), 70px)"),
            ("clamp(20px, calc(10cqw + 10%), 60px)", "clamp(20px, calc(30px + 10%), 60px)"),
        ] {
            let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}#outer{{width:300px;container-type:inline-size}}#parent{{width:200px;container-type:inline-size;margin:{expression};padding:{expression};background:blue}}#child{{width:50px;container-type:inline-size;margin:inherit;padding:inherit;background:green}}#leaf{{width:20px;height:10px;margin:inherit;padding:inherit;background:black}}</style><div id=outer><div id=parent><div id=child><div id=leaf></div></div></div></div>");
            let reference = markup.replace("margin:inherit;padding:inherit",
                &alloc::format!("margin:{computed};padding:{computed}"));
            let document = crate::html::parse(&markup, 96).unwrap();
            let reference = crate::html::parse(&reference, 96).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            let actual = display_list_with_styles(&document, 600, 600, &NoShape, &rules,
                None, Some(&mut geometry), &[]).unwrap();
            assert_eq!(actual, display_list(&reference, 600, 600, &NoShape).unwrap(),
                "{expression}: inheritance freezes the declaring query, not its used percentage");
            for (selector, width) in [("#child", 150.0), ("#leaf", 90.0)] {
                let node = crate::selector::query_selector(&document, document.root(), selector).unwrap().unwrap();
                let rect = geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap().rect;
                assert_eq!(rect.width, width, "{expression}, {selector}: each descendant's own containing width resolves its inherited percentage");
            }
            let mut session = crate::session::RenderSession::new(document);
            let first = session.display_list(600, 600, &NoShape).unwrap().clone();
            session.set_canvas_background(None);
            session.set_canvas_background(Some(Rgba { r: 255, g: 255, b: 255, a: 255 }));
            assert_eq!(session.display_list(600, 600, &NoShape).unwrap(), &first,
                "computed parent contexts survive retained layout replay");
        }
    }

    #[test]
    fn specification_clearance_uses_complete_adjoining_top_before_testing_float_bottom() {
        for (margins, prefix) in [
            ("margin-top:0", ""),
            ("margin-top:80px", ""),
            ("margin-top:0", "<div style='margin-top:70px;margin-bottom:-20px'></div>"),
        ] {
            for (float_height, expected) in [(50, 50.0), (70, 70.0)] {
                let child_margin = if margins.contains("80px") { -30 } else { 50 };
                let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}body{{display:flow-root}}#float{{float:left;width:100px;height:{float_height}px;background:green}}#cleared{{clear:left;{margins}}}#child{{margin-top:{child_margin}px;height:50px;width:100px;background:green}}</style><div id=float></div><div id=cleared>{prefix}<div id=child></div></div>");
                let document = crate::html::parse(&markup, 96).unwrap();
                let mut geometry = LayoutGeometry::default();
                let rules = stylesheets(&document).unwrap();
                let list = display_list_with_styles(&document, 200, 200, &NoShape, &rules,
                    None, Some(&mut geometry), &[]).unwrap();
                for selector in ["#cleared", "#child"] {
                    let node = crate::selector::query_selector(&document, document.root(), selector).unwrap().unwrap();
                    let rect = geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap().rect;
                    assert_eq!(rect.y, expected, "{margins}, prefix={prefix}, float={float_height}, {selector}: clearance does not add the child chain twice");
                }
                assert!(list.0.iter().any(|command| matches!(command, Command::FillRect { rect, color }
                    if rect.y == expected && rect.height == 50.0 && color.g == 128 && color.r == 0)),
                    "the admitted background starts at the actual border edge");
                let mut session = crate::session::RenderSession::new(document);
                for canvas in [None, Some(Rgba { r: 1, g: 2, b: 3, a: 255 })] {
                    session.set_canvas_background(canvas);
                    let cached = session.display_list(200, 200, &NoShape).unwrap().clone();
                    let rules = stylesheets(session.document()).unwrap();
                    let fresh = display_list_with_retained_layout_and_root(session.document(), 200, 200,
                        &NoShape, &rules, None, None, &[], &RefCell::new(css::StyleCache::default()),
                        None, None, canvas).unwrap();
                    assert_eq!(cached, fresh, "clearance admission survives retained/fresh rendering");
                }
            }
        }
        // New child formatting contexts still donate their own top margin;
        // their content margins remain isolated on the other side of the BFC.
        for display in ["flow-root", "table", "flex", "grid"] {
            let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}body{{display:flow-root}}#float{{float:left;width:100px;height:50px}}#cleared{{clear:left}}#child{{display:{display};margin-top:50px;height:50px;width:100px}}</style><div id=float></div><div id=cleared><div id=child></div></div>");
            let document = crate::html::parse(&markup, 64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document, 200, 200, &NoShape, &rules, None, Some(&mut geometry), &[]).unwrap();
            for selector in ["#cleared", "#child"] {
                let node = crate::selector::query_selector(&document, document.root(), selector).unwrap().unwrap();
                assert_eq!(geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap().rect.y,
                    50.0, "{display}: the child's own margin precedes clearance testing");
            }
        }
        // An intervening border prevents the descendant's margin from being
        // part of the cleared box's hypothetical border position.
        let document = crate::html::parse("<!doctype html><style>html,body{margin:0}body{display:flow-root}#float{float:left;width:100px;height:70px}#cleared{clear:left;border-top:1px solid transparent}#child{margin-top:50px;height:20px}</style><div id=float></div><div id=cleared><div id=child></div></div>", 64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(&document, 200, 200, &NoShape, &rules, None, Some(&mut geometry), &[]).unwrap();
        for (selector, expected) in [("#cleared",70.0),("#child",121.0)] {
            let node = crate::selector::query_selector(&document, document.root(), selector).unwrap().unwrap();
            assert_eq!(geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap().rect.y, expected);
        }
    }

