    #[test]
    fn specification_html_root_box_uses_viewport_basis_actual_edges_and_constraints() {
        for (constraint, content_width) in [("", 100.0), ("display:contents", 100.0), ("max-width:80px", 80.0), ("min-width:120px;max-width:80px", 120.0)] {
            let markup = alloc::format!("<style>html{{width:50%;height:300%;margin:10px;padding:5%;border:2px solid transparent;{constraint}}}body{{margin:0;width:100%;height:50%}}</style>");
            let document = crate::html::parse(&markup, 64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document, 200, 100, &FixedText, &rules, None, Some(&mut geometry), &[]).unwrap();
            let html = crate::selector::document_element(&document).unwrap();
            let body = crate::selector::query_selector(&document, document.root(), "body").unwrap().unwrap();
            let rect = |node| geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap().rect;
            assert_eq!(rect(html), Rect { x:10.0,y:10.0,width:content_width+24.0,height:324.0 });
            assert_eq!(rect(body), Rect { x:22.0,y:22.0,width:content_width,height:150.0 });
            assert_eq!(geometry.scroll_extents.iter().find(|bounds| bounds.node == document.root()).unwrap().max_y, 244.0);
        }
        let document = crate::html::parse("<style>html{width:100px;margin:0 auto}body{margin:0;height:50px}</style>",64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(&document,200,100,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
        let html = crate::selector::document_element(&document).unwrap();
        let hit = geometry.hits.iter().find(|hit|hit.node==html).unwrap();
        assert_eq!(hit.rect,Rect{x:50.0,y:0.0,width:100.0,height:50.0});
        assert_eq!(geometry.used_margins_for(html).unwrap(),[0.0,50.0,0.0,50.0]);
        let document=crate::html::parse("<style>html{margin:0;height:300vh}body{margin:0}</style>",64).unwrap();
        let mut rules=stylesheets(&document).unwrap();rules.environment.width=100.0;rules.environment.height=100.0;
        let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,100,100,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
        let html=crate::selector::document_element(&document).unwrap();
        assert_eq!(geometry.hits.iter().find(|hit|hit.node==html).unwrap().rect.height,300.0);
        assert_eq!(geometry.scroll_extents.iter().find(|bounds|bounds.node==document.root()).unwrap().max_y,200.0);
    }

    #[test]
    fn specification_html_canvas_background_keeps_root_anchor_box_shadows_and_replay() {
        for source in ["html", "body"] {
            let markup = alloc::format!("<style>html{{width:100px;height:120px;margin:10px;padding:5px;border:2px solid transparent;transform:translate(20px,30px);box-shadow:3px 4px 0 green}}body{{margin:20px;height:20px;box-shadow:1px 2px 0 black}}{source}{{background:linear-gradient(red,blue) no-repeat}}</style>");
            let document = crate::html::parse(&markup, 64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let html = crate::selector::document_element(&document).unwrap();
            let styles = core::cell::RefCell::default();
            let mut fragments = RetainedLayoutCache::default();
            let mut previous = None;
            for _frame in 0..2 {
                fragments.begin_frame();
                let mut geometry = LayoutGeometry::default();
                let list = display_list_with_retained_layout(&document,200,200,&FixedText,&rules,None,Some(&mut geometry),&[],&styles,Some(&mut fragments)).unwrap();
                let (background_index, fill) = list.0.iter().enumerate().find_map(|(index,command)|match command{Command::FillBackground(fill)=>Some((index,fill)),_=>None}).unwrap();
                assert_eq!(fill.rect,Rect{x:0.0,y:0.0,width:200.0,height:200.0});
                assert_eq!(fill.positioning_rect,Rect{x:12.0,y:12.0,width:110.0,height:130.0});
                assert_eq!(list.0.iter().filter(|command|matches!(command,Command::FillBackground(_))).count(),1,"propagated source background is not painted twice");
                let transform_index=list.0.iter().position(|command|matches!(command,Command::PushTransform(_))).unwrap();
                let Command::PushTransform(matrix)=list.0[transform_index] else { unreachable!() };
                assert!(background_index<transform_index,"propagated canvas paint precedes the root transform");
                assert_eq!((matrix.e,matrix.f),(20.0,30.0),"root content still has its authored transform");
                let shadows=list.0.iter().filter_map(|command|match command{Command::BoxShadow{rect,..}=>Some(*rect),_=>None}).collect::<Vec<_>>();
                assert_eq!(shadows.len(),2);
                assert!(shadows.contains(&Rect{x:10.0,y:10.0,width:114.0,height:134.0}));
                assert!(shadows.contains(&Rect{x:37.0,y:37.0,width:60.0,height:20.0}));
                let (index,hit)=geometry.hits.iter().enumerate().find(|(_,hit)|hit.node==html).unwrap();
                assert_eq!(transformed_bounds(hit.rect,geometry.transforms.iter().filter(|transform|transform.hits.contains(&index)).map(|transform|transform.matrix)).unwrap(),Rect{x:30.0,y:40.0,width:114.0,height:134.0});
                if let Some(previous)=previous {assert_eq!(list,previous,"fresh transformed-root layout preserves canvas anchoring and physical commands");}
                previous=Some(list);
            }
            let list=display_list_with_styles(&document,200,200,&FixedText,&rules,None,None,&[]).unwrap();
            let fill=list.0.iter().find_map(|command|match command{Command::FillBackground(fill)=>Some(fill),_=>None}).unwrap();
            assert_eq!(fill.positioning_rect,Rect{x:12.0,y:12.0,width:110.0,height:130.0},"canvas anchoring also works without hit collection");
        }
    }

    #[test]
    fn specification_html_canvas_background_preserves_eligible_descendant_retained_replay() {
        for source in ["html", "body"] {
            let markup=alloc::format!("<style>html{{margin:10px;width:100px;height:120px}}body{{margin:0}}{source}{{background:linear-gradient(red,blue) no-repeat}}#retained{{height:20px;background:green}}</style><div id=retained></div>");
            let document=crate::html::parse(&markup,64).unwrap();let rules=stylesheets(&document).unwrap();
            let styles=core::cell::RefCell::default();let mut fragments=RetainedLayoutCache::default();let mut previous=None;
            for _frame in 0..2 {
                fragments.begin_frame();let mut geometry=LayoutGeometry::default();
                let list=display_list_with_retained_layout(&document,200,200,&FixedText,&rules,None,Some(&mut geometry),&[],&styles,Some(&mut fragments)).unwrap();
                let fill=list.0.iter().find_map(|command|match command{Command::FillBackground(fill)=>Some(fill),_=>None}).unwrap();
                assert_eq!(fill.positioning_rect,Rect{x:10.0,y:10.0,width:100.0,height:120.0});
                assert_eq!(fill.rect,Rect{x:0.0,y:0.0,width:200.0,height:200.0});
                if let Some((prior_list,prior_geometry))=previous {
                    assert_eq!(list,prior_list);assert_eq!(geometry.hits.iter().map(|hit|(hit.node,hit.rect)).collect::<Vec<_>>(),prior_geometry);
                    assert!(fragments.stats().hits>0,"an ordinary block descendant must actually replay from the retained cache");
                }
                previous=Some((list,geometry.hits.iter().map(|hit|(hit.node,hit.rect)).collect::<Vec<_>>()));
            }
        }
    }

    #[test]
    fn specification_html_canvas_ignores_source_transforms_and_containment_gates_body() {
        for source in ["html","body"] {
            for transform in ["scale(.5)","scale(-1)","rotate(30deg)","scale(0)"] {
                let markup=alloc::format!("<style>html{{margin:10px;width:80px;height:120px;transform-origin:0 0;transform:{transform}}}body{{margin:4px;width:30px;height:40px;transform:translate(20px,30px)}}{source}{{background:linear-gradient(red,blue)}}</style><div style='width:10px;height:10px;background:green'></div>");
                let document=crate::html::parse(&markup,64).unwrap();
                let list=display_list(&document,100,100,&FixedText).unwrap();
                list.validate().unwrap();
                let transform_index=list.0.iter().position(|command|matches!(command,Command::PushTransform(_))).unwrap();
                let (background_index,fill)=list.0.iter().enumerate().find_map(|(index,command)|match command{Command::FillBackground(fill)=>Some((index,fill)),_=>None}).unwrap();
                assert!(background_index<transform_index,"{source} canvas paint is independent of both source and root transforms");
                assert_eq!(fill.positioning_rect,Rect{x:10.0,y:10.0,width:80.0,height:120.0},"{source} image sizing remains anchored to the untransformed root box");
                assert_eq!(fill.rect,Rect{x:0.0,y:0.0,width:100.0,height:100.0},"{source} canvas coverage remains the viewport, including singular root transforms");
                assert_eq!(list.0.iter().filter(|command|matches!(command,Command::FillBackground(_))).count(),1,"{source} propagated background is never painted again on its source box");
            }
        }
        for owner in ["html", "body"] {
            for containment in ["none", "size", "layout", "style", "paint"] {
                let markup=alloc::format!("<style>html{{margin:0;height:200px}}body{{margin:0;width:80px;height:30px;overflow:auto;background:linear-gradient(red,blue)}}{owner}{{contain:{containment}}}</style><div style='height:300px'></div>");
                let document=crate::html::parse(&markup,64).unwrap();
                let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
                let list=display_list_with_styles(&document,100,100,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
                let body=crate::selector::query_selector(&document,document.root(),"body").unwrap().unwrap();
                assert_eq!(geometry.scroll_ports.iter().any(|port|port.node==body),containment!="none","{owner} {containment}");
                let fill=list.0.iter().find_map(|command|match command{Command::FillBackground(fill)=>Some(fill),_=>None}).unwrap();
                assert_eq!(fill.positioning_rect.width,if containment=="none"{100.0}else{80.0},"{owner} {containment}");
                assert_eq!(fill.rect.height,if containment=="none"{100.0}else{30.0},"BODY background stays on its own box when propagation is disabled");
            }
        }
    }

    #[test]
    fn specification_html_viewport_overflow_propagation_keeps_authored_style_and_real_ports() {
        for root_overflow in ["visible", "hidden", "clip"] {
            let markup=alloc::format!("<style>html{{margin:0;height:200px;overflow:{root_overflow}}}body{{margin:0;width:80px;height:30px;overflow:auto}}#inner{{width:20px;height:20px;overflow:auto}}</style><div id=inner><div style='height:60px'></div></div><div style='height:280px'></div>");
            let document=crate::html::parse(&markup,64).unwrap();let rules=stylesheets(&document).unwrap();
            let html=crate::selector::document_element(&document).unwrap();
            let body=crate::selector::query_selector(&document,document.root(),"body").unwrap().unwrap();
            let inner=crate::selector::query_selector(&document,document.root(),"#inner").unwrap().unwrap();
            let styles=core::cell::RefCell::default();let mut geometry=LayoutGeometry::default();
            display_list_with_retained_layout(&document,100,100,&FixedText,&rules,None,Some(&mut geometry),&[],&styles,None).unwrap();
            assert!(!geometry.scroll_ports.iter().any(|port|port.node==html));
            assert_eq!(geometry.scroll_ports.iter().any(|port|port.node==body),root_overflow!="visible");
            assert!(geometry.scroll_ports.iter().any(|port|port.node==inner));
            assert_eq!(geometry.scroll_extents.iter().find(|bounds|bounds.node==inner).unwrap().max_y,40.0);
            assert_eq!(geometry.scroll_extents.iter().find(|bounds|bounds.node==document.root()).unwrap().max_y,if root_overflow=="visible"{200.0}else{100.0},"viewport clip has hidden programmatic scrolling behavior");
            let authored=css::compute_node_cached_with_text(&document,html,None,&rules,&mut styles.borrow_mut(),&FixedText).unwrap();
            assert_eq!(authored.overflow_y,match root_overflow{"visible"=>css::Overflow::Visible,"hidden"=>css::Overflow::Hidden,_=>css::Overflow::Clip});
        }
    }

    #[test]
    fn specification_html_viewport_propagation_skips_hidden_body_and_preserves_element_clip() {
        let mut document=crate::html::parse("<style>html{margin:0;height:200px}body{display:none;overflow:clip}#shown{display:block;margin:0;height:30px;overflow:auto}#clipped{height:20px;overflow:clip}</style><div></div>",64).unwrap();
        let html=crate::selector::document_element(&document).unwrap();
        let shown=document.create_unprefixed_element(Namespace::Html,"body".into(),Vec::new()).unwrap();document.set_attribute(shown,"id","shown").unwrap();document.append(html,shown).unwrap();
        let clipped=document.create_unprefixed_element(Namespace::Html,"div".into(),Vec::new()).unwrap();document.set_attribute(clipped,"id","clipped").unwrap();document.append(shown,clipped).unwrap();
        let tall=document.create_unprefixed_element(Namespace::Html,"div".into(),Vec::new()).unwrap();document.set_attribute(tall,"style","height:300px").unwrap();document.append(clipped,tall).unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,100,100,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
        assert!(!geometry.scroll_ports.iter().any(|port|port.node==shown),"the first displayed BODY propagates its overflow");
        assert!(!geometry.scroll_extents.iter().any(|bounds|bounds.node==clipped),"ordinary element clip does not permit scrolling");
        assert_eq!(geometry.scroll_extents.iter().find(|bounds|bounds.node==document.root()).unwrap().max_y,100.0);
    }

