            let parent=crate::selector::query_selector(&document,document.root(),"#parent").unwrap().unwrap();let empty=crate::selector::query_selector(&document,document.root(),"#empty").unwrap().unwrap();let next=crate::selector::query_selector(&document,document.root(),"#next").unwrap().unwrap();
            let rect=|node|geometry.hits.iter().find(|hit|hit.node==node).unwrap().rect;
            assert_eq!(rect(parent).y,expected_top);assert_eq!(rect(parent).height,16.0);
            assert_eq!(rect(empty).y,expected_top,"leading empty edges coincide with parent border edge");
