    #[test]
    fn specification_rendered_text_actual_boxes_wrap_transform_offscreen_and_replay() {
        for (content, style, expected) in [
            ("ab cd", "width:6px", "ab cd"),
            ("Maß", "text-transform:uppercase", "MASS"),
            ("a  \n b\n\n", "white-space:pre-line", "a\nb\n\n"),
        ] {
            let markup = alloc::format!("<!doctype html><style>body{{margin:0}}</style><div style='height:200px'></div><p id='target' style='{style}'>{content}</p>");
            let document = crate::html::parse(&markup, 64).unwrap();
            let target = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
            let source = document.first_child(target).unwrap().unwrap();
            let mut session = crate::session::RenderSession::new(document);
            session.request_rendered_text_boxes();
            session.display_list(100, 20, &FixedText).unwrap();
            assert_eq!(crate::rendered_text::get(&mut session, target).unwrap(), expected, "{style}");
            assert!(session.rendered_text_boxes().unwrap().iter().any(|record| record.node == source));
            assert!(matches!(session.document().kind(source), Ok(NodeKind::Text(value)) if value == content));
            session.finish_rendered_text_boxes();
        }

        let document = crate::html::parse("<!doctype html><style>body{margin:0}p{height:10px}</style><p id='changed'>one</p><p id='target'>two three</p><p>four</p>", 64).unwrap();
        let target = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
        let changed = crate::selector::query_selector(&document, document.root(), "#changed").unwrap().unwrap();
        let changed_text = document.first_child(changed).unwrap().unwrap();
        let mut session = crate::session::RenderSession::new(document);
        session.request_rendered_text_boxes();
        session.display_list(100, 100, &FixedText).unwrap();
        assert_eq!(crate::rendered_text::get(&mut session, target).unwrap(), "two three");
        session.document_mut().replace_data(changed_text, "changed").unwrap();
        session.display_list(100, 100, &FixedText).unwrap();
        assert!(session.layout_cache_stats().hits >= 2, "unchanged fragments must replay their actual text boxes");
        assert_eq!(crate::rendered_text::get(&mut session, target).unwrap(), "two three");
        session.finish_rendered_text_boxes();
    }

