    #[test]
    fn specification_text_decoration_retained_expression_heap_budget() {
        let document=crate::html::parse("<main id=t style='text-decoration-thickness:min(2em,25%);text-underline-offset:clamp(-2em,calc(1em + 50%),3em)'>A</main>",32).unwrap();
        let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();
        let style=css::compute_node(&document,node,None,&rules).unwrap();
        let thickness=style.text_decoration_thickness.retained_bytes().unwrap();
        let offset=style.text_underline_offset.retained_bytes().unwrap();
        assert!(thickness>core::mem::size_of::<css::DecorationLength>());
        assert!(offset>thickness,"boxed clamp operands and nested calc/sum storage are charged");
        let ast_bytes=thickness.checked_add(offset).unwrap();
        let mut bytes=0;
        add_style_payload_bytes(&mut bytes,&style).unwrap();
        assert!(bytes>=ast_bytes,"both ASTs and retained original relative sources are charged");
        let expected=bytes;
        add_style_payload_bytes(&mut bytes,&style.clone()).unwrap();
        assert_eq!(bytes,expected*2,"shared AST references are conservatively charged for each retained style origin");
        let mut bytes=MAX_RETAINED_FRAGMENT_BYTES-expected;
        assert!(add_style_payload_bytes(&mut bytes,&style).is_some());
        assert_eq!(bytes,MAX_RETAINED_FRAGMENT_BYTES);
        assert!(add_style_payload_bytes(&mut bytes,&style).is_none(),"nested expression heap cannot bypass cache admission cap");
        assert_eq!(css::DecorationLength::Auto.retained_bytes(),Some(0));
    }

    #[test]
    fn specification_retained_style_budget_charges_nested_image_and_generated_payloads() {
        let mut style=Style::initial();
        let base=checked_style_retained_bytes(&style).unwrap();
        let raw:Arc<str>=Arc::from("shared-image.css");
        style.background_images=Some(alloc::vec![crate::paint::BackgroundImage::CrossFade(alloc::vec![
            (crate::paint::BackgroundImage::Url(raw.clone()),0.5),
            (crate::paint::BackgroundImage::Url(raw.clone()),0.5),
        ].into())].into());
        style.generated_content=Some(alloc::vec![css::GeneratedContentItem::AlternativeText(
            alloc::vec![css::GeneratedContentItem::String(raw.clone())].into())].into());
        let charged=checked_style_retained_bytes(&style).unwrap();
        assert!(charged>=base+3*raw.len(),"nested shared strings are charged at each retained reference");
        style.svg_clip_path=Some(Arc::from("x".repeat(MAX_RETAINED_FRAGMENT_BYTES)));
        assert!(checked_style_retained_bytes(&style).is_none(),"nested style payload cannot bypass the retained byte budget");
    }

    struct DecorationMetricText;
    impl TextShaper for DecorationMetricText {
        fn shape(&self,text:&str,size:f32)->Result<ShapedRun,()> {RecordingText::default().shape(text,size)}
        fn ascent(&self,_:f32)->f32 {10.0}
        fn line_height(&self,_:f32)->f32 {16.0}
        fn underline_metrics_styled(&self,size:f32,font:&FontSpec)->(f32,f32) {
            (size*0.15,if font.weight>=700 {8.4}else{3.4})
        }
        fn strike_metrics_styled(&self,size:f32,_:&FontSpec)->(f32,f32) {(-size*0.25,6.4)}
    }

    #[test]
    fn specification_text_decoration_thickness_origin_font_metrics_and_patterns() {
        for (thickness,expected) in [("from-font",3.0),("25%",5.0),("-20px",1.0),("2.4px",2.0)] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}main{{font:20px/24px monospace;text-decoration:underline overline line-through red;text-decoration-thickness:{thickness}}}span{{font-size:40px;font-weight:bold;text-decoration-thickness:12px}}#contents{{display:contents;text-decoration:underline blue;text-decoration-thickness:30px}}#contents::before{{content:'Q';display:contents;text-decoration:underline blue}}main::after{{content:'Z'}}</style><main>A<span>B</span><i id=contents>C</i>D</main>"),96).unwrap();
            let list=display_list(&document,240,100,&DecorationMetricText).unwrap();
            let red:Vec<_>=list.0.iter().filter_map(|command|match command {Command::FillRect{rect,color} if color.r==255&&color.g==0&&color.b==0=>Some(*rect),_=>None}).collect();
            assert!(!red.is_empty());
            assert!(red.iter().all(|rect|(rect.height-expected).abs()<0.01),"originating thickness covers all three line kinds through descendant fonts/generated sources: {thickness}: {red:?}");
            assert!(!list.0.iter().any(|command|matches!(command,Command::FillRect{color,..} if color.r==0&&color.b==255)),"boxless elements/pseudos cannot create a decoration");
        }
        for pattern in ["solid","double","dotted","dashed","wavy"] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}p{{margin:0;text-decoration:underline {pattern} red;text-decoration-thickness:10px}}</style><p>A<span>B</span>C</p>"),64).unwrap();
            let list=display_list(&document,100,100,&DecorationMetricText).unwrap();
            assert!(list.0.iter().any(|command|match command {
                Command::FillRect{rect,color}|Command::FillRoundedRect{rect,color,..}=>color.r==255&&color.g==0&&(rect.height-10.0).abs()<0.01,
                Command::SvgPath{stroke_width,stroke:Some(crate::paint::SvgPaint::Color(color)),..}=>color.r==255&&color.g==0&&(*stroke_width-10.0).abs()<0.01,
                _=>false,
            }),"actual {pattern} painter consumes specified thickness");
        }
    }

    #[test]
    fn specification_text_underline_offset_zero_font_edges_vertical_and_retained() {
        let lines=|position:&str,offset:&str,mode:&str| {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}p{{margin:0;font:20px/24px monospace;writing-mode:{mode};text-decoration:underline overline line-through red;text-decoration-thickness:4px;text-underline-position:{position};text-underline-offset:{offset}}}</style><p>A</p>"),64).unwrap();
            let list=display_list(&document,120,120,&DecorationMetricText).unwrap();
            let baseline=list.0.iter().find_map(|command|match command {Command::GlyphRun{baseline_y,..}=>Some(*baseline_y),_=>None}).unwrap();
            let decoration:Vec<_>=list.0.iter().filter_map(|command|match command {Command::FillRect{rect,color} if color.r==255&&color.g==0&&color.b==0=>Some(rect.y-baseline),_=>None}).collect();
            assert_eq!(decoration.len(),3);
            decoration
        };
        assert!((lines("auto","0px","horizontal-tb")[0]).abs()<0.01,"authored zero aligns at alphabetic baseline");
        assert!((lines("from-font","0px","horizontal-tb")[0]-3.0).abs()<0.01,"from-font zero preserves actual preferred position");
        for mode in ["horizontal-tb","vertical-rl","vertical-lr","sideways-lr"] {
            for position in ["auto","from-font","under","left","right"] {
                let zero=lines(position,"0px",mode);
                let shifted=lines(position,"2px",mode);
                assert!(((shifted[0]-zero[0]).abs()-2.0).abs()<0.01,"offset moves only the actual underline in its outward direction: {mode}/{position}");
                assert_eq!(&shifted[1..],&zero[1..],"offset does not move overline/line-through: {mode}/{position}");
            }
        }
        for mode in ["horizontal-tb","vertical-rl"] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}p{{margin:0;height:32px}}#target{{font:20px/24px monospace;writing-mode:{mode};text-decoration:underline dotted red;text-decoration-thickness:calc(2px + 10%);text-underline-offset:-10%}}#target::first-letter{{text-decoration:underline blue;text-decoration-thickness:7px;text-underline-offset:1px}}#target::after{{content:'Z'}}span{{font-size:40px;text-underline-offset:20px}}</style><p id=changed>before</p><p id=target>A<span>B</span>C</p>"),96).unwrap();
            let changed=crate::selector::query_selector(&document,document.root(),"#changed").unwrap().unwrap();
            let text=document.first_child(changed).unwrap().unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let initial=session.display_list(240,240,&DecorationMetricText).unwrap();
            assert!(initial.0.iter().any(|command|matches!(command,Command::FillRect{rect,color} if color.r==0&&color.b==255&&(rect.height-7.0).abs()<0.01)),"typographic pseudo uses its own authored thickness");
            session.document_mut().replace_data(text,"changed").unwrap();
            let retained=session.display_list(240,240,&DecorationMetricText).unwrap().clone();
            let fresh=display_list(session.document(),240,240,&DecorationMetricText).unwrap();
            assert_eq!(retained,fresh,"origin font/offset and generated decoration commands replay exactly: {mode}");
        }
    }

    #[test]
    fn specification_text_decoration_patterns_source_color_and_paint_order() {
        for pattern in ["solid","double","dotted","dashed","wavy"] {
            let markup=alloc::format!("<!doctype html><style>body{{margin:0}}p{{margin:0;text-decoration:underline overline line-through {pattern} red;color:green}}span{{color:blue}}</style><p>A<span>BCD</span></p>");
            let document=crate::html::parse(&markup,64).unwrap();
            let list=display_list(&document,200,100,&RecordingText::default()).unwrap();
            let first=list.0.iter().position(|command|matches!(command,Command::GlyphRun{..})).unwrap();
            let red=|command:&Command| match command {
                Command::FillRect{color,..}|Command::FillRoundedRect{color,..}=>color.r==255&&color.g==0&&color.b==0,
                Command::SvgPath{stroke:Some(crate::paint::SvgPaint::Color(color)),..}=>color.r==255&&color.g==0&&color.b==0,
                _=>false,
            };
            assert!(list.0[..first].iter().any(red),"underline/overline paint below glyphs: {pattern}");
            assert!(list.0[first+1..].iter().any(red),"line-through paints above glyphs: {pattern}");
            match pattern {
                "double"=>assert!(list.0.iter().filter(|command|red(command)).count()>=6),
                "dotted"=>assert!(list.0.iter().any(|command|matches!(command,Command::FillRoundedRect{radius,..} if *radius>0.0))),
                "wavy"=>assert!(list.0.iter().any(|command|matches!(command,Command::SvgPath{stroke_width,data,..} if *stroke_width>=1.0&&data.contains(" Q ")))),
                _=>{},
            }
        }
    }

    #[test]
    fn specification_text_decoration_box_boundaries_edges_and_under_position() {
        let document=crate::html::parse("<!doctype html><style>body{margin:0}p{margin:0;text-decoration:underline red}#atomic{display:inline-block}#edge{padding-left:12px}#contents{display:contents;text-decoration:overline blue}</style><p>A<span id=atomic>B</span><span id=edge>C</span><span id=contents>D</span></p>",96).unwrap();
        let atomic=crate::selector::query_selector(&document,document.root(),"#atomic").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();
        let mut geometry=LayoutGeometry::default();
        let list=display_list_with_styles(&document,200,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let b=geometry.hits.iter().find(|hit|hit.node==atomic&&!hit.virtual_generated).unwrap().rect;
        let red:Vec<Rect>=list.0.iter().filter_map(|command|match command {Command::FillRect{rect,color} if color.r==255&&color.g==0&&color.b==0=>Some(*rect),_=>None}).collect();
        assert!(red.iter().all(|rect|(rect.y-red[0].y).abs()<0.01),"adjacent atomic/edge/contents sources stay on the same actual line: {red:?}");
        assert!(!red.iter().any(|rect|rect.x < b.x + b.width && rect.x + rect.width > b.x),"atomic descendant contents do not receive propagated underline even below the box: atomic={b:?}, decoration={red:?}");
        assert!(red.iter().any(|rect|rect.width>=12.0),"ancestor underline crosses descendant padding: {red:?}");
        assert!(!list.0.iter().any(|command|matches!(command,Command::FillRect{color,..} if color.b==255&&color.r==0)),"display:contents has no decorating box");
        let position=|value:&str| {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}p{{margin:0;text-decoration:underline red;text-underline-position:{value}}}</style><p>Ab</p>"),64).unwrap();
            display_list(&document,100,100,&RecordingText::default()).unwrap().0.iter().find_map(|command|match command {Command::FillRect{rect,color} if color.r==255&&color.g==0=>Some(rect.y),_=>None}).unwrap()
        };
        assert!(position("under")>position("from-font"),"under placement uses the font text-under edge");
    }

    #[test]
    fn specification_text_decoration_nested_edges_preserve_line_height_and_retained_geometry() {
        let render = |edges: bool| {
            let edge_style = if edges {
                "#outer{margin-left:7px;margin-right:11px;padding:30px 5px 40px 3px;border:2px solid blue}#inner{margin-left:2px;margin-right:8px;padding:50px 6px 60px 4px;border:1px solid green}"
            } else { "" };
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}p{{margin:0;line-height:24px;text-decoration:underline red}}{edge_style}</style><p id=target>A<span id=outer>B<span id=inner>C</span>D</span>F</p>"),96).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#target").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();
            let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,300,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let x=list.0.iter().find_map(|command|match command {
                Command::GlyphRun{origin_x,glyphs,..}=>glyphs.iter().find(|glyph|glyph.id==u16::from(b'F')).map(|glyph|*origin_x+glyph.x),
                _=>None,
            }).unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
            (x,rect.height)
        };
        let plain=render(false);let edged=render(true);
        assert!((edged.0-plain.0-52.0).abs()<0.01,"both nested edges include their actual margin, padding and border advances: plain={plain:?}, edged={edged:?}");
        assert!((edged.1-plain.1).abs()<0.01,"cross-axis inline padding and borders affect painting rather than line-box height: plain={plain:?}, edged={edged:?}");
        let document=crate::html::parse("<!doctype html><style>body{margin:0}p{margin:0;line-height:24px}#target{text-decoration:underline red}#target span{padding:30px 12px;border:2px solid blue;margin:0 3px}</style><p id=changed>before</p><p id=target>A<span>B<span>C</span>D</span>F</p>",96).unwrap();
        let changed=crate::selector::query_selector(&document,document.root(),"#changed").unwrap().unwrap();
        let text=document.first_child(changed).unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        session.display_list(300,200,&RecordingText::default()).unwrap();
        session.document_mut().replace_data(text,"changed").unwrap();
        let retained=session.display_list(300,200,&RecordingText::default()).unwrap().clone();
        let fresh=display_list(session.document(),300,200,&RecordingText::default()).unwrap();
        assert_eq!(retained,fresh,"nested edge source ranges and decoration geometry survive retained replay");
    }

