    #[test]
    fn specification_typographic_pseudos_group_letter_paint_and_replay() {
        let document = crate::html::parse("<!doctype html><style>body{margin:0}p{margin:0;height:40px}#target::first-letter{opacity:.5;background:yellow;color:red;border:1px solid blue;text-decoration:underline}</style><p id=changed>before</p><p id=target>‘<span>A</span>’bc</p><p>after</p>", 96).unwrap();
        let target = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
        let changed = crate::selector::query_selector(&document, document.root(), "#changed").unwrap().unwrap();
        let changed_text = document.first_child(changed).unwrap().unwrap();
        let mut session = crate::session::RenderSession::new(document);
        session.request_rendered_text_boxes();
        for replay in [false, true] {
            if replay { session.document_mut().replace_data(changed_text, "changed").unwrap(); }
            let list = session.display_list(200, 200, &RecordingText::default()).unwrap();
            let mut in_letter = false;
            let mut groups = 0;
            let mut glyphs = 0;
            let mut background = false;
            for command in &list.0 {
                match command {
                    Command::PushLayer { opacity, .. } if *opacity == 0.5 => { assert!(!in_letter); in_letter = true; groups += 1; }
                    Command::PopLayer if in_letter => in_letter = false,
                    Command::GlyphRun { .. } if in_letter => glyphs += 1,
                    Command::FillRect { color, .. } if in_letter && color.r == 255 && color.g == 255 && color.b == 0 => background = true,
                    _ => {}
                }
            }
            assert_eq!(groups, 1, "one composite for punctuation across authored spans");
            assert!(glyphs >= 2 && background && !in_letter, "actual background and all shaped runs share the group");
            assert_eq!(crate::rendered_text::get(&mut session, target).unwrap(), "‘A’bc");
            if replay { assert!(session.layout_cache_stats().hits >= 2); }
        }
        session.finish_rendered_text_boxes();
    }

    #[test]
    fn specification_typographic_pseudos_marker_float_and_descendant_flow() {
        let document = crate::html::parse("<!doctype html><style>body{margin:0}p{margin:0}#outer::first-line{color:green}#float::first-letter{float:left;font-size:40px}#after{height:10px}li{list-style-position:inside}li::marker{content:'M'}li::first-letter{color:red}</style><div id=outer><div style='color:blue'><span>A</span><br>B</div></div><p id=float>A</p><div id=after></div><ul><li>Cde</li></ul>", 128).unwrap();
        let list = display_list(&document, 200, 200, &RecordingText::default()).unwrap();
        let mut colors = Vec::new();
        for command in &list.0 {
            if let Command::GlyphRun { color, glyphs, .. } = command {
                colors.extend(glyphs.iter().filter_map(|glyph| char::from_u32(u32::from(glyph.id)).map(|character| (character, *color))));
            }
        }
        assert!(colors.iter().any(|(character, color)| *character == 'A' && color.g == 128));
        assert!(colors.iter().any(|(character, color)| *character == 'B' && color.b == 255));
        assert!(colors.iter().any(|(character, color)| *character == 'C' && color.r == 255 && color.g == 0));
        assert!(colors.iter().all(|(character, color)| *character != 'M' || color.r == 0));
        let (document, geometry) = intrinsic_keyword_geometry("<style>#float::first-letter{float:left;font-size:40px}p{margin:0}</style><p id=float>A</p><div id=after style='height:10px'></div>");
        let floated = intrinsic_keyword_rect(&document, &geometry, "#float");
        let after = intrinsic_keyword_rect(&document, &geometry, "#after");
        assert_eq!(floated.height, 0.0, "a float alone does not create an in-flow font strut");
        assert_eq!(after.y, floated.y, "following block starts at the same in-flow position");
    }

