        assert!(!list.0.iter().any(|command|matches!(command,Command::GlyphRun{color,glyphs,..}
            if (color.r==255 || color.b==255) && glyphs.iter().any(|glyph|glyph.id==u16::from(b'M')))),"actual marker frames are excluded from letter selection");
