    #[test]
    fn stretched_background_masks_resolve_final_border_geometry() {
        for display in ["flex", "grid"] {
            for background in ["red", "linear-gradient(red,blue)"] {
                let fixture = alloc::format!(
                    "<style>body{{margin:0}}</style><div style='display:{display};height:80px;width:100px'><div style='width:40px;border:4px double transparent;border-radius:50%;box-shadow:inset 1px 2px red;background:{background};background-clip:border-area text'>text</div></div>"
                );
                let document = crate::html::parse(&fixture, 64).unwrap();
                let text = RecordingText::default();
                let list = crate::layout::display_list(&document, 100, 100, &text).unwrap();
                let mask = list
                    .0
                    .iter()
                    .find_map(|command| match command {
                        Command::MaskedBackground(mask) => Some(mask),
                        _ => None,
                    })
                    .expect("masked stretched background");
                assert_eq!(mask.rect.height, 80.0, "{display}: {background}");
                let border = mask
                    .mask
                    .0
                    .iter()
                    .find_map(|command| match command {
                        Command::StrokeBoxBorder(border) => Some(border),
                        _ => None,
                    })
                    .expect("border-area coverage");
                assert_eq!(border.rect, mask.rect);
                assert_eq!(border.corners.unwrap()[0][1], 40.0);
                let shadow = list
                    .0
                    .iter()
                    .find_map(|command| match command {
                        Command::BoxShadow {
                            rect,
                            corners,
                            shadow,
                            ..
                        } if shadow.inset => Some((rect, corners)),
                        _ => None,
                    })
                    .expect("stretched inset shadow");
                assert_eq!(shadow.0.height, 72.0);
                assert_eq!(shadow.1.as_ref().unwrap()[0][1], 36.0);
                assert!(
                    mask.mask
                        .0
                        .iter()
                        .any(|command| matches!(command, Command::GlyphRun { .. })),
                    "stretch retains the ink mask"
                );
            }
        }
    }

    #[test]
    fn ancestor_text_background_requires_scroll_mask_repaint() {
        let document = crate::html::parse(
            "<style>body{margin:0}</style><div style='background:red;background-clip:text'><div style='width:30px;height:20px;overflow:auto'><div style='height:80px'>text</div></div></div>",
            64,
        ).unwrap();
        let mut rules = stylesheets(&document).unwrap();
        rules.environment = css::MediaEnvironment {
            width: 100.0,
            height: 100.0,
            ..Default::default()
        };
        let mut geometry = LayoutGeometry::default();
        let mut list = display_list_with_styles(
            &document,
            100,
            100,
            &FixedText,
            &rules,
            None,
            Some(&mut geometry),
            &[],
        )
        .unwrap();
        let region = geometry
            .scroll_regions
            .first()
            .expect("ordinary descendant scroll region")
            .clone();
        assert!(
            list.0
                .iter()
                .enumerate()
                .any(|(index, command)| !region.commands.contains(&index)
                    && matches!(command,Command::MaskedBackground(mask) if mask.text_clipped))
        );
        let before = list.0.clone();
        assert!(!geometry.scroll_region(&mut list.0, region.node, (0.0, 0.0), (0.0, 1.0)));
        assert_eq!(
            list.0, before,
            "fallback must leave paint unchanged until relayout"
        );
    }

    #[test]
    fn fixed_and_local_backgrounds_disable_unsafe_scroll_replay() {
        let fixtures = [
            "<style>body{margin:0}</style><div style='width:30px;height:20px;overflow:auto;background-image:url(a.png)'><div style='height:80px;margin:0;background-image:url(a.png);background-attachment:fixed'></div></div>",
            "<style>body{margin:0}</style><div style='width:30px;height:20px;overflow:auto;background-image:url(a.png);background-attachment:local'><div style='height:80px;margin:0'></div></div>",
        ];
        for (fixture, attachment) in fixtures.into_iter().zip(["fixed", "local"]) {
            let document = crate::html::parse(fixture, 64).unwrap();
            let mut rules = stylesheets(&document).unwrap();
            rules.environment = css::MediaEnvironment {
                width: 100.0,
                height: 100.0,
                ..Default::default()
            };
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(
                &document,
                100,
                100,
                &NoShape,
                &rules,
                None,
                Some(&mut geometry),
                &[],
            )
            .unwrap();
            assert!(
                geometry.scroll_regions.is_empty(),
                "{attachment} attachment must not use unsafe translate-only replay"
            );
        }
    }

    #[test]
    fn round_background_repeat_adjusts_auto_size_and_position() {
        let (.., image_rect, repeat) = background_fills(
            "<div style='width:30px;height:20px;background-image:url(a.png);background-repeat:round no-repeat;background-position:right bottom'></div>",
            test_image,
        )[0];
        assert_eq!(
            repeat,
            [BackgroundRepeat::Round, BackgroundRepeat::NoRepeat]
        );
        assert!(
            (image_rect.x - 22.5).abs() < 0.001
                && (image_rect.y - 16.25).abs() < 0.001
                && (image_rect.width - 7.5).abs() < 0.001
                && (image_rect.height - 3.75).abs() < 0.001,
            "one-axis round should keep the intrinsic ratio and reposition the tile: {image_rect:?}"
        );

        let (.., image_rect, repeat) = background_fills(
            "<div style='width:30px;height:20px;background-image:url(a.png);background-repeat:round;background-position:0 0'></div>",
            test_image,
        )[0];
        assert_eq!(repeat, [BackgroundRepeat::Round; 2]);
        assert!(
            (image_rect.width - 7.5).abs() < 0.001 && (image_rect.height - 4.0).abs() < 0.001,
            "two-axis round should adjust each axis independently: {image_rect:?}"
        );
    }

    #[test]
    fn background_url_pending_errors_and_failed_paints_nothing() {
        let document = crate::html::parse(
            "<style>body{margin:0}</style><div style='width:40px;height:20px;background-image:url(a.png)'></div>",
            32,
        )
        .unwrap();
        let pending = |_: &str| ImageState::Pending;
        assert_eq!(
            display_list_with_images(&document, 100, 100, &NoShape, &pending),
            Err(LayoutError::ImagePending)
        );
        let fills = background_fills(
            "<style>body{margin:0}</style><div style='width:40px;height:20px;background-image:url(missing.png)'></div>",
            test_image,
        );
        assert_eq!(fills.len(), 1);
        assert_eq!(fills[0].2.width, 0.0, "failed images paint no tile");
    }

    #[test]
    fn background_gradients_flow_through_layers_in_paint_order() {
        let document = crate::html::parse(
            "<style>body{margin:0}</style><div style='width:40px;height:20px;background-image:linear-gradient(red,blue),url(a.png)'></div>",
            32,
        )
        .unwrap();
        let list = display_list_with_images(&document, 100, 100, &NoShape, &test_image).unwrap();
        let paints = list
            .0
            .iter()
            .filter_map(|command| match command {
                Command::FillBackground(fill) => Some((&fill.rect, &fill.image)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(paints.len(), 2);
        // The first layer paints last, so the url tile is under the gradient.
        assert!(matches!(&paints[0].1, BackgroundPaint::Image(_)));
        assert!(matches!(&paints[1].1, BackgroundPaint::Gradient(_)));
        // A gradient has no intrinsic size: auto fills the positioning area.
        assert_eq!((paints[1].0.width, paints[1].0.height), (40.0, 20.0));
    }

    struct FixedText;

    struct SizedText;

    #[test]
    fn specification_number_control_final_font_domain_content_and_minimum_use_real_sources() {
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}input,select{display:block;appearance:none;font:10px/10px monospace;border:0;padding:0}#content,#empty,#hint,#vertical,#minimum,#maximum{field-sizing:content}#empty{min-width:1px}#vertical{writing-mode:vertical-rl}#minimum{width:min-content}#maximum{width:max-content}</style><input id=fixed type=number size=1 value=123><input id=bounded type=number min=0 max=999 step=1><input id=content type=number value=12345><input id=empty type=number><input id=hint type=number value=invalid placeholder=12345><input id=vertical type=number value=123><select id=minimum><option selected>AA BB</option></select><select id=maximum><option selected>AA BB</option></select>",192).unwrap();
        let mut session = crate::session::RenderSession::new(document);
        let find = |session: &crate::session::RenderSession, name: &str| {
            crate::selector::query_selector(session.document(), session.document().root(), name)
                .unwrap()
                .unwrap()
        };
        let render = |session: &mut crate::session::RenderSession| {
            session.display_list(300, 300, &FixedText).unwrap().clone()
        };
        let first = render(&mut session);
        for (name, width, height) in [
            ("#fixed", 40., 10.),
            ("#bounded", 6., 10.),
            ("#content", 10., 10.),
            ("#empty", 1., 10.),
            ("#hint", 10., 10.),
            ("#vertical", 10., 6.),
            ("#minimum", 4., 10.),
            ("#maximum", 10., 10.),
        ] {
            let rect = session.layout_rect(find(&session, name)).unwrap();
            assert_eq!((rect.width, rect.height), (width, height), "{name}");
        }
        let bounded = find(&session, "#bounded");
        session
            .document_mut()
            .set_attribute(bounded, "max", "99999")
            .unwrap();
        let changed = render(&mut session);
        assert_eq!(session.layout_rect(bounded).unwrap().width, 10.);
        assert_ne!(first.0, changed.0);
        assert_eq!(
            changed.0,
            display_list(session.document(), 300, 300, &FixedText)
                .unwrap()
                .0
        );
        let content = find(&session, "#content");
        session
            .document_mut()
            .set_attribute(content, "style", "width:30px;height:7px")
            .unwrap();
        render(&mut session);
        let rect = session.layout_rect(content).unwrap();
        assert_eq!((rect.width, rect.height), (30., 7.));
    }
    #[test]
    fn specification_field_sizing_content_uses_live_sources_wrapping_rows_and_retained_geometry() {
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}input,textarea,select{display:block;appearance:none;font:10px/10px monospace;padding:0;border:0;field-sizing:content}#fixed{field-sizing:fixed}#empty{min-width:1px}#wrap,#off{width:4px}#vertical{writing-mode:vertical-rl}</style><input id=fixed size=4 value=ab><input id=entry size=99 value=abc><input id=empty size=99><input id=hint placeholder=abcd><textarea id=wrap>AA BB</textarea><textarea id=off wrap=off>AA BB</textarea><textarea id=vertical>abc</textarea><select id=drop><option selected>a</option><option>long</option></select><select id=list multiple size=9><optgroup label=group><option>a</option><option>long</option></optgroup></select>",192).unwrap();
        let mut session = crate::session::RenderSession::new(document);
        let node = |session: &crate::session::RenderSession, name: &str| {
            crate::selector::query_selector(session.document(), session.document().root(), name)
                .unwrap()
                .unwrap()
        };
        let render = |session: &mut crate::session::RenderSession| {
            session.display_list(300, 300, &FixedText).unwrap().clone()
        };
        let first = render(&mut session);
        for (name, width, height) in [
            ("#fixed", 8., 10.),
            ("#entry", 6., 10.),
            ("#empty", 1., 10.),
            ("#hint", 8., 10.),
            ("#wrap", 4., 20.),
            ("#off", 4., 10.),
            ("#vertical", 10., 6.),
            ("#drop", 2., 10.),
            ("#list", 10., 30.),
        ] {
            let rect = session.layout_rect(node(&session, name)).unwrap();
            assert_eq!((rect.width, rect.height), (width, height), "{name}");
        }
        let list = node(&session, "#list");
        let mut indices = Vec::new();
        crate::forms::for_each_select_option(session.document(), list, |_, index| {
            indices.push(index);
            true
        })
        .unwrap();
        assert_eq!(
            indices,
            alloc::vec![0, 1],
            "group headers do not change option indices"
        );
        assert_eq!(render(&mut session).0, first.0);
        assert_eq!(
            first.0,
            display_list(session.document(), 300, 300, &FixedText)
                .unwrap()
                .0
        );
        let entry = node(&session, "#entry");
        session
            .document_mut()
            .set_attribute(entry, "value", "abcdef")
            .unwrap();
        let changed = render(&mut session);
        assert_eq!(session.layout_rect(entry).unwrap().width, 12.);
        assert_eq!(
            changed.0,
            display_list(session.document(), 300, 300, &FixedText)
                .unwrap()
                .0
        );
        session
            .document_mut()
            .set_attribute(entry, "style", "field-sizing:fixed")
            .unwrap();
        render(&mut session);
        assert_eq!(session.layout_rect(entry).unwrap().width, 198.);
    }
    #[test]
    fn specification_primary_font_control_sizes_use_final_metrics_counts_and_logical_axes() {
        struct MetricText;
        impl TextShaper for MetricText {
            fn shape(&self, text: &str, size: f32) -> Result<ShapedRun, ()> { SizedText.shape(text,size) }
            fn ascent(&self, size: f32) -> f32 { SizedText.ascent(size) }
            fn line_height(&self, size: f32) -> f32 { SizedText.line_height(size) }
            fn primary_character_widths_styled(&self, size: f32, _: &FontSpec) -> Option<crate::paint::PrimaryCharacterWidths> {
                Some(crate::paint::PrimaryCharacterWidths { average:size*0.4,maximum:size*0.9 })
            }
        }
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}input,textarea{display:block;font:10px/1.2 monospace;appearance:none;padding:0;border:0;letter-spacing:100px}#vertical{writing-mode:vertical-rl}#explicit{width:30px;height:7px}</style><input id=default><input id=zero size=0><input id=parsed size=' +4trailing'><input id=large size=999><input id=vertical size=4><input id=explicit size=99><textarea id=area cols=3 rows=3></textarea><textarea id=fallback cols=0 rows=0></textarea>",128).unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let node=|session:&crate::session::RenderSession,name:&str|crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
        let default=node(&session,"#default");
        let render=|session:&mut crate::session::RenderSession|session.display_list(6000,1000,&MetricText).unwrap().clone();
        let initial=render(&mut session);
        for (name,width,height) in [("#default",85.,12.),("#zero",5.,12.),("#parsed",21.,12.),("#large",4001.,12.),("#vertical",12.,21.),("#explicit",30.,7.),("#area",12.,36.),("#fallback",80.,24.)] {
            let rect=session.layout_rect(node(&session,name)).unwrap();
            assert_eq!((rect.width,rect.height),(width,height),"{name}");
        }
        assert_eq!(render(&mut session).0,initial.0);
        let fresh=display_list(session.document(),6000,1000,&MetricText).unwrap();
        assert_eq!(fresh.0,initial.0);
        session.document_mut().set_attribute(default,"style","font-size:20px;letter-spacing:0").unwrap();
        let changed=render(&mut session);
        let rect=session.layout_rect(default).unwrap();
        assert_eq!((rect.width,rect.height),(170.,24.));
        assert_eq!(session.document().get_attribute_ns_ref(default,None,"size").unwrap(),None);
        assert_eq!(changed.0,display_list(session.document(),6000,1000,&MetricText).unwrap().0);
    }

    fn intrinsic_keyword_geometry(markup: &str) -> (Document, LayoutGeometry) {
        intrinsic_keyword_geometry_at(markup, 120, 300)
    }

    fn intrinsic_keyword_geometry_at(
        markup: &str,
        viewport_width: u32,
        viewport_height: u32,
    ) -> (Document, LayoutGeometry) {
        let markup = alloc::format!("<style>html,body{{margin:0;font-size:10px}}</style>{markup}");
        let document = crate::html::parse(&markup, 96).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(
            &document,
            viewport_width,
            viewport_height,
            &SizedText,
            &rules,
            None,
            Some(&mut geometry),
            &[],
        )
        .unwrap();
        (document, geometry)
    }

    fn intrinsic_keyword_rect(
        document: &Document,
        geometry: &LayoutGeometry,
        selector: &str,
    ) -> Rect {
        let node = crate::selector::query_selector(document, document.root(), selector)
            .unwrap()
            .unwrap();
        geometry
            .hits
            .iter()
            .find(|hit| hit.node == node)
            .unwrap()
            .rect
    }

