    #[test]
    fn specification_emergency_wrapping_moves_words_and_keeps_graphemes() {
        for (mode,height) in [("normal",10.0),("break-word",20.0),("anywhere",20.0)] {
            let (document,geometry)=intrinsic_keyword_geometry(&alloc::format!("<main id=box style='width:10px;overflow-wrap:{mode}'>abcd</main>"));
            assert_eq!(intrinsic_keyword_rect(&document,&geometry,"#box").height,height,"{mode}");
        }
        let (document,geometry)=intrinsic_keyword_geometry("<main id=box style='width:15px;overflow-wrap:break-word'>a abcd</main>");
        assert_eq!(intrinsic_keyword_rect(&document,&geometry,"#box").height,30.0,"the word moves before emergency splitting");
        let (document,geometry)=intrinsic_keyword_geometry("<main id=box style='width:5px;overflow-wrap:break-word'>a&#x301;b</main>");
        assert_eq!(intrinsic_keyword_rect(&document,&geometry,"#box").height,20.0,"a combining sequence stays together even when wider than a line");
        let (document,geometry)=intrinsic_keyword_geometry("<main id=box style='width:5px;overflow-wrap:anywhere;white-space:nowrap'>abcd</main>");
        assert_eq!(intrinsic_keyword_rect(&document,&geometry,"#box").height,10.0,"nowrap prevents emergency breaks");
    }

