    #[test]
    fn forced_empty_first_line_donates_strut_baseline_without_replacing_last_image_line() {
        for mode in ["horizontal-tb", "vertical-lr", "vertical-rl"] {
            for alignment in ["first baseline", "last baseline"] {
                let markup = alloc::format!(
                    "<style>html,body{{margin:0}}main{{display:grid;writing-mode:{mode};text-orientation:mixed;font-size:20px;line-height:1;width:100px;height:150px;grid-template-columns:50px 50px;grid-template-rows:100px;align-items:{alignment}}}</style>\n                     <main><div id=text>x</div><div id=broken><br><img id=inline-image src=a.png style='width:50px;height:50px'></div></main>\n                     <div id=whitespace style='display:flow-root;font-size:20px;line-height:1'> </div>\n                     <div id=block-control style='display:flow-root;width:50px;font-size:20px;line-height:1'><br><img id=block-image src=a.png style='display:block;width:50px;height:50px'></div>"
                );
                let document = crate::html::parse(&markup, 96).unwrap();
                let rules = stylesheets(&document).unwrap();
                for (selector, expected) in [
                    ("#inline-image", Display::Inline),
                    ("#block-image", Display::Block),
                ] {
                    let node =
                        crate::selector::query_selector(&document, document.root(), selector)
                            .unwrap()
                            .unwrap();
                    assert_eq!(
                        css::compute_node(&document, node, None, &rules)
                            .unwrap()
                            .display,
                        expected,
                        "{selector}"
                    );
                }
                let mut geometry = LayoutGeometry::default();
                display_list_with_styles(
                    &document,
                    120,
                    300,
                    &SizedText,
                    &rules,
                    Some(&test_image),
                    Some(&mut geometry),
                    &[],
                )
                .unwrap();
                let text = intrinsic_keyword_rect(&document, &geometry, "#text");
                let broken = intrinsic_keyword_rect(&document, &geometry, "#broken");
                if mode == "horizontal-tb" {
                    assert_eq!((text.height, broken.height), (20.0, 74.0), "{alignment}");
                    if alignment == "first baseline" {
                        assert_eq!(text.y, broken.y, "horizontal first-line struts align");
                    } else {
                        assert_eq!(
                            text.y + 16.0,
                            broken.y + 70.0,
                            "horizontal last image baseline remains dominant"
                        );
                    }
                } else {
                    assert_eq!(
                        (text.width, broken.width),
                        (20.0, 70.0),
                        "{mode} {alignment}"
                    );
                    if alignment == "first baseline" {
                        let text_edge = text.x
                            + if mode == "vertical-rl" {
                                text.width
                            } else {
                                0.0
                            };
                        let broken_edge = broken.x
                            + if mode == "vertical-rl" {
                                broken.width
                            } else {
                                0.0
                            };
                        assert_eq!(
                            text_edge, broken_edge,
                            "{mode} first empty line is retained"
                        );
                    } else {
                        let image_center = if mode == "vertical-rl" {
                            broken.x + 25.0
                        } else {
                            broken.x + broken.width - 25.0
                        };
                        assert_eq!(
                            text.x + text.width * 0.5,
                            image_center,
                            "{mode} last image line is retained"
                        );
                    }
                }
                assert_eq!(
                    intrinsic_keyword_rect(&document, &geometry, "#whitespace").height,
                    0.0,
                    "collapsed whitespace does not create a strut line"
                );
                assert_eq!(
                    intrinsic_keyword_rect(&document, &geometry, "#block-control").height,
                    70.0,
                    "author block image follows the 20px break line without an inline descent"
                );
            }
        }
    }

