    #[test]
    fn table_cells_align_explicit_baselines_and_top_middle_bottom_contents() {
        struct GlyphSizedText;
        impl TextShaper for GlyphSizedText {
            fn shape(&self, text: &str, size: f32) -> Result<ShapedRun, ()> {
                let mut run = RecordingText::default().shape(text, size)?;
                for glyph in Arc::make_mut(&mut run.glyphs) { glyph.x *= size / 12.0; }
                run.width = SizedText.shape(text, size)?.width;
                Ok(run)
            }
            fn ascent(&self, size: f32) -> f32 { SizedText.ascent(size) }
            fn line_height(&self, size: f32) -> f32 { SizedText.line_height(size) }
        }
        let document = crate::html::parse(
            "<style>html,body{margin:0}table{border-spacing:0}td{padding:0;vertical-align:baseline}</style><table><tr><td style='font-size:10px'>a</td><td style='font-size:20px'>b</td></tr></table>",
            32,
        )
        .unwrap();
        let list = display_list(&document, 100, 80, &GlyphSizedText).unwrap();
        let baselines = list
            .0
            .iter()
            .filter_map(|command| match command {
                Command::GlyphRun { baseline_y, .. } => Some(*baseline_y),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(baselines.len(), 2);
        assert_eq!(baselines, [16.0, 16.0],"{list:?}");

        let document = crate::html::parse(
            "<style>html,body{margin:0}td{padding:0;font-size:10px}</style><table style='height:30px;border-spacing:0'><tr><td style='vertical-align:top'>a</td><td style='vertical-align:middle'>b</td><td style='vertical-align:bottom'>c</td></tr></table>",
            32,
        )
        .unwrap();
        let list = display_list(&document, 100, 80, &GlyphSizedText).unwrap();
        let baselines = list
            .0
            .iter()
            .filter_map(|command| match command {
                Command::GlyphRun { baseline_y, .. } => Some(*baseline_y),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(baselines, [8.0, 18.0, 28.0]);
    }

