    fn fill_colors(list: &DisplayList) -> Vec<Rgba> {
        list.0
            .iter()
            .filter_map(|command| match command {
                Command::FillRect { color, .. } if color.a == 255 => Some(*color),
                _ => None,
            })
            .collect()
    }

    fn has_color(colors: &[Rgba], r: u8, g: u8, b: u8) -> bool {
        colors
            .iter()
            .any(|color| (color.r, color.g, color.b) == (r, g, b))
    }

    #[test]
    fn specification_flow_owner_capacity_is_admitted_before_registry_growth() {
        let mut oversized=Vec::new();oversized.try_reserve_exact(MAX_DISPLAY_COMMANDS+1).unwrap();
        let mut owners=FlowPaintOwners::default();
        assert!(matches!(owners.register(FlowPaintOwner{commands:oversized,hits:Vec::new(),command_tail:0,hit_tail:0}),Err(LayoutError::CommandLimit)));
        assert_eq!(owners.owners.capacity(),0,"over-budget input cannot grow the registry");
        assert_eq!(owners.piece_capacity,0);
        let mut commands=Vec::new();commands.try_reserve_exact(MAX_DISPLAY_COMMANDS).unwrap();commands.push(0..1);
        let id=owners.register(FlowPaintOwner{commands,hits:Vec::new(),command_tail:2,hit_tail:0}).unwrap();
        let index=id.get() as usize-1;
        assert!(matches!(owners.append(index,3,1),Err(LayoutError::CommandLimit)));
        let owner=&owners.owners[index];
        assert_eq!((owner.command_tail,owner.hit_tail),(2,0),"failed admission publishes no new source tail");
        assert_eq!(owner.commands,[0..1]);assert_eq!(owner.hits.capacity(),0,"the second range plane is rejected before growth");
        assert_eq!(owners.piece_capacity,MAX_DISPLAY_COMMANDS);
        let map=PaintPermutation::new(3,0,&[]).unwrap();
        assert!(matches!(owner.remapped(&map,&map,0),Err(LayoutError::CommandLimit)));
        assert_eq!(owners.owners[index].commands,[0..1],"failed projection keeps the admitted owner unchanged");
    }

    #[test]
    fn specification_pending_float_line_ranges_follow_disjoint_group_adoption() {
        let document=crate::html::parse("<main></main>",16).unwrap();let rules=stylesheets(&document).unwrap();let text=RecordingText::default();
        let uses=core::cell::Cell::new(0);let cache=RefCell::default();
        let mut layout=Layout::new(&document,&text,&uses,&rules,None,Rect{x:0.0,y:0.0,width:100.0,height:100.0},None,&[],&cache,None);
        let rect=Rect{x:0.0,y:0.0,width:10.0,height:10.0};let mut line=layout.line_start();
        for color in [Rgba{r:255,g:0,b:0,a:255},Rgba{r:0,g:0,b:255,a:255},Rgba{r:0,g:255,b:0,a:255},Rgba{r:255,g:0,b:255,a:255}] {
            layout.push_command(Command::FillRect{rect,color}).unwrap();
        }
        layout.ensure_line_paint_owner(&mut line).unwrap();
        let flow=FlowContentRanges{command_start:0,command_end:3,hit_start:0,hit_end:0};
        let float=FlowContentRanges{command_start:3,command_end:4,hit_start:0,hit_end:0};
        layout.float_line_moves.insert(line.paint_key(),FloatLineMoves{shift:(3.0,5.0),pieces:alloc::vec![(flow,(0.0,0.0))],floats:alloc::vec![float]});
        layout.push_command(Command::PushLayer{svg_clip:None,filters:None,corners:None,rect,radius:0.0,opacity:0.5,clip:false}).unwrap();layout.push_command(Command::PopLayer).unwrap();
        layout.skip_line_paint_append(line).unwrap();
        let pieces=[0..1,2..3];let node=(document.root(),None);
        let moved=[(0,0,0,1,0,0,0,node,0,false),(0,0,2,3,0,0,0,node,1,false)];
        layout.permute_stacking_ranges_with_adoptions(&moved,(5,0),&[PaintScopeAdoption{destination_root:4,destination_scope:4,pieces:&pieces}]).unwrap();
        let moves=layout.float_line_moves.get(&line.paint_key()).unwrap();
        assert!(moves.pieces.len()>1,"pending source becomes disjoint after adoption");
        let end=layout.line_start();layout.align_line_until(line,end,20.0,20.0,&Style::initial(),true);
        assert_eq!(layout.float_line_storage,0,"projected float storage retires exactly");
        for command in &layout.commands {match command {
            Command::FillRect{rect,color}=>assert_eq!((rect.x,rect.y),if color.r==255&&color.b==255 {(0.0,0.0)}else{(3.0,5.0)},"float itself is excluded from pending in-flow movement"),
            Command::PushLayer{rect,..}=>assert_eq!((rect.x,rect.y),(0.0,0.0),"numeric envelope does not acquire a reserved filter wrapper"),_=>{}
        }}
        DisplayList(layout.commands).validate().unwrap();
    }

    #[test]
    fn specification_disjoint_overflow_owner_moves_once_and_excludes_neighbor_hits() {
        let document=crate::html::parse("<main></main>",16).unwrap();let rules=stylesheets(&document).unwrap();let text=RecordingText::default();
        let uses=core::cell::Cell::new(0);let cache=RefCell::default();
        let mut layout=Layout::new(&document,&text,&uses,&rules,None,Rect{x:0.0,y:0.0,width:100.0,height:100.0},None,&[],&cache,None);
        let rect=OverflowRect::new(1.0,2.0,10.0,20.0).unwrap();
        let mut frame=OverflowFrame::new(document.root(),false,false,(0.0,0.0),false,OverflowRoute::Root);
        frame.children.push(OverflowContribution{rect,hits:1..3,key:(1,7),paint_owner:None});
        frame.children.push(OverflowContribution{rect,hits:3..4,key:(3,8),paint_owner:None});
        layout.overflow_frames.push(frame);
        // Move the second half of the atomic contribution beyond its sibling.
        let map=PaintPermutation::new(5,5,&[2..3]).unwrap();
        layout.remap_overflow_paint_owners(&map).unwrap();
        let owner=layout.overflow_frames[0].children[0].paint_owner.unwrap();
        let parts=layout.flow_paint_owners.as_ref().unwrap().owners[owner.get() as usize-1].hits.clone();
        assert_eq!(parts.len(),2);
        let unrelated=layout.overflow_frames[0].children[1].hits.clone();
        assert!(parts.iter().all(|part|part.end<=unrelated.start||part.start>=unrelated.end));
        Layout::move_precise_overflow_parts(&mut layout.overflow_frames,&layout.overflow_move_index,
            layout.flow_paint_owners.as_deref(),parts[..1].iter().cloned(),9.0,11.0);
        assert_eq!(layout.overflow_frames[0].children[0].rect.left,rect.left,"partial source owner does not move an atomic extent");
        Layout::move_precise_overflow_parts(&mut layout.overflow_frames,&layout.overflow_move_index,
            layout.flow_paint_owners.as_deref(),parts.iter().cloned(),9.0,11.0);
        assert_eq!((layout.overflow_frames[0].children[0].rect.left,layout.overflow_frames[0].children[0].rect.top),(rect.left+9.0,rect.top+11.0));
        assert_eq!((layout.overflow_frames[0].children[1].rect.left,layout.overflow_frames[0].children[1].rect.top),(rect.left,rect.top),"neighbor hits inside the numeric envelope remain unmoved");
        // Compose another projection without allocating a second contribution.
        let second=PaintPermutation::new(5,0,&[unrelated]).unwrap();
        let old=layout.flow_paint_owners.as_ref().unwrap().owners[owner.get() as usize-1].piece_capacity();
        let owners=layout.flow_paint_owners.as_mut().unwrap();let index=owner.get() as usize-1;
        let projected=owners.owners[index].remapped(&second,&second,owners.available_owner_pieces(index).unwrap()).unwrap();
        owners.changed_capacity(old,projected.piece_capacity()).unwrap();owners.owners[index]=projected;
        layout.remap_overflow_paint_owners(&second).unwrap();
        assert_eq!(layout.overflow_frames[0].children[0].paint_owner,Some(owner));
        assert_eq!(layout.overflow_frames[0].children.len(),2);
    }

    #[test]
