        layout.push_command(Command::PushLayer{svg_clip:None,filters:None,corners:None,rect:outer,radius:0.0,opacity:0.5,clip:false}).unwrap();layout.push_command(Command::PopLayer).unwrap();layout.skip_line_paint_append(line).unwrap();
