        let rect=Rect{x:0.0,y:0.0,width:10.0,height:10.0};
        layout.push_command(Command::PushClip(Rect{x:0.0,y:0.0,width:100.0,height:100.0})).unwrap();let mut line=layout.line_start();
        layout.push_command(Command::PushTransform(crate::paint::Affine::IDENTITY)).unwrap();
        layout.push_command(Command::FillRect{rect,color:Rgba{r:255,g:0,b:0,a:255}}).unwrap();layout.push_command(Command::PopTransform).unwrap();
        layout.push_command(Command::FillRect{rect,color:Rgba{r:0,g:0,b:255,a:255}}).unwrap();
