    fn grid_boxes(markup: &str) -> Vec<Rect> {
        let document = crate::html::parse(markup, 32).unwrap();
        grid_boxes_at(&document, 100, 100)
    }

    fn grid_boxes_at(document: &Document, width: u32, height: u32) -> Vec<Rect> {
        display_list(document, width, height, &FixedText)
            .unwrap()
            .0
            .into_iter()
            .filter_map(|command| match command {
                Command::FillRect { rect, color } if color.a == 255 && color.g == 0 => Some(rect),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn grid_flex_alignment_resolves_logical_flow_subject_and_physical_edges() {
        for (direction, start, flow_start, end, flow_end) in [
            (
                "row-reverse",
                (0.0, 0.0),
                (80.0, 0.0),
                (80.0, 0.0),
                (0.0, 0.0),
            ),
            (
                "column-reverse",
                (0.0, 0.0),
                (0.0, 80.0),
                (0.0, 80.0),
                (0.0, 0.0),
            ),
        ] {
            for (alignment, expected) in [
                ("start", start),
                ("flow-start", flow_start),
                ("end", end),
                ("flow-end", flow_end),
            ] {
                let markup = alloc::format!(
                    "<style>body{{margin:0}}</style><main style='display:flex;width:100px;height:100px;flex-direction:{direction};justify-content:{alignment};align-items:start'><div style='width:20px;height:20px;flex-shrink:0;background:red'></div></main>"
                );
                let boxes = grid_boxes(&markup);
                assert_eq!(
                    (boxes[0].x, boxes[0].y),
                    expected,
                    "{direction} {alignment}"
                );
            }
        }
        for (alignment, expected) in [
            ("start", 0.0),
            ("end", 80.0),
            ("self-start", 80.0),
            ("self-end", 0.0),
            ("left", 0.0),
            ("right", 80.0),
        ] {
            let markup = alloc::format!(
                "<style>body{{margin:0}}</style><main style='display:grid;width:100px;grid-template-columns:100px'><div style='direction:rtl;justify-self:{alignment};width:20px;height:10px;background:red'></div></main>"
            );
            let boxes = grid_boxes(&markup);
            assert_eq!(boxes[0].x, expected, "subject rtl {alignment}");
        }
        for (alignment, expected) in [
            ("start", 80.0),
            ("self-start", 0.0),
            ("left", 0.0),
            ("right", 80.0),
        ] {
            let markup = alloc::format!(
                "<style>body{{margin:0}}</style><main style='display:grid;direction:rtl;width:100px;grid-template-columns:100px'><div style='direction:ltr;justify-self:{alignment};width:20px;height:10px;background:red'></div></main>"
            );
            assert_eq!(
                grid_boxes(&markup)[0].x,
                expected,
                "container rtl {alignment}"
            );
        }
        for (alignment, expected) in [
            ("start", 0.0),
            ("flow-start", 80.0),
            ("end", 80.0),
            ("flow-end", 0.0),
        ] {
            let markup = alloc::format!(
                "<style>body{{margin:0}}</style><main style='display:flex;flex-wrap:wrap-reverse;align-content:stretch;align-items:{alignment};width:100px;height:100px'><div style='width:20px;height:20px;background:red'></div></main>"
            );
            assert_eq!(
                grid_boxes(&markup)[0].y,
                expected,
                "wrap reverse {alignment}"
            );
        }
    }

    #[test]
    fn grid_flex_alignment_safe_overflow_and_legacy_block_geometry() {
        for display in ["grid", "grid-lanes", "flex"] {
            for (alignment, expected) in [
                ("unsafe center", -10.0),
                ("unsafe end", -20.0),
                ("safe center", 0.0),
                ("safe end", 0.0),
            ] {
                let markup = alloc::format!(
                    "<style>body{{margin:0}}</style><main style='display:{display};width:20px;grid-template-columns:20px;justify-content:{alignment};justify-items:{alignment};align-items:start'><div style='width:40px;height:10px;flex-shrink:0;background:red'></div></main>"
                );
                assert_eq!(grid_boxes(&markup)[0].x, expected, "{display} {alignment}");
            }
        }
        for (alignment, expected) in [
            ("legacy left", 0.0),
            ("legacy center", 40.0),
            ("legacy right", 80.0),
        ] {
            let markup = alloc::format!(
                "<style>body{{margin:0}}</style><main style='width:100px;justify-items:{alignment}'><div style='width:20px;height:10px;background:red'></div></main>"
            );
            assert_eq!(grid_boxes(&markup)[0].x, expected, "block {alignment}");
        }
        for (alignment, expected) in [
            ("start", 80.0),
            ("end", 0.0),
            ("left", 0.0),
            ("right", 80.0),
        ] {
            let markup = alloc::format!(
                "<style>body{{margin:0}}</style><main style='display:grid;direction:rtl;width:100px;grid-template-columns:20px;justify-content:{alignment}'><div style='height:10px;background:red'></div></main>"
            );
            assert_eq!(
                grid_boxes(&markup)[0].x,
                expected,
                "rtl content {alignment}"
            );
        }
    }

