    #[test]
    fn grid_content_baseline_retained_layout_preserves_text_and_box_hit_positions() {
        let document = crate::html::parse(
            "<style>html,body{margin:0}main{display:grid;width:100px;height:40px;grid-template-columns:50px 50px;grid-template-rows:40px;align-items:start}section{width:50px;height:40px;align-content:first baseline;background:red}.small{font-size:10px}.large{font-size:20px}section>p{margin:0}</style><main><section class=small><p>a</p></section><section class=large><p>b</p></section></main>",64,
        ).unwrap();
        let rules = stylesheets(&document).unwrap();
        let style_cache = core::cell::RefCell::default();
        let mut fragments = RetainedLayoutCache::default();
        let small = crate::selector::query_selector(&document, document.root(), ".small")
            .unwrap()
            .unwrap();
        // Grid items deliberately bypass the retained block cache. Their
        // ordinary block children are eligible, so this checks real replay
        // of the measured baseline before the parent shifts its contents.
        let small_text = crate::selector::query_selector(&document, document.root(), ".small p")
            .unwrap()
            .unwrap();
        for frame in 0..2 {
            fragments.begin_frame();
            let mut geometry = LayoutGeometry::default();
            let list = display_list_with_retained_layout(
                &document,
                100,
                100,
                &SizedText,
                &rules,
                None,
                Some(&mut geometry),
                &[],
                &style_cache,
                Some(&mut fragments),
            )
            .unwrap();
            let baselines = list
                .0
                .iter()
                .filter_map(|command| match command {
                    Command::GlyphRun { baseline_y, .. } => Some(*baseline_y),
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(baselines, [16.0, 16.0]);
            let hit = geometry.hits.iter().find(|hit| hit.node == small).unwrap();
            assert_eq!((hit.rect.y, hit.rect.height), (0.0, 40.0));
            let text_hit = geometry
                .hits
                .iter()
                .find(|hit| hit.node == small_text)
                .unwrap();
            assert_eq!(text_hit.rect.y, 8.0);
            if frame == 1 {
                assert!(fragments.stats().hits > 0);
            }
        }
    }

