    #[test]
    fn grid_retained_used_tracks_match_fractional_and_inherited_item_geometry() {
        for display in ["grid", "grid-lanes"] {
            let markup = alloc::format!(
                "<style>body{{margin:0}}</style><main id=parent style='display:{display};width:110px;gap:10px;grid-template-columns:[a] 1fr [b] 3fr [c]'><div style='height:5px;background:red'></div><div style='height:5px;background:blue'></div><section id=subgrid style='display:grid;grid-column:1/span 2;grid-template-columns:subgrid'><div style='height:5px;background:red'></div><div style='height:5px;background:blue'></div></section></main>"
            );
            let document = crate::html::parse(&markup, 64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            let list = display_list_with_styles(
                &document,
                200,
                100,
                &SizedText,
                &rules,
                None,
                Some(&mut geometry),
                &[],
            )
            .unwrap();
            let boxes = list
                .0
                .iter()
                .filter_map(|command| match command {
                    Command::FillRect { rect, color }
                        if color.r == 255 && color.g == 0 || color.b == 255 && color.g == 0 =>
                    {
                        Some((rect.x, rect.width))
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(
                boxes,
                [(0.0, 25.0), (35.0, 75.0), (0.0, 25.0), (35.0, 75.0)],
                "{display}"
            );
            for selector in ["#parent", "#subgrid"] {
                let node = crate::selector::query_selector(&document, document.root(), selector)
                    .unwrap()
                    .unwrap();
                let tracks = geometry
                    .hits
                    .iter()
                    .find(|hit| hit.node == node)
                    .unwrap()
                    .grid_tracks
                    .as_ref()
                    .unwrap();
                assert_eq!(&*tracks.columns, &[25.0, 75.0], "{display} {selector}");
                assert_eq!(
                    tracks
                        .column_names
                        .iter()
                        .map(|line| (line.name.as_ref(), line.line))
                        .collect::<Vec<_>>(),
                    [("a", 0), ("b", 1), ("c", 2)]
                );
            }
        }
    }

    #[test]
    fn outline_paints_outside_border_without_changing_flow_or_hit_geometry() {
        let document=crate::html::parse("<style>body{margin:0}</style><main style='padding:10px'><div id='box' style='width:30px;height:20px;border:3px solid red;color:blue;outline:2px dashed;outline-offset:4px;overflow:hidden'></div></main><aside style='height:5px;background:red'></aside>",64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        let list = display_list_with_styles(
            &document,
            100,
            100,
            &FixedText,
            &rules,
            None,
            Some(&mut geometry),
            &[],
        )
        .unwrap();
        assert!(list.0.iter().any(|command| matches!(command,Command::StrokePatternBorder{rect,width,color,pattern,..} if *width==2.0 && color.b==255 && *pattern==crate::paint::BorderPattern::Dashed && *rect==Rect{x:4.0,y:4.0,width:48.0,height:38.0})));
        assert!(geometry.hits.iter().any(|hit| hit.rect
            == Rect {
                x: 10.0,
                y: 10.0,
                width: 36.0,
                height: 26.0
            }));
        assert!(list.0.iter().any(|command|matches!(command,Command::FillRect{rect,color} if color.r==255 && rect.y==46.0 && rect.height==5.0)));
        let outline = list
            .0
            .iter()
            .position(
                |command| matches!(command,Command::StrokePatternBorder{color,..} if color.b==255),
            )
            .unwrap();
        assert!(
            !list.0[outline + 1..]
                .iter()
                .any(|command| matches!(command, Command::PopClip))
        );
    }

