    #[test]
    fn inline_atomic_strut_and_vertical_align_use_shared_line_metrics() {
        for (alignment, top, height) in [
            ("baseline", 6.0, 20.0),
            ("top", 0.0, 20.0),
            ("bottom", 10.0, 20.0),
            ("text-top", 0.0, 20.0),
            ("text-bottom", 10.0, 20.0),
            ("middle", 6.0, 20.0),
            ("3px", 3.0, 20.0),
            ("super", 1.0, 20.0),
            ("sub", 11.0, 21.0),
        ] {
            for display in ["inline-block", "inline-grid", "inline grid-lanes"] {
                let markup = alloc::format!(
                    "<style>html,body{{margin:0}}main{{font-size:20px;line-height:20px}}</style><main><span style='display:{display};vertical-align:{alignment};width:5px;height:10px;background:red'></span></main><footer style='height:2px;background:blue'></footer>"
                );
                let document = crate::html::parse(&markup, 64).unwrap();
                let list = display_list(&document, 100, 100, &SizedText).unwrap();
                let boxes = list
                    .0
                    .iter()
                    .filter_map(|command| match command {
                        Command::FillRect { rect, color }
                            if color.g == 0 && (color.r == 255 || color.b == 255) =>
                        {
                            Some(rect)
                        }
                        _ => None,
                    })
                    .collect::<Vec<_>>();
                assert_eq!(boxes.len(), 2, "{display} {alignment}");
                assert!(
                    (boxes[0].y - top).abs() < 0.001,
                    "{display} {alignment} {:?}",
                    boxes[0]
                );
                assert!(
                    (boxes[1].y - height).abs() < 0.001,
                    "{display} {alignment} {:?}",
                    boxes[1]
                );
            }
        }
    }

    #[test]
    fn inline_grid_first_and_inline_block_last_measured_baselines_align_with_parent_strut() {
        for (display, content, top, height, expected) in [
            (
                "inline-grid",
                "<div>a</div><div>b</div>",
                8.0,
                38.0,
                [16.0, 16.0, 26.0],
            ),
            ("inline-block", "a<br>b", 0.0, 30.0, [18.0, 8.0, 18.0]),
        ] {
            let markup = alloc::format!(
                "<style>html,body{{margin:0}}main{{font-size:20px;line-height:20px}}span{{font-size:10px;line-height:10px}}</style><main>Z<span id=atomic style='display:{display};width:20px;height:30px;grid-template-rows:10px 10px;background:red'>{content}</span></main><footer style='height:2px;background:blue'></footer>"
            );
            let document = crate::html::parse(&markup, 64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            let list = display_list_with_styles(
                &document,
                100,
                100,
                &SizedText,
                &rules,
                None,
                Some(&mut geometry),
                &[],
            )
            .unwrap();
            let baselines = list
                .0
                .iter()
                .filter_map(|command| match command {
                    Command::GlyphRun { baseline_y, .. } => Some(*baseline_y),
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(baselines, expected, "{display}");
            let node = crate::selector::query_selector(&document, document.root(), "#atomic")
                .unwrap()
                .unwrap();
            let hit = geometry.hits.iter().find(|hit| hit.node == node).unwrap();
            assert_eq!((hit.rect.y, hit.rect.height), (top, 30.0), "{display}");
            let footer = list
                .0
                .iter()
                .find_map(|command| match command {
                    Command::FillRect { rect, color } if color.b == 255 && color.g == 0 => {
                        Some(rect)
                    }
                    _ => None,
                })
                .unwrap();
            assert_eq!(footer.y, height, "{display}");
        }
    }

