    #[test]
    fn grid_intrinsic_height_constraints_size_tracks_before_item_paint() {
        for (constraint, height) in [
            ("max-height:10px", 10.0),
            ("min-height:20px;max-height:10px", 20.0),
            ("height:30px;max-height:10px", 10.0),
        ] {
            for box_sizing in ["", "box-sizing:border-box;padding:2px;border:1px solid;"] {
                for content in ["<div style='height:30px'></div>", ""] {
                    let markup = alloc::format!(
                        "<style>body{{margin:0}}</style><main style='display:grid;width:20px;grid-template-columns:20px;align-items:start'><div style='{box_sizing}{constraint};background:red'>{content}</div></main><footer style='height:2px;background:blue'></footer>"
                    );
                    if content.is_empty()
                        && !constraint.starts_with("height:")
                        && !constraint.starts_with("min-height:")
                    {
                        continue;
                    }
                    let boxes = grid_boxes(&markup);
                    assert_eq!(
                        (boxes[0].height, boxes[1].y),
                        (height, height),
                        "{constraint} {content}"
                    );
                }
            }
        }
        let boxes = grid_boxes(
            "<style>body{margin:0}</style><main style='display:grid;width:20px;grid-template-columns:20px;align-items:start'><canvas width=10 height=30 style='width:10px;max-height:10px;background:red'></canvas></main><footer style='height:2px;background:blue'></footer>",
        );
        assert_eq!(
            (boxes[0].height, boxes[1].y),
            (10.0, 10.0),
            "replaced intrinsic dimensions"
        );
        assert_eq!(boxes[0].width, 10.0, "replaced CSS width");
    }

    #[test]
    fn grid_auto_fit_retains_collapsed_zero_tracks_and_original_names_with_active_geometry() {
        for display in ["grid", "grid-lanes"] {
            for row in [false, true] {
                for empty in [false, true] {
                    let tracks = if row { "rows" } else { "columns" };
                    let size = if row {
                        "width:5px;height:160px"
                    } else {
                        "width:160px"
                    };
                    let children = if empty {
                        ""
                    } else if row {
                        "<div style='width:5px;background:red'></div><div style='width:5px;background:blue'></div>"
                    } else {
                        "<div style='height:5px;background:red'></div><div style='height:5px;background:blue'></div>"
                    };
                    let markup = alloc::format!(
                        "<style>body{{margin:0}}</style><main id=grid style='display:{display};{size};gap:10px;grid-lanes-direction:{direction};grid-template-{tracks}:repeat(auto-fit,[edge] minmax(30px,1fr))'>{children}</main>",
                        direction = if row { "row" } else { "column" }
                    );
                    let document = crate::html::parse(&markup, 64).unwrap();
                    let rules = stylesheets(&document).unwrap();
                    let mut geometry = LayoutGeometry::default();
                    let list = display_list_with_styles(
                        &document,
                        200,
                        200,
                        &SizedText,
                        &rules,
                        None,
                        Some(&mut geometry),
                        &[],
                    )
                    .unwrap();
                    let node = crate::selector::query_selector(&document, document.root(), "#grid")
                        .unwrap()
                        .unwrap();
                    let used = geometry
                        .hits
                        .iter()
                        .find(|hit| hit.node == node)
                        .unwrap()
                        .grid_tracks
                        .as_ref()
                        .unwrap();
                    let sizes = if row { &used.rows } else { &used.columns };
                    assert_eq!(
                        &**sizes,
                        if empty {
                            &[0.0, 0.0, 0.0, 0.0][..]
                        } else {
                            &[75.0, 75.0, 0.0, 0.0][..]
                        },
                        "{display} row={row} empty={empty}"
                    );
                    let names = if row {
                        &used.row_names
                    } else {
                        &used.column_names
                    };
                    assert_eq!(
                        names.iter().map(|name| name.line).collect::<Vec<_>>(),
                        [0, 1, 2, 3]
                    );
                    if !empty {
                        let boxes = list
                            .0
                            .iter()
                            .filter_map(|command| match command {
                                Command::FillRect { rect, color }
                                    if color.g == 0 && (color.r == 255 || color.b == 255) =>
                                {
                                    Some(if row {
                                        (rect.y, rect.height)
                                    } else {
                                        (rect.x, rect.width)
                                    })
                                }
                                _ => None,
                            })
                            .collect::<Vec<_>>();
                        assert_eq!(boxes, [(0.0, 75.0), (85.0, 75.0)], "{display} row={row}");
                    }
                }
            }
        }
    }

    #[test]
    fn grid_auto_fill_expands_to_fit_the_available_size() {
        // minmax(30px, 1fr): the 1fr max is indefinite for expansion, so the
        // 30px minimum drives floor((100+10)/(30+10)) = 2 repetitions.
        let boxes = grid_boxes(
            "<style>body{margin:0}</style><main style='display:grid;width:100px;gap:10px;grid-template-columns:repeat(auto-fill,minmax(30px,1fr))'><div style='height:5px;background:red'></div><div style='height:5px;background:blue'></div></main>",
        );
        assert_eq!(
            boxes.iter().map(|r| (r.x, r.width)).collect::<Vec<_>>(),
            [(0.0, 45.0), (55.0, 45.0)]
        );
    }

