    #[test]
    fn inline_grid_undecorated_margin_box_advance_and_wrapping_match_hit_geometry() {
        let document = crate::html::parse("<style>body{margin:0}</style><main style='width:70px'><i id='grid' style='display:inline-grid;grid-template-columns:20px 30px;gap:5px;margin-right:3px'><b style='width:10px;height:5px;background:red'></b></i><i id='next' style='display:inline grid-lanes;grid-template-columns:20px'><b style='height:5px;background:red'></b></i></main>",64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        let list = display_list_with_styles(
            &document,
            100,
            100,
            &FixedText,
            &rules,
            None,
            Some(&mut geometry),
            &[],
        )
        .unwrap();
        let node = |selector| {
            crate::selector::query_selector(&document, document.root(), selector)
                .unwrap()
                .unwrap()
        };
        let grid = geometry
            .hits
            .iter()
            .find(|hit| hit.node == node("#grid"))
            .unwrap()
            .rect;
        let next = geometry
            .hits
            .iter()
            .find(|hit| hit.node == node("#next"))
            .unwrap()
            .rect;
        assert_eq!(grid.width, 55.0);
        assert_eq!(next.width, 20.0);
        assert_eq!(next.x, 0.0);
        assert!(next.y > grid.y, "the whole second atomic container wraps");
        let boxes = list
            .0
            .iter()
            .filter_map(|command| match command {
                Command::FillRect { rect, color }
                    if color.r == 255 && color.g == 0 && color.b == 0 =>
                {
                    Some(*rect)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(boxes.len(), 2);
        assert_eq!(boxes[1].x, next.x);
        assert_eq!(boxes[1].y, next.y);
        let no_hits = grid_boxes(
            "<style>body{margin:0}</style><main style='width:100px'><i style='display:inline-grid;grid-template-columns:20px 30px;gap:5px'><b style='width:10px;height:5px;background:red'></b></i><i style='display:inline grid-lanes;grid-template-columns:20px'><b style='height:5px;background:red'></b></i></main>",
        );
        assert_eq!(no_hits.iter().map(|r| r.x).collect::<Vec<_>>(), [0.0, 55.0]);
    }

