    #[test]
    fn grid_lanes_and_grid_distributed_tracks_fall_back_to_safe_alignment_on_overflow() {
        for display in ["grid", "grid-lanes"] {
            for distribution in ["space-between", "space-around", "space-evenly"] {
                let markup = alloc::format!(
                    "<style>body{{margin:0}}</style><main style='display:{display};width:10px;height:20px;margin:30px;grid-template-columns:20px 20px;grid-template-rows:20px;column-gap:10px;justify-content:{distribution};align-content:start'><b style='height:20px;background:red'></b><b style='height:20px;background:red'></b></main>"
                );
                let boxes = grid_boxes(&markup);
                assert_eq!(
                    boxes
                        .iter()
                        .map(|r| (r.x, r.y, r.width, r.height))
                        .collect::<Vec<_>>(),
                    [(30.0, 30.0, 20.0, 20.0), (60.0, 30.0, 20.0, 20.0)],
                    "{display} {distribution}"
                );
            }
        }
    }

