    #[test]
    fn specification_multicol_constraints_plan_real_source_lines_before_painting() {
        let mut scratch=Vec::new();
        let mut lines=[css::columns::LineFragment::new(10.0);7];
        assert_eq!(css::columns::balanced_line_height(&mut lines,|line|line,3,2,3,&mut scratch),Some(30.0));
        assert_eq!(css::columns::plan_line_fragments(&mut lines,|line|line,30.0,2,3,&mut scratch,true),Some(3));
        assert_eq!(lines.iter().enumerate().filter_map(|(index,line)|line.fragment_start.then_some(index)).collect::<Vec<_>>(),[3,4],"the one-line middle fragment is bounded by legal paragraph source cuts");
        let mut lines=[css::columns::LineFragment::new(10.0);8];
        assert_eq!(css::columns::balanced_line_height(&mut lines,|line|line,3,2,3,&mut scratch),Some(30.0),"both cuts reserve three terminal paragraph lines");
        assert_eq!(css::columns::plan_line_fragments(&mut lines,|line|line,30.0,2,3,&mut scratch,true),Some(3));
        assert_eq!(lines.iter().enumerate().filter_map(|(index,line)|line.fragment_start.then_some(index)).collect::<Vec<_>>(),[3,5]);
        for (constraints,height,expected) in [
            ("",30.0,[0.0,0.0,0.0]),
            ("orphans:1;widows:1",10.0,[0.0,20.0,40.0]),
            ("orphans:3;widows:2",30.0,[0.0,0.0,0.0]),
        ] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#flow{{width:60px;columns:3;column-gap:0;text-align:left;font:10px/10px monospace;{constraints}}}</style><div id=flow>A<br>B<br>C</div>"),64).unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let list=session.display_list(200,100,&RecordingText::default()).unwrap().clone();
            let glyphs=list.0.iter().filter_map(|command|match command {Command::GlyphRun{origin_x,baseline_y,glyphs,..} if !glyphs.is_empty()=>Some((*origin_x,*baseline_y)),_=>None}).collect::<Vec<_>>();
            assert_eq!(glyphs.iter().map(|(x,_)|*x).collect::<Vec<_>>(),expected,"{constraints}");
            let flow=crate::selector::query_selector(session.document(),session.document().root(),"#flow").unwrap().unwrap();
            assert_eq!(session.layout_rect(flow).unwrap().height,height,"{constraints}");
            assert_eq!(session.display_list(200,100,&RecordingText::default()).unwrap(),&list);
            assert_eq!(display_list(session.document(),200,100,&RecordingText::default()).unwrap(),list);
        }
        let document=crate::html::parse("<style>html,body{margin:0}#flow{width:80px;height:40px;columns:4;column-gap:0;column-fill:auto;orphans:1;widows:3;font:10px/10px monospace}</style><div id=flow>1<br>2<br>3<br>4<br>5<br>6<br>7<br>8<br>9</div>",64).unwrap();
        let list=display_list(&document,200,100,&RecordingText::default()).unwrap();
        let xs=list.0.iter().filter_map(|command|match command {Command::GlyphRun{origin_x,glyphs,..} if !glyphs.is_empty()=>Some(*origin_x),_=>None}).collect::<Vec<_>>();
        assert_eq!(xs,[0.0,0.0,0.0,0.0,20.0,20.0,40.0,40.0,40.0],"Rule 3 counts the paragraph source on either side of cuts4/6, yielding4+2+3");
        // There is no allowed two-line fragment at this fixed 10px height.
        // Rule 3 relaxes, using whole lines in overflow fragmentainers.
        let document=crate::html::parse("<style>html,body{margin:0}#flow{width:40px;height:10px;columns:2;column-gap:0;column-fill:auto;font:10px/10px monospace}</style><div id=flow>A<br>B<br>C</div>",64).unwrap();
        let list=display_list(&document,200,100,&RecordingText::default()).unwrap();
        let glyphs=list.0.iter().filter_map(|command|match command {Command::GlyphRun{origin_x,baseline_y,glyphs,..} if !glyphs.is_empty()=>Some((*origin_x,*baseline_y)),_=>None}).collect::<Vec<_>>();
        assert_eq!(glyphs.iter().map(|(x,_)|*x).collect::<Vec<_>>(),[0.0,20.0,40.0]);
        assert!(glyphs.windows(2).all(|pair|pair[0].1==pair[1].1));
    }

    #[test]
    fn specification_lexical_fallback_uses_whole_context_shapes_and_intrinsic_width() {
        struct ContextText;
        impl TextShaper for ContextText {
            fn shape(&self,text:&str,_size:f32)->Result<ShapedRun,()> {
                let count=text.chars().count();
                Ok(ShapedRun { glyphs:text.char_indices().enumerate().map(|(index,(at,ch))|crate::paint::Glyph {
                    id:ch as u16+count as u16*10,face:0,cluster:at as u32,caps_expansion:0,
                    x:index as f32*6.0,y:0.0,size_scale:1.0,
                }).collect::<Vec<_>>().into(),width:count as f32*6.0 })
            }
            fn shape_resolved_with_cluster_advances(&self,text:&str,size:f32,_rtl:bool,_font:&FontSpec)
                ->Result<Option<crate::paint::ShapedRunWithClusterAdvances>,()> {
                Ok(Some(crate::paint::ShapedRunWithClusterAdvances {
                    run:self.shape(text,size)?,clusters:lumen_common::ucd::graphemes(text)
                        .map(|(at,unit)|crate::paint::ShapedClusterAdvance{source:at..at+unit.len(),advance:unit.chars().count() as f32*6.0})
                        .collect::<Vec<_>>().into(),
                }))
            }
            fn ascent(&self,_size:f32)->f32 {10.0}
            fn line_height(&self,_size:f32)->f32 {10.0}
        }
        for text in ["กขค","កខគ","ꦏꦑꦒ","ᬓᬔᬕ"] {for policy in ["normal","keep-all","auto-phrase"] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}main{{width:min-content;font:10px/10px monospace;word-break:{policy}}}</style><main>{text}</main>"),64).unwrap();
            let main=crate::selector::query_selector(&document,document.root(),"main").unwrap().unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let list=session.display_list(200,100,&ContextText).unwrap().clone();
            assert_eq!(session.layout_rect(main).unwrap().width,6.0,"{text}/{policy}: fallback contributes to min-content");
            let mut glyphs=Vec::new();let mut baselines=Vec::new();
            for command in &list.0 {if let Command::GlyphRun{glyphs:run,baseline_y,..}=command {
                glyphs.extend(run.iter().map(|glyph|glyph.id));baselines.push(*baseline_y);
            }}
            baselines.sort_by(f32::total_cmp);baselines.dedup();assert_eq!(baselines.len(),3);
            assert_eq!(glyphs,text.chars().map(|ch|ch as u16+30).collect::<Vec<_>>(),"fallback retains the entire word's contextual forms");
            assert_eq!(session.display_list(200,100,&ContextText).unwrap(),&list);
            assert_eq!(display_list(session.document(),200,100,&ContextText).unwrap(),list);
        }}
    }

    #[test]
    fn specification_multicol_generated_principals_measure_their_actual_inline_payload() {
        for marker in [false,true] {
            let mut expected=None;let mut changed_expected=None;
            for source in ["ordinary","before","after"] {
                let selector=match source{"ordinary"=>"#host","before"=>"#host::before",_=>"#host::after"};
                let wide=selector.replace("#host","#host.wide");
                let display=if marker{"list-item"}else{"block"};
                let content=if source=="ordinary"{""}else{"content:'A\\a B\\a C\\a D';"};
                let text=if source=="ordinary"{"A\nB\nC\nD"}else{"S"};
                let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#host{{width:90px;margin-left:100px;font:10px/10px monospace;white-space:pre;orphans:1;widows:1}}{selector}{{display:{display};width:90px;columns:2;column-gap:10px;column-fill:auto;height:20px;list-style-position:inside;list-style-type:decimal;{content}}}{wide}{{width:190px;columns:4;height:auto;column-fill:balance}}</style><div id=host>{text}</div>"),96).unwrap();
                let mut session=crate::session::RenderSession::new(document);
                let host=crate::selector::query_selector(session.document(),session.document().root(),"#host").unwrap().unwrap();
                let top=if source=="after"{10.0}else{0.0};
                let extract=|list:&DisplayList,height:f32|list.0.iter().filter_map(|command|match command {
                    Command::GlyphRun{origin_x,baseline_y,glyphs,..} if !glyphs.is_empty() && *baseline_y>top && *baseline_y<=top+height=>Some((*origin_x,*baseline_y-top,glyphs.to_vec())),_=>None,
                }).collect::<Vec<_>>();
                let list=session.display_list(400,100,&RecordingText::default()).unwrap().clone();
                let positions=extract(&list,20.0);assert!(!positions.is_empty());
                if let Some(expected)=expected.as_ref(){assert_eq!(&positions,expected,"{source} marker={marker}: generated source uses the same columns and inline payload as an ordinary principal");}
                else{expected=Some(positions);}
                assert_eq!(session.layout_rect(host).unwrap().height,if source=="ordinary"{20.0}else{30.0});
                assert_eq!(session.display_list(400,100,&RecordingText::default()).unwrap(),&list);
                assert_eq!(display_list(session.document(),400,100,&RecordingText::default()).unwrap(),list);
                session.document_mut().set_attribute(host,"class","wide").unwrap();
                let changed=session.display_list(400,100,&RecordingText::default()).unwrap().clone();
                let positions=extract(&changed,10.0);assert!(!positions.is_empty());
                if let Some(expected)=changed_expected.as_ref(){assert_eq!(&positions,expected,"mutation reselects generated source columns without a stale origin-DOM measurement");}
                else{changed_expected=Some(positions);}
                assert_eq!(session.layout_rect(host).unwrap().height,if source=="ordinary"{10.0}else{20.0});
                assert_eq!(session.display_list(400,100,&RecordingText::default()).unwrap(),&changed);
                assert_eq!(display_list(session.document(),400,100,&RecordingText::default()).unwrap(),changed);
            }
        }
    }

    #[test]
    fn specification_multicol_zero_source_after_overflow_moves_to_the_next_column() {
        use css::columns::{LineFragment,PrincipalSourceSpan,PrincipalTrialScratch,plan_principal_sources};
        for forest in [false,true] {
            let mut lines=alloc::vec![LineFragment::new(20.0),LineFragment::new(0.0),LineFragment::new(5.0)];
            lines[1].continuous=true;lines[2].continuous=true;
            let owners=if forest{alloc::vec![PrincipalSourceSpan{start:0,end:3,parent:usize::MAX,height:20.0,avoid_inside:false}]}else{Vec::new()};
            let mut placements=Vec::new();let mut gaps=Vec::new();let mut scratch=PrincipalTrialScratch::default();
            assert_eq!(plan_principal_sources(&mut lines,|line|line,&owners,10.0,10.0,
                &mut placements,&mut gaps,&mut scratch,true,MAX_DISPLAY_COMMANDS),Some(2));
            assert_eq!(placements.iter().map(|source|(source.position.column,source.position.offset)).collect::<Vec<_>>(),[(0,0.0),(1,0.0),(1,0.0)]);
        }
        for height in [10,20] {
            for direction in ["ltr","rtl"] {
                let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#flow{{width:90px;margin-left:100px;columns:2;column-gap:10px;column-fill:auto;height:10px;direction:{direction}}}#principal{{height:20px}}#first{{contain:size;height:{height}px}}#zero{{height:0}}#next{{height:5px}}</style><div id=flow><div id=principal><div id=first></div><div id=zero></div><div id=next></div></div></div>"),96).unwrap();
                let mut session=crate::session::RenderSession::new(document);
                let list=session.display_list(400,100,&RecordingText::default()).unwrap().clone();
                let get=|selector|crate::selector::query_selector(session.document(),session.document().root(),selector).unwrap().unwrap();
                let x=|column:usize|100.0+if direction=="rtl"{50.0-column as f32*50.0}else{column as f32*50.0};
                assert_eq!(session.layout_rect(get("#zero")).unwrap(),Rect{x:x(usize::from(height>10)),y:if height>10{0.0}else{10.0},width:40.0,height:0.0});
                assert_eq!(session.layout_rect(get("#next")).unwrap(),Rect{x:x(1),y:0.0,width:40.0,height:5.0});
                assert_eq!(session.display_list(400,100,&RecordingText::default()).unwrap(),&list);
                assert_eq!(display_list(session.document(),400,100,&RecordingText::default()).unwrap(),list);
            }
        }
    }

    #[test]
    fn specification_fragment_fixed_terminal_edge_keeps_parallel_child_ink_and_surface_order() {
        let document=crate::html::parse("<style>html,body{margin:0}#flow{width:120px;columns:2;column-gap:20px;column-fill:auto;height:100px}#box{height:70px;border-top:15px solid blue;border-bottom:15px solid pink;background:yellow;box-decoration-break:clone}#child{height:185px;background:lime}</style><div id=flow><section id=box><div id=child></div></section></div>",96).unwrap();
        let mut session=crate::session::RenderSession::new(document);let text=RecordingText::default();
        let list=session.display_list(250,150,&text).unwrap().clone();
        let node=crate::selector::query_selector(session.document(),session.document().root(),"#child").unwrap().unwrap();
        assert_eq!(session.client_rects(node).iter().map(|rect|(rect.x,rect.y,rect.height)).collect::<Vec<_>>(),[(0.0,15.0,85.0),(70.0,0.0,100.0)]);
        let lime=list.0.iter().enumerate().filter_map(|(at,command)|match command{Command::FillRect{rect,color}if color.r==0 && color.g==255 && color.b==0=>Some((at,*rect)),_=>None}).collect::<Vec<_>>();
        assert_eq!(lime.iter().map(|(_,rect)|(rect.x,rect.y,rect.height)).collect::<Vec<_>>(),[(0.0,15.0,85.0),(70.0,0.0,100.0)]);
        let surfaces=list.0.iter().enumerate().filter_map(|(at,command)|match command{Command::FillRect{color,..}if color.r==255 && color.g==255 && color.b==0=>Some(at),Command::StrokeBoxBorder(_)=>Some(at),_=>None}).collect::<Vec<_>>();
        assert!(!surfaces.is_empty());assert!(surfaces.iter().all(|at|*at<lime[0].0),"terminal decorations stay below the child's actual parallel overflow");
        assert_eq!(session.display_list(250,150,&text).unwrap(),&list);
        assert_eq!(display_list(session.document(),250,150,&text).unwrap(),list);
    }

    #[test]
    fn specification_fragment_continuous_child_omits_ancestor_edges_and_empty_gaps_dispatch_completely() {
        for border_box in [false,true] {
            let sizing=if border_box{"box-sizing:border-box"}else{""};
            for fixed in [false,true] {
                let height=if fixed{"height:60px"}else{""};
                let child=if fixed{alloc::format!("<div id=next style='height:{}px;background:lime'></div>",if border_box{30}else{20})}
                    else{"".into()};
                let content=if fixed{""}else{"<div id=child style='height:80px;background:lime'></div>"};
                let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#flow{{width:120px;columns:2;column-gap:20px;column-fill:auto;height:50px}}#box{{padding:3px;border:2px solid blue;background:yellow;box-decoration-break:clone;{height};{sizing}}}</style><div id=flow><section id=box>{content}</section>{child}</div>"),96).unwrap();
                let mut session=crate::session::RenderSession::new(document);let text=RecordingText::default();
                let list=session.display_list(250,100,&text)
                    .unwrap_or_else(|error|panic!("fragment source dispatch: border_box={border_box}, fixed={fixed}, {error:?}"))
                    .clone();
                let pieces=|color:Rgba|list.0.iter().filter_map(|command|match command{Command::FillRect{rect,color:paint}if *paint==color=>Some((rect.x,rect.y,rect.height)),_=>None}).collect::<Vec<_>>();
                let end=if border_box{10.0}else{30.0};
                assert_eq!(pieces(Rgba{r:255,g:255,b:0,a:255}),[(0.0,0.0,50.0),(70.0,0.0,if fixed{end}else{50.0})]);
                let lime=pieces(Rgba{r:0,g:255,b:0,a:255});
                if fixed {assert_eq!(lime,[(70.0,end,if border_box{30.0}else{20.0})]);}
                else {assert_eq!(lime,[(5.0,5.0,40.0),(75.0,5.0,40.0)],"child ink excludes both continuing ancestor clone edges");}
                let selector=if fixed{"#next"}else{"#child"};
                let node=crate::selector::query_selector(session.document(),session.document().root(),selector).unwrap().unwrap();
                let rects=session.client_rects(node);
                assert_eq!(rects.iter().map(|rect|(rect.x,rect.y,rect.height)).collect::<Vec<_>>(),lime,
                    "hit fragments use exactly the same scoped source pieces as child paint");
                assert_eq!(session.display_list(250,100,&text).unwrap(),&list);
                assert_eq!(display_list(session.document(),250,100,&text).unwrap(),list);
            }
        }
    }

    #[test]
    fn specification_fragment_flow_root_keeps_bfc_source_and_shared_fragment_payloads() {
        for direction in ["ltr","rtl"] {
            for generated in [false,true] {
                let source=if generated {"#host::before{content:'A\\a B\\a C\\a D';white-space:pre;display:flow-root}"}
                    else {"#box{display:flow-root}"};
                let markup=if generated {"<div id=host></div>"}
                    else {"<div id=box>A<br>B<br>C<br>D</div>"};
                let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#flow{{width:100px;columns:2;column-gap:20px;height:30px;column-fill:auto;direction:{direction};font:10px/10px monospace;orphans:1;widows:1}}#box,#host::before{{border:5px solid blue;background:lime;box-decoration-break:clone}}{source}</style><div id=flow>{markup}</div>"),96).unwrap();
                let mut session=crate::session::RenderSession::new(document);let text=RecordingText::default();
                let list=session.display_list(250,100,&text).unwrap().clone();
                let host=crate::selector::query_selector(session.document(),session.document().root(),
                    if generated{"#host"}else{"#box"}).unwrap().unwrap();
                let left=if direction=="rtl"{60.0}else{0.0};let right=60.0-left;
                let rects=list.0.iter().filter_map(|command|match command {
                    Command::FillRect{rect,color}if *color==Rgba{r:0,g:255,b:0,a:255}=>Some(*rect),_=>None,
                }).collect::<Vec<_>>();
                assert_eq!(rects,[Rect{x:left,y:0.0,width:40.0,height:30.0},Rect{x:right,y:0.0,width:40.0,height:30.0}],
                    "BFC principal uses the enclosing columns and actual clone edges");
                let glyphs=list.0.iter().filter_map(|command|match command {
                    Command::GlyphRun{origin_x,glyphs,..}if !glyphs.is_empty()=>Some(*origin_x),_=>None,
                }).collect::<Vec<_>>();
                assert_eq!(glyphs.len(),4);assert_eq!(&glyphs[..2],&glyphs[2..].iter().map(|x|x-(right-left)).collect::<Vec<_>>());
                if !generated {assert_eq!(session.client_rects(host),rects.as_slice());}
                assert_eq!(session.display_list(250,100,&text).unwrap(),&list);
                assert_eq!(display_list(session.document(),250,100,&text).unwrap(),list);
            }
        }
    }

