            assert_eq!(glyphs.len(),4);
            assert!(glyphs.iter().all(|(x,_)|*x==0.0),"{containment}: complete contents remain in the zero-size source's first column");
            assert!(glyphs.windows(2).all(|pair|pair[1].1-pair[0].1==10.0));
            assert!(!list.0.iter().any(|command|matches!(command,Command::FillRect{color,..} if (color.r,color.g,color.b)==(255,0,0))),"one occupied column has no separating rule");
