    #[test]
    fn specification_multicol_inline_fragments_and_rtl_use_final_column_coordinates() {
        for (direction,expected) in [("ltr",[0.0,20.0,40.0]),("rtl",[40.0,20.0,0.0])] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#flow{{width:60px;columns:3;column-gap:0;direction:{direction};text-align:left;orphans:1;widows:1;font:10px/10px monospace}}span{{background:red}}</style><div id=flow><span>A<br>B<br>C</span></div>"),64).unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,200,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let spans=list.0.iter().filter_map(|command|match command {Command::FillRect{rect,color} if (color.r,color.g,color.b)==(255,0,0)=>Some(*rect),_=>None}).collect::<Vec<_>>();
            assert_eq!(spans.len(),3);assert_eq!(spans.iter().map(|rect|rect.x).collect::<Vec<_>>(),expected);
            assert!(spans.windows(2).all(|pair|pair[0].y==pair[1].y));
            let span=crate::selector::query_selector(&document,document.root(),"span").unwrap().unwrap();
            let hit=geometry.hits.iter().position(|hit|hit.node==span&&!hit.virtual_generated).unwrap();
            let parts=geometry.hit_rects(hit);assert_eq!(parts.len(),3);
            assert_eq!(parts.iter().map(|rect|rect.x).collect::<Vec<_>>(),expected);
        }
    }

    #[test]
    fn specification_multicol_applies_to_list_and_table_flow_containers() {
        let content="<b></b><b></b>";
        for (name,owner) in [
            ("block",alloc::format!("<main class=flow>{content}</main>")),
            ("list-item",alloc::format!("<li class=flow>{content}</li>")),
            ("caption",alloc::format!("<table><caption class=flow>{content}</caption></table>")),
            ("cell",alloc::format!("<table><tr><td class=flow>{content}</td></tr></table>")),
        ] {
            let markup=alloc::format!("<style>html,body{{margin:0}}table{{border-spacing:0}}.flow{{width:40px;columns:2;column-gap:0;list-style:none;padding:0;border:0}}b{{display:block;height:5px;background:red}}</style>{owner}");
            let boxes=colored_boxes_in(&markup,100,100);
            assert_eq!(boxes.iter().map(|rect|(rect.x,rect.y,rect.width,rect.height)).collect::<Vec<_>>(),
                [(0.0,0.0,20.0,5.0),(20.0,0.0,20.0,5.0)],"{name}: native block-container flow owns its columns");
        }
        for display in [Display::Flex,Display::Grid,Display::Table,Display::InlineTable] {
            let mut style=Style::initial();style.display=display;style.column_count=Some(2);
            assert!(!css::columns::active(&style),"the columns do not replace another layout model");
        }
    }

