                let doc=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}main{{writing-mode:{mode};width:60px;height:80px;font:20px/24px monospace;text-decoration:{decoration} red;text-underline-position:{position}}}</style><main>AB</main>"),32).unwrap();
