    #[test]
    fn template_subtrees_are_inert_for_style_paint_and_inline_flow() {
        let document = crate::html::parse(
            "<style>body{margin:0}</style><p>a<template><style>p{background:red}</style><b>hidden</b></template>b</p>",
            24,
        )
        .unwrap();
        let list = display_list(&document, 100, 30, &FixedText).unwrap();
        let runs: Vec<_> = list
            .0
            .iter()
            .filter_map(|command| match command {
                Command::GlyphRun {
                    origin_x,
                    baseline_y,
                    ..
                } => Some((*origin_x, *baseline_y)),
                _ => None,
            })
            .collect();
        // The inert template contributes no boundary; the two adjacent text
        // nodes retain one shaping run.
        assert_eq!(runs, [(0.0, 2.0)]);
        assert!(!list.0.iter().any(|command| matches!(command, Command::FillRect { color, .. } if color.r == 255 && color.g == 0)));
    }

    #[test]
    fn foreign_namespace_elements_are_inert() {
        let mut document = crate::html::parse("<body></body>", 16).unwrap();
        let body = crate::selector::query_selector(&document, document.root(), "body")
            .unwrap()
            .unwrap();
        let foreign = document
            .create(NodeKind::Element {
                namespace: Namespace::Svg,
                name: "div".into(),
                attributes: alloc::vec![(
                    "style".into(),
                    "background:red;width:10px;height:10px".into()
                )],
            })
            .unwrap();
        document.append(body, foreign).unwrap();
        let text = document.create(NodeKind::Text("inert".into())).unwrap();
        document.append(foreign, text).unwrap();
        let list = display_list(&document, 20, 20, &NoShape).unwrap();
        assert_eq!(list.0.len(), 1);
    }

    impl TextShaper for FixedText {
        fn primary_character_widths_styled(&self, size: f32, _: &FontSpec) -> Option<crate::paint::PrimaryCharacterWidths> {
            let _ = size;
            Some(crate::paint::PrimaryCharacterWidths { average: 2.0, maximum: 2.0 })
        }
        fn shape(&self, text: &str, _: f32) -> Result<ShapedRun, ()> {
            Ok(ShapedRun {
                glyphs: Arc::from([]),
                width: text.len() as f32 * 2.0,
            })
        }
        fn ascent(&self, _: f32) -> f32 {
            2.0
        }
        fn line_height(&self, _: f32) -> f32 {
            3.0
        }
    }

    fn visible_overflow_glyphs(list:&DisplayList)->Vec<u16> {
            let mut matrix=Affine::IDENTITY;let mut transforms=Vec::new();let mut clips:Vec<(Affine,Rect)>=Vec::new();let mut layers=Vec::new();let mut result=Vec::new();
            for command in &list.0 {match command {
                Command::PushTransform(value)=>{transforms.push(matrix);matrix=matrix.then(*value);},
                Command::PopTransform=>matrix=transforms.pop().unwrap(),
                Command::PushClip(rect) | Command::PushBoxClip(rect)=>clips.push((matrix.inverse().unwrap(),*rect)),
                Command::PopClip=>{clips.pop().unwrap();},
                Command::PushLayer{clip,rect,..}=>{layers.push(*clip);if *clip{clips.push((matrix.inverse().unwrap(),*rect));}},
                Command::PopLayer=>{if layers.pop().unwrap(){clips.pop().unwrap();}},
                Command::GlyphRun{origin_x,baseline_y,color,glyphs,..} if color.a!=0=>{
                    for glyph in glyphs.iter(){let point=matrix.apply(origin_x+glyph.x+0.1,baseline_y+glyph.y-0.1);
                        if clips.iter().all(|(inverse,clip)|{let point=inverse.apply(point.0,point.1);clip.contains_rounded(point.0,point.1,0.0)}){result.push(glyph.id);}
                    }
                },_=>{}
            }}
            assert!(transforms.is_empty()&&clips.is_empty()&&layers.is_empty());result
        }

    #[test]
    fn specification_text_overflow_actual_paint_preserves_sources_geometry_and_replay() {
        let visible = visible_overflow_glyphs;
        let make=|policy:&str,content:&str,width:u32,extra:&str|crate::html::parse(&alloc::format!(
            "<!doctype html><style>body{{margin:0}}#target{{font:10px/16px monospace;width:{width}px;white-space:nowrap;overflow:hidden;text-overflow:{policy};{extra}}}</style><div id=target>{content}</div>"),128).unwrap();
        let render=|document:&Document,scrolls:&[ScrollOffset]|{let rules=stylesheets(document).unwrap();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),scrolls).unwrap();(list,geometry)};
        let clipped=make("clip","ABCDEFG",30,"");let elided=make("ellipsis","ABCDEFG",30,"");
        let (clip,clip_geometry)=render(&clipped,&[]);let (ellipsis,geometry)=render(&elided,&[]);
        assert_eq!(visible(&ellipsis),alloc::vec![u16::from(b'A'),u16::from(b'B'),u16::from(b'C'),u16::from(b'D'),0x2026]);
        assert!(!visible(&clip).contains(&0x2026));
        let boxes=|geometry:&LayoutGeometry|geometry.hits.iter().map(|hit|hit.rect).collect::<Vec<_>>();
        assert_eq!(boxes(&clip_geometry),boxes(&geometry),"elision changes paint, never real hit or line geometry");
        let extents=|geometry:&LayoutGeometry|geometry.scroll_extents.iter().map(|value|(value.min_x,value.max_x,value.min_y,value.max_y)).collect::<Vec<_>>();
        assert_eq!(extents(&clip_geometry),extents(&geometry));
        assert!(ellipsis.0.iter().any(|command|matches!(command,Command::GlyphRun{glyphs,..} if glyphs.len()==7)),"original immutable glyph payload is retained behind actual clips");
        let target=crate::selector::query_selector(&elided,elided.root(),"#target").unwrap().unwrap();
        let text=elided.first_child(target).unwrap().unwrap();
        assert!(matches!(elided.kind(text),Ok(NodeKind::Text(value)) if value=="ABCDEFG"));
        let (scrolled,_)=render(&elided,&[ScrollOffset{node:target,x:12.0,y:0.0}]);
        assert!(!visible(&scrolled).contains(&0x2026),"marker disappears when scrolling reveals the real end edge");
        let mut session=crate::session::RenderSession::new(elided);session.display_list(200,200,&RecordingText::default()).unwrap();
        let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
        let fresh=display_list(session.document(),200,200,&RecordingText::default()).unwrap();
        assert_eq!(retained,fresh,"rare source plans and their anchors survive actual retained replay");
        let narrow=make("ellipsis","A\u{301}BCDE",9,"");let (list,_)=render(&narrow,&[]);
        let painted=visible(&list);assert!(painted.contains(&u16::from(b'A'))&&painted.contains(&0x301));
        assert!(!painted.contains(&u16::from(b'B'))&&!painted.contains(&0x2026),"first whole grapheme clips instead of being replaced by an overlapping marker");
        for extra in ["direction:rtl","height:30px;width:16px;writing-mode:vertical-rl","height:30px;width:16px;writing-mode:vertical-lr"] {
            let document=make("ellipsis","ABCDEFG",30,extra);let (list,_)=render(&document,&[]);
            if extra == "direction:rtl" {
                assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{origin_x,glyphs,..} if *origin_x<0.0&&glyphs.len()==7)),
                    "RTL overflowing source retains end alignment before paint elision");
            }
            assert!(visible(&list).contains(&0x2026),"actual directional/vertical line end elides: {extra}");
            assert_eq!(visible(&list).len(),5,"whole typographic units fit the actual inline edge: {extra}");
        }
        let document=make("ellipsis","<span style='position:relative;left:6px'>ABCDEFG</span>",30,"");let (list,_)=render(&document,&[]);
        assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{origin_x,glyphs,..} if *origin_x==6.0&&glyphs.len()==7)),
            "relative inline provenance preserves the actual shifted source pen");
        assert!(visible(&list).contains(&0x2026));assert!(!visible(&list).contains(&u16::from(b'G')),"ordinary relative inline provenance is character based");
        let document=make("ellipsis","A<span style='display:inline-block;width:24px;height:16px;opacity:.3;transform:rotate(10deg)'>XYZ</span>",18,"");
        let (list,geometry)=render(&document,&[]);
        let baseline_for = |glyph_id:u16| list.0.iter().find_map(|command|match command {
            Command::GlyphRun{baseline_y,glyphs,..} if glyphs.iter().any(|glyph|glyph.id==glyph_id)=>Some(*baseline_y), _=>None,
        });
        assert_eq!(baseline_for(u16::from(b'A')),baseline_for(u16::from(b'X')),
            "nowrap preserves the atomic source on the same normal-flow baseline before its transform");
        assert!(!geometry.transforms.is_empty() && list.0.iter().any(|command|matches!(command,Command::PushLayer{opacity,..} if *opacity==0.3)),
            "elision preserves the atomic box's actual transform and opacity ownership");
        assert_eq!(visible(&list),alloc::vec![u16::from(b'A'),0x2026],"transformed self-painting atomic source elides as a whole, with exact line-plane clip scopes");
        assert!(geometry.hits.iter().any(|hit|hit.rect.width>=24.0),"paint-hidden atomic box retains its actual full hit target");
        let document=make("ellipsis","<span style='display:inline-block;width:60px;height:16px'>XYZ</span>",12,"");
        let (list,_)=render(&document,&[]);
        assert!(visible(&list).contains(&u16::from(b'X'))&&!visible(&list).contains(&0x2026),"first atomic inline clips instead of disappearing for a marker");
        let document=make("ellipsis","ABCDEFG<br>ABCDEFG",30,"");let (list,_)=render(&document,&[]);
        assert_eq!(visible(&list).iter().filter(|id|**id==0x2026).count(),2,"each actual overflowing line owns its own marker");

    }

    #[test]
    fn specification_text_overflow_custom_pair_paint_scroll_axes_and_replay() {
        let make=|policy:&str,content:&str,width:u32,extra:&str|crate::html::parse(&alloc::format!(
            "<!doctype html><style>body{{margin:0}}#target{{font:10px/16px monospace;width:{width}px;white-space:nowrap;overflow:hidden;text-overflow:{policy};{extra}}}</style><div id=target>{content}</div>"),128).unwrap();
        let render=|document:&Document,scrolls:&[ScrollOffset]|{let rules=stylesheets(document).unwrap();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),scrolls).unwrap();(list,geometry)};
        let ids=|value:&str|value.chars().map(|c|c as u16).collect::<Vec<_>>();
        for (policy,width,expected) in [("'XY'",30,"ABCXY"),("'123456789'",18,"A12"),("''",15,"AB")] {
            let document=make(policy,"ABCDEFG",width,"");let (list,geometry)=render(&document,&[]);
            assert_eq!(visible_overflow_glyphs(&list),ids(expected),"custom marker uses actual font advances and clips its far end: {policy}");
            let reference=make("clip","ABCDEFG",width,"");let (_,reference)=render(&reference,&[]);
            assert_eq!(geometry.hits.iter().map(|hit|hit.rect).collect::<Vec<_>>(),reference.hits.iter().map(|hit|hit.rect).collect::<Vec<_>>());
            assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{glyphs,..} if glyphs.len()==7)),"source glyph Arc remains intact");
        }
        let content="ABCDEFGHIJKLMNOP";
        for extra in ["", "direction:rtl;text-align:left", "height:30px;width:16px;writing-mode:vertical-rl", "height:30px;width:16px;writing-mode:vertical-lr"] {
            let document=make("'L' 'R'",content,30,extra);
            let target=crate::selector::query_selector(&document,document.root(),"#target").unwrap().unwrap();
            let vertical=extra.contains("writing-mode");
            let scroll=ScrollOffset{node:target,x:if vertical{0.0}else{24.0},y:if vertical{24.0}else{0.0}};
            let (list,geometry)=render(&document,&[scroll]);
            assert_eq!(visible_overflow_glyphs(&list),ids("FGHLR"),"physical pair stays line-left/right in each direction/axis: {extra}");
            let text=document.first_child(target).unwrap().unwrap();
            assert!(matches!(document.kind(text),Ok(NodeKind::Text(value)) if value==content));
            let reference=make("clip",content,30,extra);
            let reference_target=crate::selector::query_selector(&reference,reference.root(),"#target").unwrap().unwrap();
            let (_,reference_geometry)=render(&reference,&[ScrollOffset{node:reference_target,..scroll}]);
            assert_eq!(geometry.hits.iter().map(|hit|hit.rect).collect::<Vec<_>>(),reference_geometry.hits.iter().map(|hit|hit.rect).collect::<Vec<_>>());
            let mut session=crate::session::RenderSession::new(document);
            session.display_list(200,200,&RecordingText::default()).unwrap();
            session.set_scroll_offset(target,scroll.x,scroll.y).unwrap();
            session.display_list(200,200,&RecordingText::default()).unwrap();
            let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
            let applied=session.scroll_offset(target);
            let fresh=render(session.document(),&[ScrollOffset{node:target,x:applied.0,y:applied.1}]).0;
            assert_eq!(retained,fresh,"both marker ranges survive retained replay");
            session.set_scroll_offset(target,0.0,0.0).unwrap();
            let restored=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
            assert_eq!(restored,render(session.document(),&[]).0,"scroll restoration recomputes edge presence");
        }
        for (extra,expected) in [("",'R'),("direction:rtl;text-align:left",'L')] {
            let document=make("'L' 'R'",content,6,extra);
            let target=crate::selector::query_selector(&document,document.root(),"#target").unwrap().unwrap();
            let (list,_)=render(&document,&[ScrollOffset{node:target,x:24.0,y:0.0}]);
            assert_eq!(visible_overflow_glyphs(&list),alloc::vec![expected as u16],"only logical end marker survives insufficient pair width");
        }
        for (forced,expected) in [("Hi\nHi","Hi Hi"),("Hi\r\nHi","Hi Hi"),("Hi\x0cHi","Hi Hi"),("Hi\u{85}Hi","Hi Hi"),("Hi\u{2028}\u{2029}Hi","Hi Hi"),("안녕\n안녕","안녕 안녕")] {
            assert_eq!(Layout::overflow_marker_text(forced),expected);
        }
        assert!(matches!(Layout::overflow_marker_text("plain  spaces\tremain"),Cow::Borrowed(_)));
        let document=make("'Hi\\a \\2028 \\2029 Hi'",content,42,"");let (list,_)=render(&document,&[]);
        assert_eq!(visible_overflow_glyphs(&list),ids("ABHi Hi"),"forced breaks collapse independently of block white-space");
    }

    #[test]
    fn specification_text_overflow_custom_marker_bidi_isolation_and_font_baseline() {
        #[derive(Default)]
        struct BidiText { inner:RecordingText, calls:core::cell::RefCell<Vec<(String,bool)>> }
        impl TextShaper for BidiText {
            fn shape(&self,text:&str,size:f32)->Result<ShapedRun,()>{self.inner.shape(text,size)}
            fn shape_resolved(&self,text:&str,size:f32,rtl:bool,font:&crate::paint::FontSpec)->Result<ShapedRun,()>{
                self.calls.borrow_mut().push((String::from(text),rtl));self.inner.shape_resolved(text,size,rtl,font)
            }
            fn ascent(&self,size:f32)->f32{self.inner.ascent(size)}
            fn line_height(&self,size:f32)->f32{self.inner.line_height(size)}
        }
        let document=crate::html::parse("<!doctype html><style>body{margin:0}#target{font:10px/16px monospace;width:60px;white-space:nowrap;overflow:hidden;text-overflow:'xאב12'}#target::first-line{color:red;font-size:20px}</style><div id=target>ABCDEFGHIJKLMNOPQRSTUVWXYZ</div>",128).unwrap();
        let shaper=BidiText::default();let list=display_list(&document,200,200,&shaper).unwrap();
        let calls=shaper.calls.borrow();
        assert!(calls.iter().any(|(text,rtl)|text=="אב"&&*rtl));
        assert!(calls.iter().any(|(text,rtl)|text=="12"&&!*rtl),"numeric visual item keeps its resolved LTR direction inside the isolated marker");
        let item=|id:u16|list.0.iter().find_map(|command|match command{
            Command::GlyphRun{origin_x,baseline_y,size,color,glyphs} if color.a!=0 && glyphs.first().is_some_and(|glyph|glyph.id==id)=>Some((*origin_x,*baseline_y,*size,*color)),_=>None,
        });
        let latin=item(u16::from(b'x')).expect("marker Latin item");
        let digits=item(u16::from(b'1')).expect("marker numeric item");
        let hebrew=item('א' as u16).expect("marker RTL item");
        assert!(latin.0<digits.0&&digits.0<hebrew.0,"marker bidi is resolved in visual order without joining surrounding content");
        assert_eq!(latin.1,digits.1);assert_eq!(digits.1,hebrew.1);
        assert_eq!((latin.2,latin.3),(10.0,Rgba{r:0,g:0,b:0,a:255}),"marker uses block font/color, not first-line styling");
        let target=crate::selector::query_selector(&document,document.root(),"#target").unwrap().unwrap();
        let original=document.first_child(target).unwrap().unwrap();
        assert!(matches!(document.kind(original),Ok(NodeKind::Text(value)) if value=="ABCDEFGHIJKLMNOPQRSTUVWXYZ"));
    }

    #[derive(Default)]
    struct RecordingText(core::cell::RefCell<Vec<String>>);

    #[test]
    fn specification_fieldset_dynamic_multicol_positioned_content_and_owner_removal() {
        let mut document=crate::html::parse("<!doctype html><style>.c2{transform:rotate3d(0,1,0,45deg);column-width:100px}.c19{overflow:auto;padding-left:65536px;column-count:3}q{position:absolute;column-width:1px}body{column-count:3}</style><body></body>",128).unwrap();
        let html=crate::selector::query_selector(&document,document.root(),"html").unwrap().unwrap();
        let body=crate::selector::query_selector(&document,document.root(),"body").unwrap().unwrap();
        let second=document.create(NodeKind::Element{name:crate::Name::from("body"),namespace:Namespace::Html,attributes:Vec::new()}).unwrap();
        document.append(html,second).unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let text=RecordingText::default();
        let check=|session:&mut crate::session::RenderSession,phase:&str| {
            let retained=session.display_list(800,600,&text).unwrap_or_else(|error|panic!("{phase}: retained {error:?}")).clone();
            let fresh=display_list(session.document(),800,600,&text).unwrap_or_else(|error|panic!("{phase}: fresh {error:?}"));
            assert_eq!(retained,fresh,"{phase}: retained ownership/scopes match fresh formatting");
            assert_eq!(retained,session.display_list(800,600,&text).unwrap().clone(),"{phase}: steady replay");
        };
        check(&mut session,"second body inserted");
        let fragment=crate::html::parse_fragment_in(session.document_mut(),body,"<fieldset class=c2><q>q</q></fieldset>").unwrap();
        session.document_mut().append(body,fragment).unwrap();
        let fieldset=crate::selector::query_selector(session.document(),session.document().root(),"fieldset").unwrap().unwrap();
        let quote=crate::selector::query_selector(session.document(),fieldset,"q").unwrap().unwrap();
        check(&mut session,"transformed multicol containing fieldset");
        let root=session.document().root();
        session.set_scroll_offset(root,28.0,71.0).unwrap();
        session.display_list(800,600,&text).expect("actual scroll mutation");
        session.set_scroll_offset(root,0.0,0.0).unwrap();
        session.document_mut().set_attribute(fieldset,"class","c19").unwrap();
        check(&mut session,"overflow multicol anonymous content with large padding");
        session.document_mut().remove(body).unwrap();
        check(&mut session,"original body and positioned content removed");
        assert!(session.client_rects(fieldset).is_empty());
        assert!(session.client_rects(quote).is_empty());
        assert!(!session.client_rects(second).is_empty(),"remaining real body continues formatting");
    }

    #[test]
    fn specification_fieldset_legend_reserves_border_space_and_transfers_padding() {
        let document=crate::html::parse("<!doctype html><style>body{margin:0}fieldset{margin:0;width:100px;height:40px;padding:4px;border:2px solid red;min-inline-size:0}legend{width:30px;height:20px;padding:0;margin:0}div{width:10px;height:10px}</style><fieldset id=f><legend id=l></legend><div id=c></div></fieldset>",96).unwrap();
        let node=|selector|crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
        let (fieldset,legend,child)=(node("#f"),node("#l"),node("#c"));
        let mut session=crate::session::RenderSession::new(document);
        let text=RecordingText::default();
        let list=session.display_list(200,200,&text).unwrap().clone();
        assert_eq!(session.client_rects(fieldset),[Rect{x:0.0,y:0.0,width:112.0,height:52.0}]);
        assert_eq!(session.client_rects(legend),[Rect{x:6.0,y:0.0,width:30.0,height:20.0}]);
        assert_eq!(session.client_rects(child),[Rect{x:6.0,y:24.0,width:10.0,height:10.0}]);
        assert!(list.0.iter().any(|command|matches!(command,Command::PushClip(rect) | Command::PushBoxClip(rect) if rect.x==36.0 && rect.y==9.0)),"real border cutout keeps the region after the static legend");
        assert_eq!(list,session.display_list(200,200,&text).unwrap().clone(),"retained fieldset replay preserves exact clips and geometry");
        session.document_mut().set_attribute(legend,"style","display:none").unwrap();
        let changed=session.display_list(200,200,&text).unwrap().clone();
        assert_eq!(session.client_rects(child)[0].y,6.0,"removing the first rendered legend restores ordinary border allocation");
        assert_eq!(changed,display_list(session.document(),200,200,&text).unwrap());
    }

    #[test]
    fn specification_fieldset_legend_logical_axes_and_border_centering() {
        for (writing,legend_rect,child_rect) in [
            ("vertical-rl",Rect{x:32.0,y:6.0,width:20.0,height:30.0},Rect{x:18.0,y:6.0,width:10.0,height:10.0}),
            ("vertical-lr",Rect{x:0.0,y:6.0,width:20.0,height:30.0},Rect{x:24.0,y:6.0,width:10.0,height:10.0}),
        ] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}fieldset{{writing-mode:{writing};margin:0;width:40px;height:100px;padding:4px;border:2px solid red;min-inline-size:0}}legend{{width:20px;height:30px;padding:0;margin:0}}div{{width:10px;height:10px}}</style><fieldset id=f><legend id=l></legend><div id=c></div></fieldset>"),96).unwrap();
            let node=|selector|crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
            let (fieldset,legend,child)=(node("#f"),node("#l"),node("#c"));
            let mut session=crate::session::RenderSession::new(document);
            let list=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
            assert_eq!((session.client_rects(fieldset)[0].width,session.client_rects(fieldset)[0].height),(52.0,112.0),"{writing}");
            assert_eq!(session.client_rects(legend),[legend_rect],"{writing}");
            assert_eq!(session.client_rects(child),[child_rect],"{writing}");
            assert_eq!(list,display_list(session.document(),200,200,&RecordingText::default()).unwrap());
        }
        for (top,bottom,expected) in [(50,50,0.0),(25,25,25.0),(10,40,25.0),(40,10,25.0)] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}fieldset{{margin:0;padding:0;border:0;border-top:100px solid red;min-inline-size:0}}legend{{width:20px;height:0;padding:0;border-top:{top}px solid black;border-bottom:{bottom}px solid black}}</style><fieldset><legend id=l></legend></fieldset>"),96).unwrap();
            let legend=crate::selector::query_selector(&document,document.root(),"#l").unwrap().unwrap();
            let mut session=crate::session::RenderSession::new(document);
            session.display_list(200,200,&RecordingText::default()).unwrap();
            assert_eq!(session.client_rects(legend)[0].y,expected,"actual legend border box is centered, not its content box");
        }
    }

    #[test]
    fn specification_fieldset_anonymous_content_preserves_flex_grid_intrinsics_and_float_isolation() {
        for display in ["flex","grid"] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}fieldset{{display:{display};width:100px;margin:0;padding:0;border:2px solid;min-inline-size:0;gap:3px;grid-template-columns:20px 20px}}legend{{width:30px;height:20px;padding:0;margin:0}}div{{width:20px;height:10px}}</style><fieldset id=f><legend id=l></legend><div id=a></div><div id=b></div></fieldset>"),96).unwrap();
            let node=|selector|crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
            let (fieldset,legend,a,b)=(node("#f"),node("#l"),node("#a"),node("#b"));
            let mut session=crate::session::RenderSession::new(document);
            session.display_list(200,200,&RecordingText::default()).unwrap();
            assert_eq!(session.client_rects(legend)[0],Rect{x:2.0,y:0.0,width:30.0,height:20.0});
            assert_eq!(session.client_rects(a)[0],Rect{x:2.0,y:20.0,width:20.0,height:10.0});
            assert_eq!(session.client_rects(b)[0],Rect{x:25.0,y:20.0,width:20.0,height:10.0});
            assert_eq!(session.client_rects(fieldset)[0].height,32.0,"{display}");
        }
        let document=crate::html::parse("<!doctype html><style>body{margin:0}aside{float:left;width:40px;height:80px}fieldset{margin:0;padding:0;border:2px solid;width:80px;min-inline-size:0}legend{width:30px;height:20px;padding:0;margin:0}div{float:left;width:10px;height:30px}</style><aside></aside><fieldset id=f><legend></legend><div></div></fieldset>",96).unwrap();
        let fieldset=crate::selector::query_selector(&document,document.root(),"#f").unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        session.display_list(200,200,&RecordingText::default()).unwrap();
        assert_eq!(session.client_rects(fieldset)[0],Rect{x:40.0,y:0.0,width:84.0,height:52.0},"both fieldset and anonymous flow box use real BFC float admission/containment");
    }

    #[test]
    fn specification_fieldset_formatting_children_own_floats_but_preserve_positioned_escapes() {
        // fieldset-painting-order.html: a legend float must finish before the
        // following anonymous formatting child's overlapping block surface.
        for display in ["block", "flex", "grid"] {
            for z in [None, Some(-1), Some(0), Some(1)] {
                let escape = z.map_or(String::new(), |z| alloc::format!(
                    "<i id=escape style='position:absolute;left:50px;top:50px;width:50px;height:50px;background:blue;z-index:{z}'></i>"));
                let document = crate::html::parse(&alloc::format!(
                    "<!doctype html><style>body{{margin:0;position:relative}}fieldset{{display:{display};margin:0;padding:0;border:0;width:100px;height:0;min-inline-size:0}}legend{{width:100px;height:100px;margin:0;padding:0;background:green}}legend span{{float:right;margin-top:50px;width:50px;height:50px;background:red}}fieldset>div{{margin-top:-50px;width:100px;height:100px;background:lime}}</style><fieldset><legend><span id=float></span>{escape}</legend><div id=content></div></fieldset>"), 128).unwrap();
                let content = crate::selector::query_selector(&document, document.root(), "#content").unwrap().unwrap();
                let escaped = crate::selector::query_selector(&document, document.root(), "#escape").unwrap();
                let mut session = crate::session::RenderSession::new(document);
                let text = RecordingText::default();
                let check = |session: &mut crate::session::RenderSession, expected: Option<NodeId>| {
                    let retained = session.display_list(300, 300, &text).unwrap().clone();
                    let fresh = display_list(session.document(), 300, 300, &text).unwrap();
                    assert_eq!(retained, fresh, "{display} z={z:?}: phase replay");
                    let color = retained.0.iter().filter_map(|command| match command {
                        Command::FillRect {rect,color} if rect.x <= 75.0 && 75.0 < rect.x + rect.width
                            && rect.y <= 75.0 && 75.0 < rect.y + rect.height => Some(*color),
                        _ => None,
                    }).last().unwrap();
                    let blue = Rgba {r:0,g:0,b:255,a:255};
                    let lime = Rgba {r:0,g:255,b:0,a:255};
                    assert_eq!(color, if expected == Some(content) { lime } else { blue },
                        "{display} z={z:?}: ordinary legend float is covered; positioned phases escape");
                    assert_eq!(session.hit_test(75.0, 75.0), expected, "paint and hit ownership agree");
                    assert_eq!(retained, session.display_list(300, 300, &text).unwrap().clone());
                };
                check(&mut session, if z.is_some_and(|z| z >= 0) {escaped} else {Some(content)});
                if let Some(escape) = escaped {
                    session.document_mut().set_attribute(escape, "style",
                        "position:absolute;left:50px;top:50px;width:50px;height:50px;background:blue;z-index:2").unwrap();
                    check(&mut session, Some(escape));
                }
            }
        }
    }

    #[test]
    fn specification_fieldset_border_gap_covers_full_logical_band_at_static_legend_position() {
        // /html/rendering/non-replaced-elements/the-fieldset-and-legend-elements/fieldset-border-gap-position-relative.html
        fn red_area(list: &DisplayList) -> f32 {
            let mut clips: Vec<Option<Rect>> = Vec::new();
            let mut area = 0.0;
            for command in &list.0 {
                match command {
                    Command::PushClip(rect) | Command::PushBoxClip(rect) => {
                        let clipped = if let Some(parent) = clips.last() {
                            parent.and_then(|parent| parent.intersection(*rect))
                        } else { Some(*rect) };
                        clips.push(clipped);
                    }
                    Command::PopClip => { clips.pop().expect("balanced real border clip"); }
                    Command::FillRect { rect, color } if *color == Rgba { r: 255, g: 0, b: 0, a: 255 } => {
                        let clipped = clips.last().map_or(Some(*rect), |clip| clip.and_then(|clip| clip.intersection(*rect)));
                        area += clipped.map_or(0.0, |rect| rect.width * rect.height);
                    }
                    _ => {}
                }
            }
            assert!(clips.is_empty());
            area
        }
        for writing in ["horizontal-tb", "vertical-rl", "vertical-lr"] {
            for (inline, expected) in [(100, 0.0), (60, 4000.0)] {
                for relative in ["", "position:relative;left:9px;top:13px;transform:translate(7px,11px)"] {
                    let document = crate::html::parse(&alloc::format!(
                        "<!doctype html><style>body{{margin:0}}fieldset{{writing-mode:{writing};margin:0;padding:0;border:0;border-block-start:100px solid red;inline-size:100px;block-size:100px;min-inline-size:0}}legend{{margin:0;padding:0;inline-size:{inline}px;block-size:50px;background:lime;{relative}}}</style><fieldset><legend id=l></legend></fieldset>"), 96).unwrap();
                    let legend = crate::selector::query_selector(&document, document.root(), "#l").unwrap().unwrap();
                    let mut session = crate::session::RenderSession::new(document);
                    let text = RecordingText::default();
                    let first = session.display_list(300,300,&text).unwrap().clone();
                    assert_eq!(red_area(&first), expected, "{writing}/{inline}/{relative}: complete border band uses the legend's static inline footprint");
                    assert!(!session.client_rects(legend).is_empty(), "actual legend ownership and geometry remain");
                    assert_eq!(first, session.display_list(300,300,&text).unwrap().clone(), "retained clipping replay");
                    assert_eq!(first, display_list(session.document(),300,300,&text).unwrap(), "fresh clipping matches retained geometry");
                }
            }
        }
    }

    // /html/rendering/non-replaced-elements/the-fieldset-and-legend-elements/fieldset-overflow-cssomview.html
    #[test]
    fn specification_fieldset_anonymous_scrollport_owns_overflow_without_scrolling_legend() {
        let document = crate::html::parse("<!doctype html><style>body{margin:0}fieldset{margin:0;width:100px;height:200px;border:2px solid;padding:0;overflow:scroll;min-inline-size:0}legend{width:30px;height:20px;margin:0;padding:0}div{height:400px}</style><fieldset id=f><legend id=l></legend><div id=c></div></fieldset>", 96).unwrap();
        let lookup = |selector| crate::selector::query_selector(&document, document.root(), selector).unwrap().unwrap();
        let (fieldset, legend, child) = (lookup("#f"), lookup("#l"), lookup("#c"));
        let text = RecordingText::default();
        let mut session = crate::session::RenderSession::new(document);
        let list = session.display_list(300, 600, &text).unwrap().clone();
        let legend_rect = session.client_rects(legend)[0];
        let child_rect = session.client_rects(child)[0];
        assert_eq!(session.scrollport(fieldset), Some(Rect { x: 2.0, y: 20.0, width: 100.0, height: 182.0 }));
        assert_eq!(session.scroll_extent(fieldset), Some((0.0, 218.0)), "principal fieldset finalization cannot replace the anonymous content's actual extent");
        let port = session.scrollport_size(fieldset).unwrap();
        assert_eq!(port.1 + session.scroll_extent(fieldset).unwrap().1, 400.0, "CSSOM scrollHeight uses the anonymous box");
        assert_eq!(list, session.display_list(300,600,&text).unwrap().clone(), "retained fieldset overflow frame keeps the scrolling box");
        assert!(session.set_scroll_offset(fieldset, 0.0, 500.0).unwrap());
        session.display_list(300,600,&text).unwrap();
        assert_eq!(session.client_rects(legend)[0], legend_rect, "legend is outside the scrolling content");
        assert_eq!(session.client_rects(child)[0].y, child_rect.y - 218.0, "content scrolls by the anonymous box's clamped range");
        session.set_scroll_offset(fieldset,0.0,0.0).unwrap();
        session.document_mut().set_attribute(legend,"style","display:none").unwrap();
        let changed = session.display_list(300,600,&text).unwrap().clone();
        assert_eq!(session.scrollport_size(fieldset), Some((100.0, 200.0)));
        assert_eq!(session.scroll_extent(fieldset), Some((0.0, 200.0)), "legend removal invalidates the port and its overflow together");
        assert_eq!(changed, display_list(session.document(),300,600,&text).unwrap(), "fresh fieldset overflow matches retained mutation");
    }

    // /html/rendering/non-replaced-elements/the-fieldset-and-legend-elements/fieldset-max-block-size.html
    // /html/rendering/non-replaced-elements/the-fieldset-and-legend-elements/fieldset-overflow.html
    #[test]
    fn specification_fieldset_auto_block_size_constrains_anonymous_scrollport() {
        for (constraint, natural, legend_size, port_height, fieldset_height) in [
            ("max-height:50px", 400, 0, 50.0, 54.0),
            ("max-height:50px", 10, 0, 10.0, 14.0),
            ("max-height:0", 400, 0, 0.0, 4.0),
            ("max-height:50px", 400, 20, 32.0, 54.0),
            ("min-height:50px", 10, 0, 50.0, 54.0),
        ] {
            let legend = if legend_size == 0 { alloc::string::String::new() }
                else { alloc::format!("<legend style='width:30px;height:{legend_size}px;margin:0;padding:0'></legend>") };
            let document = crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}fieldset{{margin:0;padding:0;width:100px;border:2px solid;overflow:auto;min-inline-size:0;{constraint}}}div{{height:{natural}px}}</style><fieldset id=f>{legend}<div></div></fieldset>"),96).unwrap();
            let fieldset = crate::selector::query_selector(&document,document.root(),"#f").unwrap().unwrap();
            let text = RecordingText::default();
            let mut session = crate::session::RenderSession::new(document);
            let list = session.display_list(300,600,&text).unwrap().clone();
            assert_eq!(session.scrollport_size(fieldset),Some((100.0,port_height)),"{constraint}/{natural}/{legend_size}: actual scrolling box follows used block-size");
            assert_eq!(session.client_rects(fieldset)[0].height,fieldset_height);
            assert_eq!(session.scroll_extent(fieldset).unwrap().1,(natural as f32-port_height).max(0.0));
            assert_eq!(list,session.display_list(300,600,&text).unwrap().clone());
            assert_eq!(list,display_list(session.document(),300,600,&text).unwrap());
        }
    }

    // /html/rendering/non-replaced-elements/the-fieldset-and-legend-elements/fieldset-baseline.html
    // /html/rendering/non-replaced-elements/the-fieldset-and-legend-elements/fieldset-dynamic-baseline.html
    #[test]
    fn specification_fieldset_baseline_matches_ordinary_atom_and_ignores_positioned_mutation() {
        fn glyph_positions(list: &DisplayList) -> Vec<(f32,f32)> {
            list.0.iter().filter_map(|command| match command {
                Command::GlyphRun { origin_x, baseline_y, .. } => Some((*origin_x,*baseline_y)),
                _ => None,
            }).collect()
        }
        let text = SizedText;
        for display in ["inline-block", "inline-flex"] {
            let markup = |tag, child| alloc::format!("<!doctype html><style>body{{margin:0;font-size:10px;line-height:10px}}{tag}{{display:{display};border:2px solid;padding:10px;margin:5px;min-inline-size:0}}</style><main>Z<{tag}><div style='position:relative'>A<br>B{child}</div></{tag}></main>");
            let reference = crate::html::parse(&markup("span", ""),96).unwrap();
            let reference_node=crate::selector::query_selector(&reference,reference.root(),"span").unwrap().unwrap();
            let mut reference_session=crate::session::RenderSession::new(reference);
            let expected=glyph_positions(reference_session.display_list(300,300,&text).unwrap());
            let expected_box=reference_session.client_rects(reference_node)[0];
            let direct=|tag|alloc::format!("<!doctype html><style>body{{margin:0;font-size:10px;line-height:10px}}{tag}{{display:{display};border:2px solid;padding:10px;margin:5px;min-inline-size:0}}</style><main>Z<{tag}>A<br>B</{tag}></main>");
            let mut boxes=Vec::new();
            for tag in ["span","fieldset"] {
                let document=crate::html::parse(&direct(tag),96).unwrap();
                let node=crate::selector::query_selector(&document,document.root(),tag).unwrap().unwrap();
                let mut direct_session=crate::session::RenderSession::new(document);
                direct_session.display_list(300,300,&text).unwrap();
                boxes.push(direct_session.client_rects(node)[0]);
            }
            assert_eq!(boxes[1],boxes[0],"{display}: direct text/BR intrinsic border dimensions include both transferred padding sides");
            let document = crate::html::parse(&markup("fieldset", "<div id=oof style='position:absolute'></div>"),96).unwrap();
            let positioned = crate::selector::query_selector(&document,document.root(),"#oof").unwrap().unwrap();
            let fieldset_node=crate::selector::query_selector(&document,document.root(),"fieldset").unwrap().unwrap();
            let mut session = crate::session::RenderSession::new(document);
            let first = session.display_list(300,300,&text).unwrap().clone();
            assert_eq!(glyph_positions(&first),expected,"{display}: anonymous formatting exports the same real line baselines as the ordinary reference");
            assert_eq!(session.client_rects(fieldset_node)[0],expected_box,"{display}: empty positioned descendant cannot donate a line-height to principal geometry");
            assert_eq!(first,session.display_list(300,300,&text).unwrap().clone());
            session.document_mut().set_attribute(positioned,"style","position:absolute;top:10px").unwrap();
            let changed = session.display_list(300,300,&text).unwrap().clone();
            assert_eq!(glyph_positions(&changed),expected,"{display}: positioned descendants do not donate flow baselines");
            assert_eq!(session.client_rects(fieldset_node)[0],expected_box,"{display}: positioned inset mutation leaves principal border geometry intact");
            assert_eq!(changed,display_list(session.document(),300,300,&text).unwrap());
        }
    }

    // /css/css-contain/contain-size-fieldset-001.html through -004.html
    // /css/css-contain/contain-inline-size-fieldset.html
    #[test]
    fn specification_containment_fieldset_principal_empty_size_keeps_actual_contents() {
        let text = SizedText;
        for mode in ["horizontal-tb", "vertical-rl", "vertical-lr", "sideways-rl", "sideways-lr"] {
            for sizing in ["content-box", "border-box"] {
                for constraint in ["", "min-inline-size:30px;min-block-size:35px", "inline-size:40px;block-size:45px", "max-inline-size:25px;max-block-size:30px"] {
                    for containment in ["size", "inline-size"] {
                        let children = "<legend id=l style='inline-size:200px;block-size:50px;padding:0;margin:0;background:blue'></legend><div id=c style='inline-size:100px;block-size:80px;background:lime'></div>";
                        let markup = |reference: bool| {
                            let (contain, inline, contents) = if !reference { (containment, "", children) }
                                else if containment == "size" { ("none", "", "") }
                                else { ("none", "inline-size:0;", children) };
                            alloc::format!("<!doctype html><style>body{{margin:0}}fieldset{{display:inline-block;writing-mode:{mode};box-sizing:{sizing};border:2px solid;padding:3px;margin:5px;min-inline-size:0;contain:{contain};{inline}{constraint}}}</style><fieldset id=f>{contents}</fieldset>")
                        };
                        let mut dimensions = Vec::new();
                        for reference in [true, false] {
                            let document = crate::html::parse(&markup(reference),128).unwrap();
                            let fieldset = crate::selector::query_selector(&document,document.root(),"#f").unwrap().unwrap();
                            let content = crate::selector::query_selector(&document,document.root(),"#c").unwrap();
                            let mut session = crate::session::RenderSession::new(document);
                            let first = session.display_list(500,500,&text).unwrap().clone();
                            let rect = session.client_rects(fieldset)[0];
                            dimensions.push((rect.width,rect.height));
                            if let Some(content) = content {
                                let rect = session.client_rects(content)[0];
                                let expected = if mode == "horizontal-tb" { (100.0,80.0) } else { (80.0,100.0) };
                                assert_eq!((rect.width,rect.height),expected,"{containment}/{mode}/{sizing}/{constraint}: containment preserves actual overflowing contents");
                                session.document_mut().set_attribute(content,"style","inline-size:160px;block-size:120px;background:lime").unwrap();
                                let changed = session.display_list(500,500,&text).unwrap().clone();
                                if containment == "size" {
                                    let rect = session.client_rects(fieldset)[0];
                                    assert_eq!((rect.width,rect.height),*dimensions.last().unwrap(),"{mode}/{sizing}/{constraint}: content mutation cannot change either contained principal axis");
                                }
                                assert_eq!(changed,display_list(session.document(),500,500,&text).unwrap());
                            } else {
                                assert_eq!(first,session.display_list(500,500,&text).unwrap().clone());
                                assert_eq!(first,display_list(session.document(),500,500,&text).unwrap());
                            }
                        }
                        assert_eq!(dimensions[1],dimensions[0],"{containment}/{mode}/{sizing}/{constraint}: principal geometry follows empty sizing only on contained axes");
                    }
                }
            }
        }
    }

    #[test]
    fn specification_select_contained_none_preserves_empty_widget_sizing() {
        for mode in ["horizontal-tb","vertical-rl"] {
            for (attributes,empty) in [("",(10.0,10.0)),("multiple size=2",(0.0,20.0)),("multiple size=10",(0.0,100.0))] {
                for (fallback,expected) in [("none none",empty),("55px none",(55.0,empty.1)),("none 66px",(empty.0,66.0)),("0px 0px",(0.0,0.0))] {
                    let vertical=mode!="horizontal-tb";
                    let (fallback,expected)=if vertical {
                        let (width,height)=fallback.split_once(' ').unwrap();
                        (alloc::format!("{height} {width}"),(expected.1,expected.0))
                    }else{(String::from(fallback),expected)};
                    let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}select{{display:inline-block;appearance:auto;writing-mode:{mode};font:10px/10px monospace;padding:0;border:2px solid;margin:0}}#contained{{contain:size;contain-intrinsic-size:{fallback}}}</style><select id=contained {attributes}><option>A LONG LABEL</option></select>"),96).unwrap();
                    let node=crate::selector::get_element_by_id(&document,document.root(),"contained").unwrap().unwrap();
                    let mut session=crate::session::RenderSession::new(document);
                    let first=session.display_list(500,500,&SizedText).unwrap().clone();
                    let rect=session.layout_rect(node).unwrap();
                    assert_eq!((rect.width,rect.height),(expected.0+4.0,expected.1+4.0),"{mode}/{attributes}/{fallback}: option labels are suppressed, widget rows remain, explicit zero differs from none");
                    assert_eq!(first,session.display_list(500,500,&SizedText).unwrap().clone());
                    assert_eq!(first,display_list(session.document(),500,500,&SizedText).unwrap());
                }
            }
        }
    }

    #[test]
    fn specification_vertical_generated_blocks_share_ordinary_axis_progression() {
        for mode in ["vertical-lr","vertical-rl","sideways-lr","sideways-rl"] {
            let base=alloc::format!("<style>body{{margin:0}}main{{writing-mode:{mode};width:100px;height:100px}}b,main::before,main::after{{display:block;margin:0;padding:0;border:0;background:red}}b:first-child,main::before{{width:40px;height:20px}}b:last-child,main::after{{width:20px;height:10px}}");
            let ordinary=alloc::format!("{base}</style><main><b></b><b></b></main>");
            let generated=alloc::format!("{base}main::before,main::after{{content:''}}</style><main></main>");
            assert_eq!(grid_boxes(&generated),grid_boxes(&ordinary),"{mode}: generated and ordinary block boxes use the same physical block progression");
            let document=crate::html::parse(&alloc::format!("{base}main::before{{content:''}}main{{display:inline-block;width:auto;height:auto;contain:size;contain-intrinsic-size:40px 30px;border:5px solid}}</style><main id=r></main>"),96).unwrap();
            let node=crate::selector::get_element_by_id(&document,document.root(),"r").unwrap().unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let first=session.display_list(500,500,&SizedText).unwrap().clone();
            assert_eq!((session.layout_rect(node).unwrap().width,session.layout_rect(node).unwrap().height),(50.0,40.0),"contained principal size preserves its physical overrides while generated vertical contents use ordinary paint");
            assert_eq!(first,session.display_list(500,500,&SizedText).unwrap().clone());
        }
    }

