    impl TextShaper for RecordingText {
        fn primary_character_widths_styled(&self, size: f32, _: &FontSpec) -> Option<crate::paint::PrimaryCharacterWidths> {
            let _ = size;
            Some(crate::paint::PrimaryCharacterWidths { average: 6.0, maximum: 6.0 })
        }
        fn shape(&self, text: &str, _: f32) -> Result<ShapedRun, ()> {
            self.0.borrow_mut().push(String::from(text));
            Ok(ShapedRun {
                glyphs: text
                    .char_indices()
                    .enumerate()
                    .map(|(index, (cluster, character))| crate::paint::Glyph {
                        id: u16::try_from(character as u32).unwrap_or(0xfffd),
                        face: 0,
                        cluster: cluster as u32,
                        caps_expansion: 0,
                        x: index as f32 * 6.0,
                        y: 0.0,
                        size_scale: 1.0,
                    })
                    .collect::<Vec<_>>()
                    .into(),
                width: text.chars().count() as f32 * 6.0,
            })
        }

        fn ascent(&self, _: f32) -> f32 {
            10.0
        }

        fn line_height(&self, _: f32) -> f32 {
            16.0
        }
    }

    #[test]
    fn specification_principal_box_inheritance_retains_contents_origins_for_real_descendants() {
        let markup="<!doctype html><style>html,body{margin:0;color:red;font:16px/16px monospace}.contents{display:contents}.pink{color:pink}.lime{color:lime}.b{background:inherit}</style><main style='display:flex;color:lime'><div class='contents pink'><div>A<span class=b>B</span></div></div><div class='contents pink'><div style='display:inline'>C<div>D</div></div></div></main><main style='display:flex'><div class='contents lime'><div class='contents pink'><div>E<span class=b>F</span></div></div></div></main><section style='columns:2;height:64px'><div id=origin class='contents pink'><div>G<span class=b>H</span></div></div><div class='contents pink'><div>I</div></div></section>";
        let document=crate::html::parse(markup,192).unwrap();
        let origin=crate::selector::query_selector(&document,document.root(),"#origin").unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let text=RecordingText::default();
        let first=session.display_list(200,200,&text).unwrap().clone();
        let painted=|list:&DisplayList|list.0.iter().filter_map(|command|match command {
            Command::GlyphRun{glyphs,color,..}=>Some(glyphs.iter().filter_map(|glyph|
                ((b'A' as u16..=b'I' as u16).contains(&glyph.id)).then_some((glyph.id,(color.r,color.g,color.b))))),
            _=>None,
        }).flatten().collect::<Vec<_>>();
        let actual=painted(&first);
        for character in b'A'..=b'I' {
            assert_eq!(actual.iter().find(|(id,_)|*id==character as u16).map(|(_,color)|*color),Some((255,192,203)),
                "the real descendant keeps its DOM inheritance through contents: {}",char::from(character));
        }
        assert_eq!(first,session.display_list(200,200,&text).unwrap().clone(),"retained principal origin matches first paint");
        session.invalidate_image_resources();
        assert_eq!(first,session.display_list(200,200,&text).unwrap().clone(),"fresh paint uses the same inherited origin");
        session.document_mut().set_attribute(origin,"style","color:teal").unwrap();
        let changed=session.display_list(200,200,&text).unwrap().clone();
        let actual=painted(&changed);
        for character in [b'G',b'H'] {
            assert_eq!(actual.iter().find(|(id,_)|*id==character as u16).map(|(_,color)|*color),Some((0,128,128)),"real descendant inheritance is recascaded after origin mutation");
        }
        session.invalidate_image_resources();assert_eq!(changed,session.display_list(200,200,&text).unwrap().clone(),"mutated origin retained replay remains exact");
    }

    #[test]
    fn empty_decorated_inline_advance_matches_word_spacing_reference() {
        let markup = "<style>body{margin:0}p{margin:0;font:10px/10px monospace}.control span{background:blue;color:blue}.spacer{padding-left:40px}.test span{background:orange;color:orange;word-spacing:40px}</style><p class=control><span>A <span class=spacer></span>B</span></p><p class=test><span>A B</span></p>";
        let document = crate::html::parse(markup, 128).unwrap();
        let list = display_list(&document, 160, 80, &RecordingText::default()).unwrap();
        let mut blue_width = 0.0f32;
        let mut orange_width = 0.0f32;
        for command in &list.0 {
            let Command::FillRect { rect, color } = command else {
                continue;
            };
            if (color.r, color.g, color.b) == (0, 0, 255) {
                blue_width = blue_width.max(rect.width);
            } else if (color.r, color.g, color.b) == (255, 165, 0) {
                orange_width = orange_width.max(rect.width);
            }
        }
        assert!(
            blue_width >= 40.0,
            "empty padded inline lost its box advance: {blue_width}"
        );
        assert!(
            (blue_width - orange_width).abs() < 0.01,
            "empty inline padding should match the equivalent word spacing: {blue_width} vs {orange_width}"
        );
    }

    #[test]
    fn specification_table_anonymous_inline_atoms_preserve_cells_context_and_first_row_baseline() {
        let render=|display:&str,contents:bool,split:bool,rows:bool| {
            let cells=if rows {"<em style='display:table-row'><b id=first class=cell>ab</b></em><em style='display:table-row'><b id=second class=cell>cd</b></em>"}else{"<b id=first class=cell>ab</b><b id=second class=cell>cd</b>"};
            let children=if contents {alloc::format!("<i style='display:contents'>{cells}</i>")}else{String::from(cells)};
            let interruption=if split {"<div style='height:5px'></div>"}else{""};
            let markup=alloc::format!("<style>body,p{{margin:0}}p{{text-transform:uppercase}}.cell{{display:table-cell;padding:0}}#wrapper{{border-spacing:0;{display}}}</style><p>X<span id=wrapper>{children}</span>{interruption}Y</p>");
            let document=crate::html::parse(&markup,128).unwrap();
            let first=crate::selector::query_selector(&document,document.root(),"#first").unwrap().unwrap();
            let source=document.first_child(first).unwrap().unwrap();
            assert!(matches!(document.kind(source).unwrap(),NodeKind::Text(value) if value=="ab"));
            let mut geometry=LayoutGeometry::default();let rules=stylesheets(&document).unwrap();
            let list=display_list_with_styles(&document,100,120,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            assert!(matches!(document.kind(source).unwrap(),NodeKind::Text(value) if value=="ab"),"box fixup and case shaping do not mutate the DOM");
            for selector in ["#first","#second"] {
                let cell=crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
                assert_eq!(geometry.hits.iter().filter(|hit|hit.node==cell&&!hit.virtual_generated).count(),1,"one real hit per source cell");
            }
            let mut ink=Vec::new();
            for command in list.0 {if let Command::GlyphRun{origin_x,baseline_y,glyphs,..}=command {
                ink.extend(glyphs.iter().map(|glyph|(glyph.id,origin_x+glyph.x,baseline_y+glyph.y)));
            }}
            assert!(ink.iter().any(|glyph|glyph.0==u16::from(b'A')),"anonymous cells retain inherited case context");
            if rows&&!split {
                let first=ink.iter().find(|glyph|glyph.0==u16::from(b'A')).unwrap().2;
                let second=ink.iter().find(|glyph|glyph.0==u16::from(b'C')).unwrap().2;
                let tail=ink.iter().find(|glyph|glyph.0==u16::from(b'Y')).unwrap().2;
                assert!((first-tail).abs()<0.001&&second>first,"inline table baseline is its first row, not its last row");
            }
            ink
        };
        for contents in [false,true] {for split in [false,true] {for rows in [false,true] {
            let anonymous=render("",contents,split,rows);let explicit=render("display:inline-table",contents,split,rows);
            assert_eq!(anonymous.len(),explicit.len());
            for (a,b) in anonymous.iter().zip(&explicit){assert_eq!(a.0,b.0);assert!((a.1-b.1).abs()<0.001&&(a.2-b.2).abs()<0.001,"anonymous inline table {a:?} != explicit {b:?}; contents={contents}, split={split}");}
        }}}
    }

    #[test]
    fn intrinsic_paragraphs_preserve_inter_node_spaces_in_boxes_and_anonymous_cells() {
        for display in ["inline-block","table"] {for (sizing,width) in [("max-content",30.0),("min-content",12.0)] {
            let document=crate::html::parse(&alloc::format!("<style>body{{margin:0}}#box{{display:{display};width:{sizing};border-spacing:0}}</style><div id=box><span>aa</span> <span>bb</span></div>"),64).unwrap();
            let box_node=crate::selector::query_selector(&document,document.root(),"#box").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            display_list_with_styles(&document,100,100,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let actual=geometry.hits.iter().find(|hit|hit.node==box_node&&!hit.virtual_generated).unwrap().rect.width;
            assert!((actual-width).abs()<0.001,"{display} {sizing}: source boundaries must retain the one inter-word space; {actual} versus {width}");
        }}
        for whitespace in ["", "\n  "] {
            let document=crate::html::parse(&alloc::format!("<style>body{{margin:0}}</style><div id=box style='float:left;min-width:150px'>{whitespace}<div style='float:right;width:100px;height:200px'></div>{whitespace}<div style='display:inline-block;vertical-align:top;width:100px;height:200px'></div>{whitespace}</div>"),64).unwrap();
            let box_node=crate::selector::query_selector(&document,document.root(),"#box").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            display_list_with_styles(&document,400,300,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let actual=geometry.hits.iter().find(|hit|hit.node==box_node&&!hit.virtual_generated).unwrap().rect;
            assert_eq!((actual.width,actual.height),(200.0,200.0),"collapsing trailing whitespace cannot widen the max-content line beside a float");
        }
    }

    #[test]
    fn text_indent_applies_to_first_line_only_with_signed_and_percentage_values() {
        let markup = "<style>body{margin:0}p{margin:0;width:100px;font:10px/10px monospace}#positive{text-indent:20px}#negative{text-indent:-10px}#percent{text-indent:10%}</style><p id=positive>a<br>b</p><p id=negative>c</p><p id=percent>d</p>";
        let document = crate::html::parse(markup, 128).unwrap();
        let list = display_list(&document, 160, 100, &RecordingText::default()).unwrap();
        let mut glyphs = Vec::new();
        for command in &list.0 {
            let Command::GlyphRun {
                origin_x,
                baseline_y,
                glyphs: run,
                ..
            } = command
            else {
                continue;
            };
            for glyph in run.iter() {
                if let Some(character) = char::from_u32(u32::from(glyph.id)) {
                    glyphs.push((character, *origin_x + glyph.x, *baseline_y));
                }
            }
        }
        let first = glyphs
            .iter()
            .find(|(character, _, _)| *character == 'a')
            .unwrap();
        let second = glyphs
            .iter()
            .find(|(character, _, _)| *character == 'b')
            .unwrap();
        let negative = glyphs
            .iter()
            .find(|(character, _, _)| *character == 'c')
            .unwrap();
        let percentage = glyphs
            .iter()
            .find(|(character, _, _)| *character == 'd')
            .unwrap();
        assert!(
            (first.1 - 20.0).abs() < 0.01,
            "positive first-line indent: {first:?}"
        );
        assert!(
            (second.1 - 0.0).abs() < 0.01,
            "forced second line must not inherit the indent: {second:?}"
        );
        assert!(
            (negative.1 + 10.0).abs() < 0.01,
            "negative first-line indent: {negative:?}"
        );
        assert!(
            (percentage.1 - 10.0).abs() < 0.01,
            "percentage indent uses containing width: {percentage:?}"
        );
    }

    #[test]
    fn specification_final_line_whitespace_preserves_bidi_edges_and_original_sources() {
        fn sample(direction:&str,align:&str,space:&str,mode:&str,inside:bool)
            ->(Vec<(u16,f32,f32)>,Vec<Rect>,String) {
            let content=if inside {alloc::format!("A<span></span>B{space}</span>")}
                else {alloc::format!("A<span></span>B</span>{space}")};
            let markup=alloc::format!("<style>html,body{{margin:0;padding:0}}#box{{width:80px;direction:{direction};text-align:{align};white-space:{mode}}}#ink{{border-left:2px solid red;border-right:4px solid red}}</style><div id=box><span id=ink>{content}</div>");
            let document=crate::html::parse(&markup,64).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#ink").unwrap().unwrap();
            let box_node=crate::selector::query_selector(&document,document.root(),"#box").unwrap().unwrap();
            let mut original=String::new();document.append_descendant_text(box_node,&mut original).unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let list=session.display_list(100,60,&RecordingText::default()).unwrap().clone();
            let ink=list.0.iter().filter_map(|command|match command {
                Command::GlyphRun{glyphs,origin_x,baseline_y,..}=>Some(glyphs.iter()
                    .map(|glyph|(glyph.id,*origin_x+glyph.x,*baseline_y+glyph.y))),
                _=>None,
            }).flatten().collect();
            (ink,session.client_rects(node),original)
        }
        for direction in ["ltr","rtl"] {for align in ["left","right","start","end","center"] {
            for inside in [false,true] {for mode in ["normal","nowrap","pre-line"] {
                let reference=sample(direction,align,"",mode,inside);
                let trailing=sample(direction,align," ",mode,inside);
                assert_eq!(trailing.0,reference.0,"discarded source cannot inset visual ink: {direction}/{align}/{mode}/{inside}");
                assert_eq!(trailing.1,reference.1,"physical frame edges survive trimming: {direction}/{align}/{mode}/{inside}");
                assert_eq!(trailing.2,"AB ","line trimming cannot rewrite the original Text nodes");
            }}}
        }
        // Pre and break-spaces retain the actual trailing advance. Forced
        // pre-wrap lines count the space when it fits; it is not collapsed.
        for mode in ["pre","pre-wrap","break-spaces"] {
            let reference=sample("ltr","right","",mode,false);
            let preserved=sample("ltr","right"," ",mode,false);
            assert_eq!(preserved.0[0].1,reference.0[0].1-6.0,"preserved fitting separator contributes to alignment: {mode}");
            assert_eq!(preserved.2,"AB ");
            let reference=sample("rtl","left","",mode,false);
            let preserved=sample("rtl","left"," ",mode,false);
            let a=|sample:&(Vec<(u16,f32,f32)>,Vec<Rect>,String)|sample.0.iter().find(|glyph|glyph.0==u16::from(b'A')).unwrap().1;
            assert_eq!(a(&preserved),a(&reference)+6.0,"fitting RTL preserved space stays at the physical leading edge: {mode}");
        }
        for (direction,align) in [("ltr","left"),("rtl","right")] {
            let reference=sample(direction,align,"","pre-wrap",false);
            let hanging=sample(direction,align,"                    ","pre-wrap",false);
            let a=|sample:&(Vec<(u16,f32,f32)>,Vec<Rect>,String)|sample.0.iter().find(|glyph|glyph.0==u16::from(b'A')).unwrap().1;
            assert_eq!(a(&hanging),a(&reference),"overflowing preserved spaces hang on their physical end without displacing ink: {direction}");
            assert_eq!(hanging.0.iter().filter(|glyph|glyph.0==u16::from(b' ')).count(),20,"hanging preserves real source glyph payload");
        }
        let ink=|markup:&str| {
            let document=crate::html::parse(markup,64).unwrap();
            let list=display_list(&document,100,60,&RecordingText::default()).unwrap();
            list.0.iter().filter_map(|command|match command {
                Command::GlyphRun{glyphs,origin_x,baseline_y,..}=>Some(glyphs.iter().map(|glyph|
                    (glyph.id,*origin_x+glyph.x,*baseline_y+glyph.y))),_=>None,
            }).flatten().collect::<Vec<_>>()
        };
        // RecordingText records source characters without backend mirroring.
        // Keep direction identical here; the real FontSet guard compares the
        // mirrored RTL punctuation against its literal LTR visual reference.
        assert_eq!(ink("<style>body{margin:0;direction:rtl;text-align:left}.a:before{content:'('}.a:after{content:')'}.b:after{content:''}</style><body><span class=a><span class=b></span></span></body>\n"),
            ink("<style>body{margin:0;direction:rtl;text-align:left}.a:before{content:'('}.a:after{content:')'}.b:after{content:''}</style><body><span class=a><span class=b></span></span></body>"),
            "discarded whitespace after empty generated scopes cannot inset their real punctuation");
    }

    #[test]
    fn specification_bidi_visual_fragments_preserve_background_gaps_and_hit_order() {
        let markup="<style>body{margin:0}div{margin:0;width:120px}#split{background:red}</style><div id=gap><span id=split>abא</span>ב</div>";
        let document=crate::html::parse(markup,64).unwrap();
        let split=crate::selector::query_selector(&document,document.root(),"#split").unwrap().unwrap();
        let gap=crate::selector::query_selector(&document,document.root(),"#gap").unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let shaper=RecordingText::default();let list=session.display_list(200,100,&shaper).unwrap().clone();
        let rects=session.client_rects(split);
        assert_eq!(rects.len(),2,"bidi reordering yields actual separated fragments: {rects:?}");
        assert_eq!(rects.iter().map(|rect|rect.width).sum::<f32>(),18.0);
        let bounds=session.bounding_client_rect(split).unwrap();assert_eq!(bounds.width,24.0);
        let mut painted:Vec<Rect>=list.0.iter().filter_map(|command|match command {Command::FillRect{rect,color} if color.r==255&&color.g==0&&color.b==0=>Some(*rect),_=>None}).collect();
        painted.sort_by(|a,b|a.x.total_cmp(&b.x));assert_eq!(painted,rects,"background paints fragments instead of their bounding union");
        assert_eq!(session.hit_test(rects[0].x+rects[0].width+3.0,rects[0].y+3.0),Some(gap),"fragment union cannot steal unwrapped outside text in the visual gap");
        session.document_mut().set_attribute(gap,"style","transform:translate(13px,9px)").unwrap();
        session.display_list(200,100,&shaper).unwrap();
        let moved=session.client_rects(split);assert_eq!(moved.len(),2);
        for (before,after) in rects.iter().zip(&moved){assert_eq!((after.x-before.x,after.y-before.y),(13.0,9.0));assert_eq!((after.width,after.height),(before.width,before.height));}
        assert_eq!(session.hit_test(moved[0].x+moved[0].width+3.0,moved[0].y+3.0),Some(gap),"fragment hit coverage follows the actual ancestor transform");
        session.document_mut().set_attribute(gap,"style","").unwrap();
        session.document_mut().set_attribute(split,"style","padding-left:2px;padding-right:4px").unwrap();
        session.display_list(200,100,&shaper).unwrap();
        let padded=session.client_rects(split);assert_eq!(padded.len(),2);
        assert_eq!(padded.iter().map(|rect|rect.width).sum::<f32>(),24.0,"visual start/end fragments each receive their one physical padding edge");
        assert_eq!(padded[1].x-padded[0].x-padded[0].width,6.0,"outside text remains between the decorated fragments");
    }

    #[test]
    fn specification_css_bidi_scopes_reopen_and_preserve_rendered_source_geometry() {
        #[derive(Default)] struct Directions(core::cell::RefCell<Vec<(String,bool)>>);
        impl TextShaper for Directions {
            fn shape(&self,value:&str,size:f32)->Result<ShapedRun,()>{RecordingText::default().shape(value,size)}
            fn shape_directional(&self,value:&str,size:f32,rtl:bool)->Result<ShapedRun,()>{self.0.borrow_mut().push((value.into(),rtl));self.shape(value,size)}
            fn ascent(&self,_:f32)->f32{10.0}fn line_height(&self,_:f32)->f32{16.0}
        }
        let document=crate::html::parse("<style>body{margin:0}</style><div id=source>a<span dir=rtl>\u{a0}\u{654}\u{670}</span>z</div><div><bdo dir=rtl>abc<br>def</bdo></div><div>ab<span style='direction:rtl;unicode-bidi:normal'>cd</span>ef</div>",128).unwrap();
        let shaper=Directions::default();let mut session=crate::session::RenderSession::new(document);
        session.display_list(400,200,&shaper).unwrap();let calls=shaper.0.borrow();
        assert!(calls.iter().any(|(text,rtl)|text=="\u{a0}\u{654}\u{670}"&&*rtl),"neutral marks inherit their actual isolated RTL scope: {calls:?}");
        for text in ["abc","def"] {assert!(calls.iter().any(|(value,rtl)|value==text&&*rtl),"override reopens across actual BR: {text}, {calls:?}");}
        assert!(calls.iter().any(|(text,rtl)|text=="cd"&&!*rtl),"direction on unicode-bidi:normal inline does not override UAX9: {calls:?}");drop(calls);
        let source=crate::selector::query_selector(session.document(),session.document().root(),"#source").unwrap().unwrap();
        assert_eq!(crate::rendered_text::get(&mut session,source).unwrap(),"a\u{a0}\u{654}\u{670}z","synthetic scope controls cannot enter rendered source text");
        assert!(session.layout_rect(source).unwrap().width>0.0);
    }

    #[test]
    fn specification_modern_transforms_share_shaping_intrinsics_and_separator_hanging() {
        let markup="<style>body{margin:0}div{display:inline-block;margin:0}#wide{width:max-content;text-transform:full-width full-size-kana}#math{text-transform:math-auto}#minimum{width:min-content;text-transform:full-width}</style><div id=wide>a ｧ</div><div id=math><span>a</span><span>ab</span><span>h</span></div><div id=minimum>x<span> </span>x</div>";
        let document=crate::html::parse(markup,128).unwrap();let rules=stylesheets(&document).unwrap();
        let wide=crate::selector::query_selector(&document,document.root(),"#wide").unwrap().unwrap();
        let minimum=crate::selector::query_selector(&document,document.root(),"#minimum").unwrap().unwrap();
        let shaper=RecordingText::default();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,300,100,&shaper,&rules,None,Some(&mut geometry),&[]).unwrap();
        assert!(shaper.0.borrow().iter().any(|value|value=="ａ\u{3000}ア"));
        for value in ["\u{1d44e}","ab","ℎ"] { assert!(shaper.0.borrow().iter().any(|item|item==value),"original Text-node eligibility survives optional cluster-backend fallback: expected {value:?}; calls {:?}",shaper.0.borrow()); }
        assert_eq!(geometry.hits.iter().find(|hit|hit.node==wide&&!hit.virtual_generated).unwrap().rect.width,18.0);
        assert_eq!(geometry.hits.iter().find(|hit|hit.node==minimum&&!hit.virtual_generated).unwrap().rect.width,6.0);
        let mut paragraph=InlineParagraph::default();let mut style=Style::initial();style.white_space=WhiteSpace::PreWrap;
        Layout::paragraph_append_text(&mut paragraph,"x\u{3000}",wide,&style,&[]).unwrap();
        assert_eq!(Layout::paragraph_visible_end(&paragraph,0..paragraph.text.len(),true),1);
        assert_eq!(Layout::paragraph_hanging_end(&paragraph,0..paragraph.text.len(),true,true),paragraph.text.len(),"conditional separators count for max-content");
        style.white_space=WhiteSpace::BreakSpaces;paragraph.spans[0].style=style;
        assert_eq!(Layout::paragraph_visible_end(&paragraph,0..paragraph.text.len(),true),paragraph.text.len());
    }

    #[test]
    fn specification_contextual_case_ignores_out_of_flow_boundaries_and_preserves_source_geometry() {
        for (markup, expected) in [
            ("<main style='text-transform:capitalize'>p<span style='position:absolute'></span>ass</main>", "Pass"),
            ("<main style='text-transform:capitalize'>fo<span style='float:left'></span>o-bar</main>", "Foo-Bar"),
            ("<main lang=nl style='text-transform:capitalize'>i<span style='position:absolute'></span>jsland</main>", "IJsland"),
            ("<style>main{text-transform:capitalize}main::before{content:'p'}</style><main><span style='position:absolute'></span>ass</main>", "Pass"),
            ("<main style='text-transform:capitalize'><i style='text-transform:none'>un</i><span style='position:absolute'></span>changed</main>", "unchanged"),
            ("<main lang=el style='text-transform:uppercase'>Νε<span>ρά</span><span style='position:absolute'></span>ιδα ή Ι<span>\u{308}\u{301}</span>Ρ</main>", "ΝΕΡΑΪΔΑ Ή Ι\u{308}Ρ"),
            ("<main lang=el style='text-transform:lowercase'>ΟΣ<br>Σ</main>", "οςσ"),
        ] {
            assert_eq!(painted_text_runs(markup).concat(), expected, "{markup}");
        }
        for sizing in ["max-content", "min-content"] {
            let document = crate::html::parse(&alloc::format!("<style>body{{margin:0}}#box{{display:inline-block;width:{sizing};text-transform:uppercase}}</style><main id=box lang=el>ᾄ<span style='position:absolute'></span></main>"), 64).unwrap();
            let node = crate::selector::query_selector(&document, document.root(), "#box").unwrap().unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document, 100, 100, &RecordingText::default(), &rules, None, Some(&mut geometry), &[]).unwrap();
            assert_eq!(geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap().rect.width, 12.0, "{sizing} includes the real two-scalar uppercase expansion");
        }
        let document = crate::html::parse("<input lang=el value='ᾄ' style='text-transform:uppercase;width:80px;height:20px'>", 16).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        let list = display_list_with_styles(&document, 100, 60, &RecordingText::default(), &rules, None, Some(&mut geometry), &[]).unwrap();
        // Control geometry records formatted tokens, not individual graphemes.
        // The expanded word has two glyphs but one original source range.
        assert_eq!(geometry.control_text_runs.len(), 1);
        let run = &geometry.control_text_runs[0];
        assert_eq!(run.range, 0.."ᾄ".len());
        assert_eq!(run.display_range, 0.."ΑΙ".len());
        assert_eq!(run.width, 12.0);
        let Command::GlyphRun { glyphs, .. } = &list.0[run.command_index.unwrap()] else { panic!("control expansion retains its actual glyph command"); };
        assert_eq!(glyphs.iter().map(|glyph| glyph.id).collect::<Vec<_>>(), ['Α' as u16, 'Ι' as u16]);
    }

    #[test]
    fn text_transform_shapes_original_inline_context_generated_text_and_control_source_ranges() {
        for (markup,expected) in [
            ("<style>body{margin:0}main{text-transform:uppercase}</style><main>Maß<span> kitty</span></main>","MASS KITTY"),
            ("<main style='text-transform:capitalize'>a<span>b</span>c hello<span> world</span></main>","Abc Hello World"),
            ("<main lang=nl style='text-transform:capitalize'>i<span>jsland</span></main>","IJsland"),
            ("<main lang=tr style='text-transform:uppercase'>i<span lang=''>i</span>ı</main>","İII"),
            ("<style>main{text-transform:uppercase}main::before{content:'maß '}</style><main>cat</main>","MASS CAT"),
            ("<main><script style='display:inline;text-transform:uppercase'>shown</script><style style='display:inline;text-transform:uppercase'>also</style></main>","SHOWNALSO"),
        ] {assert_eq!(painted_text_runs(markup).concat(),expected,"{markup}");}
        let document=crate::html::parse("<input value='İ' style='text-transform:lowercase;width:80px;height:20px'>",16).unwrap();
        let rules=stylesheets(&document).unwrap();
        let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,100,60,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        assert_eq!(geometry.control_text_runs.len(),1);
        assert_eq!(geometry.control_text_runs[0].range,0.."İ".len());
        assert_eq!(geometry.control_text_runs[0].display_range,0.."i\u{307}".len());
    }

    fn painted_text_runs(markup: &str) -> Vec<String> {
        let document = crate::html::parse(markup, 128).unwrap();
        let text = RecordingText::default();
        let list = display_list(&document, 320, 200, &text).unwrap();
        list.0
            .into_iter()
            .filter_map(|command| {
                let Command::GlyphRun { glyphs, .. } = command else {
                    return None;
                };
                Some(
                    glyphs
                        .iter()
                        .filter_map(|glyph| char::from_u32(u32::from(glyph.id)))
                        .collect(),
                )
            })
            .collect()
    }

    #[test]
    fn specification_svg_paint_opacity_cascade_and_retained_commands_share_actual_sources() {
        let document=crate::html::parse("<style>body{margin:0}#front{stroke-opacity:calc(75% - 25%)}.changed #front{fill-opacity:75%;stroke-opacity:25%}</style><svg width=120 height=60><defs><linearGradient id=paint><stop stop-color='red'/><stop offset=1 stop-color='blue'/></linearGradient></defs><g fill-opacity=50% stroke-opacity=75%><rect id=front x=10 y=10 width=40 height=30 fill='url(#paint)' stroke=green stroke-width=4 /></g></svg>",96).unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let front=crate::selector::query_selector(session.document(),session.document().root(),"#front").unwrap().unwrap();
        let body=crate::selector::query_selector(session.document(),session.document().root(),"body").unwrap().unwrap();
        for (class,fill_opacity,stroke_opacity) in [("",0.5,0.5),("changed",0.75,0.25)] {
            session.document_mut().set_attribute(body,"class",class).unwrap();
            let style=session.computed_style(front).unwrap();
            assert_eq!((style.svg_fill_opacity,style.svg_stroke_opacity),(fill_opacity,stroke_opacity));
            assert_eq!(style.computed_css_value("fill-opacity",css::computed_values::ComputedValueContext::default()),Some(alloc::format!("{fill_opacity}")));
            assert_eq!(style.computed_css_value("stroke-opacity",css::computed_values::ComputedValueContext::default()),Some(alloc::format!("{stroke_opacity}")));
            assert!(session.unsupported_svg_features().unwrap().is_empty());
            let list=session.display_list(120,60,&RecordingText::default()).unwrap().clone();
            let (fill,stroke)=list.0.iter().find_map(|command|if let Command::SvgPath{fill:Some(crate::paint::SvgPaint::Gradient(gradient)),stroke:Some(crate::paint::SvgPaint::Color(color)),..}=command{Some((gradient,color))}else{None}).unwrap();
            assert_eq!(fill.opacity,fill_opacity);
            assert!(fill.stops.iter().all(|stop|stop.color.a==255),"paint opacity must preserve the immutable stop alpha source");
            assert_eq!(stroke.a,(255.0_f32*stroke_opacity).round() as u8);
            assert_eq!(session.display_list(120,60,&RecordingText::default()).unwrap(),&list);
            assert_eq!(display_list(session.document(),120,60,&RecordingText::default()).unwrap(),list);
        }
    }

