    #[test]
    fn specification_generated_flex_grid_principals_share_anonymous_items_and_replay() {
        for container in ["block", "flex", "grid"] {
        for display in ["flex", "inline-flex", "grid", "inline-grid"] {
            for sizing in ["width:80px;height:60px", "width:min-content", "width:max-content", "width:auto", "width:80px;aspect-ratio:2", "height:60px;aspect-ratio:2"] {
                let shared=alloc::format!("html,body{{margin:0}}#host{{font:10px/16px monospace;width:240px;display:{container}}}#container,#host::before{{display:{display};{sizing};background:green;padding:3px;border:2px solid blue;justify-content:center;align-items:center;grid-template-columns:70px;gap:5px}}.changed #container,.changed #host::before{{width:120px;height:80px;justify-content:end}}#next{{font:10px/16px monospace}}");
                let generated=alloc::format!("<!doctype html><style>{shared}#host::before{{content:'A B  C'}}</style><div id='host'></div><div id='next'>END</div>");
                let reference=alloc::format!("<!doctype html><style>{shared}</style><div id='host'><div id='container'>A B  C</div></div><div id='next'>END</div>");
                let paint=|list:&DisplayList|list.0.iter().filter(|command|matches!(command,Command::GlyphRun{..}|Command::FillRect{..})).cloned().collect::<Vec<_>>();
                let mut session=crate::session::RenderSession::new(crate::html::parse(&generated,128).unwrap());
                let first=session.display_list(400,300,&RecordingText::default()).unwrap().clone();
                let reference=crate::html::parse(&reference,128).unwrap();
                let expected=display_list(&reference,400,300,&RecordingText::default()).unwrap();
                assert_eq!(paint(&first),paint(&expected),"canonical anonymous item: {display}; {sizing}");
                let host=crate::selector::query_selector(session.document(),session.document().root(),"#host").unwrap().unwrap();
                assert_eq!(session.hit_test(6.0,6.0),Some(host),"generated principal keeps its actual originating hit owner: {container}; {display}; {sizing}");
                assert_eq!(first,session.display_list(400,300,&RecordingText::default()).unwrap().clone());
                let body=crate::selector::query_selector(session.document(),session.document().root(),"body").unwrap().unwrap();
                session.document_mut().set_attribute(body,"class","changed").unwrap();
                let warm=session.display_list(400,300,&RecordingText::default()).unwrap().clone();
                let fresh=display_list(session.document(),400,300,&RecordingText::default()).unwrap();
                assert_eq!(warm,fresh,"retained principal sizing and anonymous source: {display}; {sizing}");
            }
        }
        }
    }

