    // /css/CSS2/generated-content/before-after-positioned-001.xht
    #[test]
    fn specification_image_set_density_scales_raster_but_preserves_vector_natural_dimensions() {
        struct VectorImages;
        impl ImageResolver for VectorImages {
            fn resolve(&self,_:&str)->ImageState { ImageState::Failed }
            fn image_intrinsic_size(&self,_:&Arc<ImageData>,_:css::UsedColorScheme)->Option<crate::object::IntrinsicSize> {
                Some(crate::object::IntrinsicSize{width:Some(80.0),height:Some(40.0),ratio:Some(2.0)})
            }
            fn image_coordinate_scale(&self,_:&Arc<ImageData>,_:f32,_:f32,_:css::UsedColorScheme)->Option<[f32;2]> {Some([1.0;2])}
        }
        let source=BackgroundImage::UrlResolution{url:"opaque-source".into(),density:2.0};
        let image=Arc::new(ImageData{width:80,height:40,pixels:alloc::vec![255;80*40*4]});
        let paint=BackgroundPaint::Image(image);
        let natural=background_natural_size(&source,&paint,Some(&VectorImages),(300.0,150.0),css::UsedColorScheme::Dark,0).unwrap();
        assert_eq!(natural.default_dimensions(),(80.0,40.0));
        let natural=background_natural_size(&source,&paint,None,(300.0,150.0),css::UsedColorScheme::Dark,0).unwrap();
        assert_eq!(natural.default_dimensions(),(40.0,20.0));
    }

