    #[test]
    fn specification_table_generated_percentage_children_share_cell_phases() {
        for algorithm in ["auto", "fixed"] {
            for anonymous in [false, true] {
                for definite in [false, true] {
                    let height = if definite {"100px"}else{"auto"};
                    let selector = if anonymous {"#table"}else{"#cell"};
                    let content = if anonymous {
                        "<div id=table><div id=natural></div></div>"
                    }else{
                        "<div id=table><div style='display:table-row'><div id=cell style='display:table-cell'><div id=natural></div></div><div style='display:table-cell;height:100px'></div></div></div>"
                    };
                    let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}#table{{display:table;table-layout:{algorithm};width:100px;height:{height};border-spacing:0}}#cell{{vertical-align:top}}{selector}::before{{content:'';display:block;height:50%;background:lime}}#natural{{height:20px}}</style>{content}");
                    let document = crate::html::parse(&markup,128).unwrap();
                    let mut session = crate::session::RenderSession::new(document);
                    let id = |session:&crate::session::RenderSession,name:&str| crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                    let table=id(&session,"#table");let owner=id(&session,selector);let natural=id(&session,"#natural");
                    let list=session.display_list(300,300,&SizedText).unwrap().clone();
                    let row_height=if !anonymous || definite {100.0}else{20.0};
                    assert_eq!(session.layout_rect(table).unwrap().height,row_height,"generated source does not inflate natural row height: {algorithm}, anonymous={anonymous}, definite={definite}");
                    assert_eq!(session.pseudo_layout_rect(owner,css::PseudoElement::Before).unwrap().height,if definite {50.0}else{0.0},"generated source consumes the eligible assigned cell basis: {algorithm}, anonymous={anonymous}, definite={definite}");
                    assert_eq!(session.layout_rect(natural).unwrap().height,20.0);
                    assert_eq!(list,session.display_list(300,300,&SizedText).unwrap().clone());
                    session.document_mut().set_attribute(table,"style","height:200px").unwrap();
                    let retained=session.display_list(300,300,&SizedText).unwrap().clone();
                    assert_eq!(session.layout_rect(table).unwrap().height,200.0);
                    assert_eq!(session.pseudo_layout_rect(owner,css::PseudoElement::Before).unwrap().height,100.0);
                    assert_eq!(session.layout_rect(natural).unwrap().height,20.0);
                    assert_eq!(retained,display_list(session.document(),300,300,&SizedText).unwrap());
                }
            }
        }
    }

