    #[test]
    fn specification_table_percentage_children_resolve_only_in_the_assigned_cell_phase() {
        for algorithm in ["auto","fixed"] {
            for table_height in ["auto","100px","100%"] {
                for cell_height in ["auto","40px","50%"] {
                    for definite_parent in [false,true] {
                        for edges in [false,true] {
                            let row_height = if edges {114.0}else{100.0};
                            let content_height = 100.0;
                            let decoration = if edges {"padding:5px;border:2px solid black"}else{"padding:0;border:0"};
                            let parent_height = if definite_parent {alloc::format!("{row_height}px")}else{String::from("auto")};
                            let eligible = cell_height=="40px" || table_height!="auto";
                            let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}#wrapper{{height:{parent_height}}}table{{table-layout:{algorithm};width:200px;height:{table_height};border-spacing:0}}td{{vertical-align:top;{decoration}}}#first{{height:{cell_height}}}#child{{height:50%}}#natural{{height:20px}}#other{{height:100px}}</style><div id=wrapper><table id=table><tr><td id=first><div id=child><div id=natural></div></div></td><td><div id=other></div></td></tr></table></div>");
                            let document = crate::html::parse(&markup,128).unwrap();
                            let mut session = crate::session::RenderSession::new(document);
                            let find = |session:&crate::session::RenderSession,name:&str| crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                            let table = find(&session,"#table");let first = find(&session,"#first");let child = find(&session,"#child");let natural = find(&session,"#natural");
                            let list = session.display_list(400,400,&SizedText).unwrap().clone();
                            assert_eq!(session.layout_rect(table).unwrap().height,row_height,"actual natural minimum precedes percentage content: {algorithm}, table={table_height}, cell={cell_height}, definite={definite_parent}, edges={edges}");
                            assert_eq!(session.layout_rect(first).unwrap().height,row_height);
                            assert_eq!(session.layout_rect(child).unwrap().height,if eligible {content_height*0.5}else{20.0},"explicit source eligibility, including table percentage behaving as auto: table={table_height}, cell={cell_height}, definite={definite_parent}, edges={edges}");
                            assert_eq!(session.layout_rect(natural).unwrap().height,20.0);
                            assert_eq!(list,session.display_list(400,400,&SizedText).unwrap().clone());
                            session.document_mut().set_attribute(child,"style","height:150%").unwrap();
                            let retained = session.display_list(400,400,&SizedText).unwrap().clone();
                            assert_eq!(session.layout_rect(table).unwrap().height,row_height,"second-pass overflowing percentages do not enlarge first-pass row minimum");
                            assert_eq!(session.layout_rect(child).unwrap().height,if eligible {content_height*1.5}else{20.0});
                            assert_eq!(retained,display_list(session.document(),400,400,&SizedText).unwrap());
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn specification_table_scrollable_percentage_children_do_not_inflate_natural_rows() {
        for algorithm in ["auto","fixed"] {
            for overflow in ["auto","scroll","visible","hidden","clip"] {
                for declaration in ["height:100%","height:calc(10px + 100%)","height:auto;min-height:100%"] {
                    let scrolling = matches!(overflow,"auto"|"scroll");
                    let natural = if scrolling && !declaration.contains("height:auto") {100.0}else{500.0};
                    let used = if declaration.contains("calc") {natural+10.0}else{natural};
                    let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{table-layout:{algorithm};width:100px;height:100px;border-spacing:0}}td{{padding:0;vertical-align:top}}#child{{overflow:{overflow};{declaration}}}#content{{height:500px}}</style><table id=table><tr><td><div id=child><div id=content></div></div></td></tr></table>");
                    let document = crate::html::parse(&markup,128).unwrap();
                    let mut session = crate::session::RenderSession::new(document);
                    let find = |session:&crate::session::RenderSession,name:&str| crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                    let table = find(&session,"#table");let child = find(&session,"#child");let content = find(&session,"#content");
                    let list = session.display_list(300,700,&SizedText).unwrap().clone();
                    assert_eq!(session.layout_rect(table).unwrap().height,natural,"first-pass scrollable percentage height is zero while visible/hidden/clip content measures auto: {algorithm}, {overflow}, {declaration}");
                    assert_eq!(session.layout_rect(child).unwrap().height,used,"final source percentage uses assigned content basis");
                    assert_eq!(session.layout_rect(content).unwrap().height,500.0,"scrolling content source remains intact");
                    assert_eq!(list,session.display_list(300,700,&SizedText).unwrap().clone());
                    assert_eq!(list,display_list(session.document(),300,700,&SizedText).unwrap());
                }
            }
        }
    }

    #[test]
    fn specification_inline_block_baselines_skip_block_tables_but_keep_actual_lines() {
        struct TableText;
        impl TextShaper for TableText {
            fn shape(&self,text:&str,size:f32)->Result<ShapedRun,()> { RecordingText::default().shape(text,size) }
            fn ascent(&self,size:f32)->f32 { SizedText.ascent(size) }
            fn line_height(&self,size:f32)->f32 { SizedText.line_height(size) }
        }
        for algorithm in ["auto", "fixed"] {
            for wrapped in [false, true] {
                for before in [false,true] {
                    for after in [false,true] {
                        let first = if before {"A"}else{""};
                        let last = if after {"C"}else{""};
                        let table = "<table id=table><tr><td>B</td></tr></table>";
                        let middle = if wrapped {alloc::format!("<div>{table}</div>")}else{String::from(table)};
                        let height = 40.0 + if before {10.0}else{0.0} + if after {10.0}else{0.0};
                        let baseline = if after {48.0 + if before {10.0}else{0.0}}else if before {8.0}else{40.0};
                        let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}#host{{font-size:0;line-height:0}}#marker{{display:inline-block;width:20px;height:{baseline}px}}#atomic{{display:inline-block;width:80px;font:10px/10px monospace}}table{{table-layout:{algorithm};width:80px;height:40px;border-spacing:0}}td{{padding:0;vertical-align:baseline}}</style><div id=host><i id=marker></i><span id=atomic>{first}{middle}{last}</span></div>");
                        let document = crate::html::parse(&markup,128).unwrap();
                        assert_eq!(document.document_mode(),crate::DocumentMode::NoQuirks,"baseline discovery fixture explicitly uses standards mode");
                        let mut session = crate::session::RenderSession::new(document);
                        let find = |session:&crate::session::RenderSession,name:&str| crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                        let marker = find(&session,"#marker");
                        let atomic = find(&session,"#atomic");
                        let list = session.display_list(300,300,&TableText).unwrap().clone();
                        assert_eq!(session.layout_rect(marker).unwrap().y,0.0,"block table is not an inline-block line baseline: {algorithm}, wrapped={wrapped}, before={before}, after={after}");
                        assert_eq!(session.layout_rect(atomic).unwrap(),Rect{x:20.0,y:0.0,width:80.0,height},"skip discovery does not remove actual table height or ink");
                        assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{glyphs,..} if glyphs.iter().any(|glyph|glyph.id==u16::from(b'B')))),"table content still paints");
                        assert_eq!(list,session.display_list(300,300,&TableText).unwrap().clone());
                        assert_eq!(list,display_list(session.document(),300,300,&TableText).unwrap());
                        if !before && !after && !wrapped {
                            // The same child table now belongs to a table-cell
                            // discovery context. Its row baseline must return,
                            // including when a retained child fragment exists.
                            session.document_mut().set_attribute(atomic,"style","display:inline-table").unwrap();
                            session.document_mut().set_attribute(marker,"style","height:8px").unwrap();
                            let retained = session.display_list(300,300,&TableText).unwrap().clone();
                            let nested = find(&session,"#table");
                            let cell = find(&session,"td");
                            for (name,node) in [("#atomic",atomic),("#table",nested),("td",cell)] {
                                assert_eq!(session.computed_style_with_text(node,Some(&TableText)).unwrap().font_size,10.0,
                                    "dynamic standards discovery retains computed DOM font at {name}, {node:?}; mode={:?}",session.document().document_mode());
                            }
                            let ink = retained.0.iter().find_map(|command|match command {
                                Command::GlyphRun{baseline_y,size,glyphs,..} if glyphs.iter().any(|glyph|glyph.id==u16::from(b'B')) => Some((*baseline_y,*size)),
                                _=>None,
                            }).unwrap();
                            let atomic_rect = session.layout_rect(atomic).unwrap();
                            let nested_rect = session.layout_rect(nested).unwrap();
                            assert_eq!(ink.1,10.0,"actual nested text uses inherited font; ink={ink:?}, atomic={atomic_rect:?}, nested={nested_rect:?}");
                            assert_eq!(ink.0-atomic_rect.y,8.0,"nested actual first-row ink baseline agrees with computed font; ink={ink:?}, atomic={atomic_rect:?}, nested={nested_rect:?}");
                            assert_eq!(session.layout_rect(marker).unwrap().y,0.0,"nested table row baseline returns in cell discovery; ink={ink:?}, atomic={atomic_rect:?}, nested={nested_rect:?}");
                            assert_eq!(session.layout_rect(atomic).unwrap().y,0.0);
                            assert_eq!(retained,display_list(session.document(),300,300,&TableText).unwrap(),"discovery purpose participates in retained fragment identity");
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn specification_table_height_constraints_consume_winning_collapsed_borders() {
        for algorithm in ["auto","fixed"] {
            for sizing in ["content-box","border-box"] {
                for padding in [0,2] {
                    for span in [1,2] {
                        let expected = if sizing=="border-box" {3.0f32.max(padding as f32*2.0)}else{3.0+padding as f32*2.0};
                        let rows = if span==1 {"<tr><td id=cell></td></tr>"}else{"<tr><td id=cell rowspan=2></td><td></td></tr><tr><td></td></tr>"};
                        let markup = |border:&str| alloc::format!("<style>html,body{{margin:0}}table{{table-layout:{algorithm};width:100px;border-collapse:collapse}}tr{{border:20px hidden}}td{{padding:0;border:0}}#cell{{height:3px;box-sizing:{sizing};padding:{padding}px;border:{border};margin:30px}}</style><table id=table>{rows}</table>");
                        let mut snapshots = Vec::new();
                        for border in ["20px solid red","0"] {
                            let document = crate::html::parse(&markup(border),128).unwrap();
                            let mut session = crate::session::RenderSession::new(document);
                            let table = crate::selector::query_selector(session.document(),session.document().root(),"#table").unwrap().unwrap();
                            let first = session.display_list(300,300,&SizedText).unwrap().clone();
                            let rect = session.layout_rect(table).unwrap();
                            assert_eq!(rect.height,expected,"used hidden winners precede box-sizing floor: {algorithm}, {sizing}, padding={padding}, rowspan={span}, {border}");
                            assert_eq!(first,session.display_list(300,300,&SizedText).unwrap().clone());
                            snapshots.push(rect);
                        }
                        assert_eq!(snapshots[0],snapshots[1],"discarded authored border cannot constrain the used cell box");
                    }
                }
            }
        }
    }

    #[test]
    fn specification_percentage_table_cell_constraints_share_used_border_box_authority() {
        for algorithm in ["auto","fixed"] {
            for sizing in ["content-box","border-box"] {
                let first_height = if sizing=="border-box" {50.0}else{54.0};
                let markup = |border:&str| alloc::format!("<style>html,body{{margin:0}}table{{table-layout:{algorithm};width:100px;height:100px;border-collapse:collapse}}tr{{border:20px hidden}}td{{padding:0;border:0}}#first{{height:50%;box-sizing:{sizing};padding:2px;border:{border};margin:30px}}#content{{height:1px}}</style><table id=table><tr><td id=first></td></tr><tr><td id=second><div id=content></div></td></tr></table>");
                for border in ["20px solid red","0"] {
                    let document = crate::html::parse(&markup(border),128).unwrap();
                    let mut session = crate::session::RenderSession::new(document);
                    let find = |session:&crate::session::RenderSession,name:&str| crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                    let table = find(&session,"#table");let first = find(&session,"#first");let second = find(&session,"#second");let content = find(&session,"#content");
                    let list = session.display_list(300,300,&SizedText).unwrap().clone();
                    assert_eq!(session.layout_rect(table).unwrap().height,100.0);
                    assert_eq!(session.layout_rect(first).unwrap().height,first_height,"percentage minimum uses winning borders and excludes inapplicable margins: {algorithm}, {sizing}, {border}");
                    assert_eq!(session.layout_rect(second).unwrap().y,first_height);
                    assert_eq!(session.layout_rect(second).unwrap().height,100.0-first_height);
                    assert_eq!(session.layout_rect(content).unwrap().height,1.0,"assigned cell height does not become natural child height");
                    assert_eq!(list,session.display_list(300,300,&SizedText).unwrap().clone());
                    assert_eq!(list,display_list(session.document(),300,300,&SizedText).unwrap());
                }
            }
        }
    }

    #[test]
    fn specification_empty_table_rows_synthesize_from_assigned_content_edges() {
        for algorithm in ["auto", "fixed"] {
            for row_count in [1usize, 2] {
                for edges in [false, true] {
                    let bottom = if edges { 7.0 } else { 0.0 };
                    let expected = 100.0 / row_count as f32 - bottom;
                    let decoration = if edges { "padding:5px;border:2px solid green" } else { "padding:0;border:0" };
                    let rows = (0..row_count).map(|_| "<tr><td></td></tr>").collect::<String>();
                    let markup = alloc::format!("<style>html,body{{margin:0}}#host{{font-size:0;line-height:0}}#marker{{display:inline-block;width:20px;height:{expected}px}}#table{{display:inline-table;table-layout:{algorithm};width:50px;height:100px;border-spacing:0}}td{{height:10px;{decoration}}}</style><div id=host><i id=marker></i><table id=table>{rows}</table></div>");
                    let document = crate::html::parse(&markup,128).unwrap();
                    let mut session = crate::session::RenderSession::new(document);
                    let find = |session:&crate::session::RenderSession,name:&str| crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                    let marker = find(&session,"#marker");
                    let table = find(&session,"#table");
                    let first = session.display_list(300,300,&SizedText).unwrap().clone();
                    assert_eq!(session.layout_rect(table).unwrap(),Rect{x:20.0,y:0.0,width:50.0,height:100.0},"assigned first-row fallback; {algorithm}, {row_count}, edges={edges}");
                    assert_eq!(session.layout_rect(marker).unwrap().y,0.0);
                    assert_eq!(first,session.display_list(300,300,&SizedText).unwrap().clone(),"warm geometry is stable");
                    let next = 200.0 / row_count as f32 - bottom;
                    session.document_mut().set_attribute(marker,"style",&alloc::format!("height:{next}px")).unwrap();
                    session.document_mut().set_attribute(table,"style","height:200px").unwrap();
                    let retained = session.display_list(300,300,&SizedText).unwrap().clone();
                    assert_eq!(session.layout_rect(table).unwrap().y,0.0,"height redistribution refreshes synthesized baseline");
                    assert_eq!(session.layout_rect(marker).unwrap().y,0.0);
                    assert_eq!(retained,display_list(session.document(),300,300,&SizedText).unwrap(),"retained/fresh baseline authority");
                }
            }
        }
    }

    #[test]
    fn specification_table_authored_minima_do_not_replace_real_content_baselines() {
        struct TableText;
        impl TextShaper for TableText {
            fn shape(&self,text:&str,size:f32)->Result<ShapedRun,()> { RecordingText::default().shape(text,size) }
            fn ascent(&self,size:f32)->f32 { SizedText.ascent(size) }
            fn line_height(&self,size:f32)->f32 { SizedText.line_height(size) }
        }
        for algorithm in ["auto", "fixed"] {
            for collapse in ["separate", "collapse"] {
                for empty in ["", " ", "<span style='display:none'>ignored</span>"] {
                    let markup = alloc::format!("<style>html,body{{margin:0}}#host{{font-size:0;line-height:0}}#marker{{display:inline-block;width:20px;height:16px}}table{{display:inline-table;table-layout:{algorithm};width:80px;border-spacing:0;border-collapse:{collapse}}}td{{padding:0;border:0;font:20px/20px monospace;vertical-align:baseline}}#empty{{height:100px}}</style><div id=host><i id=marker></i><table id=table><tr><td>A</td><td id=empty>{empty}</td></tr></table></div>");
                    let document = crate::html::parse(&markup,128).unwrap();
                    let table = crate::selector::query_selector(&document,document.root(),"#table").unwrap().unwrap();
                    let mut geometry = LayoutGeometry::default();
                    let list = display_list_with_styles(&document,300,300,&TableText,&stylesheets(&document).unwrap(),None,Some(&mut geometry),&[]).unwrap();
                    let rect = geometry.hits.iter().find(|hit|hit.node==table&&!hit.virtual_generated).unwrap().rect;
                    assert_eq!(rect,Rect{x:20.0,y:0.0,width:80.0,height:100.0},"empty authored minimum does not pull actual text baseline: {algorithm}, {collapse}, {empty:?}");
                    let baseline = list.0.iter().find_map(|command|match command {Command::GlyphRun{baseline_y,glyphs,..} if glyphs.iter().any(|glyph|glyph.id==u16::from(b'A'))=>Some(*baseline_y),_=>None}).unwrap();
                    assert_eq!(baseline,16.0);
                }
            }
            // No line/row exists in this cell, but its actual block content
            // provides a natural content-edge baseline. Authored height only
            // raises the row minimum; it cannot turn that content into 100px.
            let markup = alloc::format!("<style>html,body{{margin:0}}#host{{font-size:0;line-height:0}}#marker{{display:inline-block;width:20px;height:20px}}table{{display:inline-table;table-layout:{algorithm};width:80px;border-spacing:0}}td{{height:100px;padding:0;vertical-align:baseline}}#content{{height:20px}}</style><div id=host><i id=marker></i><table id=table><tr><td><div id=content></div></td></tr></table></div>");
            let document = crate::html::parse(&markup,128).unwrap();
            let mut session = crate::session::RenderSession::new(document);
            session.display_list(300,300,&SizedText).unwrap();
            for (name,height) in [("#table",100.0),("#content",20.0)] {
                let node = crate::selector::query_selector(session.document(),session.document().root(),name).unwrap().unwrap();
                let rect = session.layout_rect(node).unwrap();
                assert_eq!((rect.y,rect.height),(0.0,height),"actual non-line content retained: {algorithm}, {name}");
            }
        }
    }

    #[test]
    fn specification_spanning_table_cells_align_with_their_originating_row() {
        struct TableText;
        impl TextShaper for TableText {
            fn shape(&self,text:&str,size:f32)->Result<ShapedRun,()> { RecordingText::default().shape(text,size) }
            fn ascent(&self,size:f32)->f32 { SizedText.ascent(size) }
            fn line_height(&self,size:f32)->f32 { SizedText.line_height(size) }
        }
        for algorithm in ["auto", "fixed"] {
            for minimum in ["", "height:80px"] {
                let markup = alloc::format!("<style>html,body{{margin:0}}table{{table-layout:{algorithm};width:80px;border-spacing:0}}td{{padding:0;border:0;font:10px/10px monospace;vertical-align:baseline}}#span{{font:40px/40px monospace;{minimum}}}</style><table id=table><tr><td id=span rowspan=2>A</td><td>B</td></tr><tr><td>C</td></tr></table>");
                let document = crate::html::parse(&markup,128).unwrap();
                let mut geometry = LayoutGeometry::default();
                let list = display_list_with_styles(&document,300,300,&TableText,&stylesheets(&document).unwrap(),None,Some(&mut geometry),&[]).unwrap();
                let baseline = |id:u16| list.0.iter().find_map(|command|match command {Command::GlyphRun{baseline_y,glyphs,..} if glyphs.iter().any(|glyph|glyph.id==id)=>Some(*baseline_y),_=>None}).unwrap();
                assert_eq!(baseline(u16::from(b'A')),32.0,"spanning cell baseline participates before span-height allocation");
                assert_eq!(baseline(u16::from(b'B')),32.0,"originating row shares spanning baseline: {algorithm}, {minimum}");
                assert!(baseline(u16::from(b'C'))>32.0,"later row retains its own baseline");
                let table = crate::selector::query_selector(&document,document.root(),"#table").unwrap().unwrap();
                let rect = geometry.hits.iter().find(|hit|hit.node==table&&!hit.virtual_generated).unwrap().rect;
                assert_eq!(rect.height,if minimum.is_empty() {44.0}else{80.0},"spanning descent is allocated once, while authored minimum remains a constraint");
            }
        }
    }

    #[test]
    fn specification_vertical_block_progression_is_independent_of_inline_direction_and_alignment() {
        for mode in ["vertical-rl", "vertical-lr"] {
            for direction in ["ltr", "rtl"] {
                for child_mode in ["horizontal-tb", "vertical-rl", "vertical-lr"] {
                    for inline_alignment in ["", "margin-left:auto", "margin-right:auto", "justify-self:center"] {
                        let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}#parent{{writing-mode:{mode};direction:{direction};width:80px;height:30px;font-size:0;line-height:0}}i{{display:block;writing-mode:{child_mode};width:8px;height:10px;{inline_alignment}}}</style><div id=parent><i id=first></i><i id=second></i></div>");
                        let document=crate::html::parse(&markup,64).unwrap();
                        let find=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
                        let parent=find("#parent");let first=find("#first");let second=find("#second");
                        let mut session=crate::session::RenderSession::new(document);
                        session.display_list(200,200,&FixedText).unwrap();
                        let origin=session.layout_rect(parent).unwrap().x;
                        for (node,offset) in [(first,if mode=="vertical-rl"{72.0}else{0.0}),(second,if mode=="vertical-rl"{64.0}else{8.0})] {
                            let rect=session.layout_rect(node).unwrap();
                            assert_eq!((rect.x,rect.width,rect.height),(origin+offset,8.0,10.0),"actual block progression {mode}/{direction}/{child_mode}/{inline_alignment}");
                        }
                        let warm=session.display_list(200,200,&FixedText).unwrap().clone();
                        assert_eq!(warm,display_list(session.document(),200,200,&FixedText).unwrap());
                        session.document_mut().set_attribute(parent,"style",if direction=="rtl"{"direction:ltr"}else{"direction:rtl"}).unwrap();
                        let changed=session.display_list(200,200,&FixedText).unwrap().clone();
                        assert_eq!(session.layout_rect(first).unwrap().x,origin+if mode=="vertical-rl"{72.0}else{0.0},"inline direction cannot change block progression");
                        assert_eq!(changed,display_list(session.document(),200,200,&FixedText).unwrap());
                    }
                }
            }
        }
    }

    #[test]
    fn specification_orthogonal_cell_inline_constraints_survive_rowmin_and_control_real_glyph_lines() {
        for vertical_mode in ["vertical-rl", "vertical-lr", "sideways-rl", "sideways-lr"] {
            for vertical_cell in [true,false] {
                for constrained in [false,true] {
                    let (table_mode,cell_mode)=if vertical_cell {("horizontal-tb",vertical_mode)}else{(vertical_mode,"horizontal-tb")};
                    let sizing=if constrained {"max-inline-size:12px"}else{"inline-size:24px"};
                    let text=if constrained {"AB CD"}else{"ABCD"};
                    let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{table_mode};border-spacing:0}}td{{writing-mode:{cell_mode};text-orientation:sideways;{sizing};padding:0;border:0;font:16px/16px monospace}}</style><table id=table><tr><td id=cell>{text}</td></tr></table>");
                    let document=crate::html::parse(&markup,64).unwrap();
                    let find=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
                    let table=find("#table");let cell=find("#cell");
                    let mut session=crate::session::RenderSession::new(document);
                    let list=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
                    let (inline,block)=if constrained {(12.0,32.0)}else{(24.0,16.0)};
                    let expected=if vertical_cell {(block,inline)}else{(inline,block)};
                    for node in [table,cell] {let rect=session.layout_rect(node).unwrap();assert_eq!((rect.width,rect.height),expected,"orthogonal own inline source {table_mode}/{cell_mode}/{sizing}");}
                    let points=painted_baseline_points(&list);
                    assert_eq!(points.len(),if constrained {2}else{1},"actual glyph line count {table_mode}/{cell_mode}/{sizing}");
                    if constrained {
                        let distance=if vertical_cell {(points[1].0-points[0].0).abs()}else{(points[1].1-points[0].1).abs()};
                        assert_eq!(distance,16.0,"one actual line-height between source baselines");
                    }
                    let warm=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
                    assert_eq!(warm,display_list(session.document(),200,200,&RecordingText::default()).unwrap());
                    session.document_mut().set_attribute(cell,"style",if constrained {"max-inline-size:none;inline-size:24px"}else{"inline-size:auto;max-inline-size:12px"}).unwrap();
                    let changed=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
                    assert_eq!(changed,display_list(session.document(),200,200,&RecordingText::default()).unwrap(),"own inline constraints invalidate retained cell measurements");
                }
            }
        }
    }

    #[test]
    fn specification_table_cell_real_glyph_baselines_share_the_actual_physical_row_axis() {
        struct ScaledCellText;
        impl TextShaper for ScaledCellText {
            fn shape(&self,text:&str,size:f32)->Result<ShapedRun,()> {
                let mut run=RecordingText::default().shape(text,size)?;
                for glyph in Arc::make_mut(&mut run.glyphs) {glyph.x*=size/12.0;}
                run.width*=size/12.0;
                Ok(run)
            }
            fn ascent(&self,size:f32)->f32 {size*0.8}
            fn line_height(&self,size:f32)->f32 {size}
        }
        for mode in ["horizontal-tb","vertical-rl","vertical-lr","sideways-rl","sideways-lr"] {
            for direction in ["ltr","rtl"] {
                let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{mode};direction:{direction};text-orientation:sideways;border-spacing:0}}td{{padding:0;vertical-align:baseline}}#small{{font:10px/10px monospace}}#large{{font:20px/20px monospace}}</style><table id=table><tr><td id=small>A</td><td id=large>B</td></tr></table>");
                let document=crate::html::parse(&markup,64).unwrap();
                let table=crate::selector::query_selector(&document,document.root(),"#table").unwrap().unwrap();
                let mut session=crate::session::RenderSession::new(document);
                let list=session.display_list(200,200,&ScaledCellText).unwrap().clone();
                let points=painted_baseline_points(&list);
                assert_eq!(points.len(),2);
                let border=session.layout_rect(table).unwrap();
                let horizontal=mode=="horizontal-tb";
                let coordinate=|point:(f32,f32,f32)|if horizontal {point.1}else{point.0};
                assert_eq!(coordinate(points[0]),coordinate(points[1]),"actual two-font baseline coincidence {mode}/{direction}");
                let origin=if horizontal {border.y}else{border.x};
                let offset=if matches!(mode,"vertical-rl"|"vertical-lr"|"sideways-rl") {4.0}else{16.0};
                assert_eq!(coordinate(points[0]),origin+offset,"measured20px line's alphabetic baseline authority {mode}/{direction}");
                assert_eq!(if horizontal{border.height}else{border.width},20.0,"actual line content determines row minimum");
                let warm=session.display_list(200,200,&ScaledCellText).unwrap().clone();
                assert_eq!(warm,display_list(session.document(),200,200,&ScaledCellText).unwrap());
            }
        }
    }

    #[test]
    fn specification_upright_table_tracks_use_ltr_while_computed_direction_remains_rtl() {
        for mode in ["vertical-rl","vertical-lr"] {
            for collapse in ["separate","collapse"] {
                let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{mode};direction:rtl;text-orientation:upright;width:50px;height:60px;border-collapse:{collapse};border-spacing:0;font-size:0;line-height:0}}td{{height:30px;padding:0}}tr:first-child td{{width:20px}}tr:last-child td{{width:30px}}</style><table id=table><col id=col1><col id=col2><tr><td id=a></td><td id=b></td></tr><tr><td id=c></td><td id=d></td></tr></table>");
                let document=crate::html::parse(&markup,96).unwrap();
                let find=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
                let table=find("#table");let first=find("#a");let second=find("#b");let col1=find("#col1");let col2=find("#col2");
                let mut session=crate::session::RenderSession::new(document);
                session.display_list(200,200,&FixedText).unwrap();
                assert_eq!(session.layout_rect(first).unwrap().y,0.0,"upright first source cell {mode}/{collapse}");
                assert_eq!(session.layout_rect(second).unwrap().y,30.0,"upright second source cell {mode}/{collapse}");
                assert_eq!(session.layout_rect(col1).unwrap().y,0.0);
                assert_eq!(session.layout_rect(col2).unwrap().y,30.0);
                let warm=session.display_list(200,200,&FixedText).unwrap().clone();
                assert_eq!(warm,display_list(session.document(),200,200,&FixedText).unwrap());
                session.document_mut().set_attribute(table,"style","text-orientation:sideways").unwrap();
                let changed=session.display_list(200,200,&FixedText).unwrap().clone();
                assert_eq!(session.layout_rect(first).unwrap().y,30.0,"sideways restores computedRTL used progression");
                assert_eq!(session.layout_rect(second).unwrap().y,0.0);
                assert_eq!(changed,display_list(session.document(),200,200,&FixedText).unwrap());
            }
        }
    }

    #[test]
    fn specification_table_cell_alignment_uses_line_over_not_block_progression() {
        for cell_mode in ["vertical-rl", "vertical-lr", "sideways-rl", "sideways-lr"] {
            for table_mode in ["horizontal-tb", cell_mode] {
                for direction in ["ltr", "rtl"] {
                    for alignment in ["top", "middle", "bottom"] {
                        let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{table_mode};direction:{direction};width:80px;height:30px;border-spacing:0;font-size:0;line-height:0}}td{{writing-mode:{cell_mode};width:80px;height:30px;padding:0;vertical-align:{alignment}}}i{{display:block;width:8px;height:10px;background:green}}</style><table><tr><td id=cell><i id=ink></i></td></tr></table>");
                        let document=crate::html::parse(&markup,64).unwrap();
                        let find=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
                        let cell=find("#cell");let ink=find("#ink");
                        let mut session=crate::session::RenderSession::new(document);
                        session.display_list(200,200,&FixedText).unwrap();
                        let border=session.layout_rect(cell).unwrap();let content=session.layout_rect(ink).unwrap();
                        assert_eq!((border.width,border.height),(80.0,30.0));
                        let over_left=cell_mode=="sideways-lr";
                        let offset=match alignment {"middle"=>36.0,"top" if !over_left=>72.0,"bottom" if over_left=>72.0,_=>0.0};
                        assert_eq!((content.x,content.width,content.height),(border.x+offset,8.0,10.0),"line-relative alignment {table_mode}/{cell_mode}/{direction}/{alignment}");
                        let warm=session.display_list(200,200,&FixedText).unwrap().clone();
                        assert_eq!(warm,display_list(session.document(),200,200,&FixedText).unwrap());
                        session.document_mut().set_attribute(cell,"style",if alignment=="top"{"vertical-align:bottom"}else{"vertical-align:top"}).unwrap();
                        let updated=session.display_list(200,200,&FixedText).unwrap().clone();
                        let changed_offset=if alignment=="top" {if over_left{72.0}else{0.0}}else{if over_left{0.0}else{72.0}};
                        assert_eq!(session.layout_rect(ink).unwrap().x,border.x+changed_offset);
                        assert_eq!(updated,display_list(session.document(),200,200,&FixedText).unwrap(),"line-over used source invalidation");
                    }
                }
            }
        }
    }

    #[test]
    fn specification_vertical_table_tracks_project_cells_captions_and_own_line_alignment() {
        for mode in ["vertical-rl", "vertical-lr"] {
            for direction in ["ltr", "rtl"] {
                for align in ["top", "middle", "bottom"] {
                    for captions in [false, true] {
                        let markup = alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{mode};direction:{direction};height:60px;width:50px;border-spacing:0;font-size:0;line-height:0}}td{{padding:0;height:30px;vertical-align:{align}}}tr:first-child td{{width:20px}}tr:last-child td{{width:30px}}i{{display:block;width:8px;height:10px;background:green}}caption{{height:60px}}#before{{width:5px}}#after{{width:7px;caption-side:bottom}}</style><table id=table>{}<tbody><tr><td id=a><i id=ink></i></td><td id=b><i></i></td></tr><tr><td id=c><i></i></td><td id=d><i></i></td></tr></tbody></table>",
                            if captions { "<caption id=before></caption><caption id=after></caption>" } else { "" });
                        let document = crate::html::parse(&markup, 96).unwrap();
                        let find = |name| crate::selector::query_selector(&document, document.root(), name).unwrap().unwrap();
                        let nodes = [find("#table"),find("#a"),find("#b"),find("#c"),find("#d"),find("#ink")];
                        let mut session = crate::session::RenderSession::new(document);
                        session.display_list(200, 200, &FixedText).unwrap();
                        let rect = |session: &crate::session::RenderSession, node| session.layout_rect(node).unwrap();
                        let rl = mode == "vertical-rl";
                        let rtl = direction == "rtl";
                        let grid_x = if captions { if rl { 7.0 } else { 5.0 } } else { 0.0 };
                        assert_eq!(rect(&session,nodes[0]), Rect{x:grid_x,y:0.0,width:50.0,height:60.0},"grid {mode}/{direction}/{align}/{captions}");
                        for (index,row,column,cell_width) in [(1,0,0,20.0),(2,0,1,20.0),(3,1,0,30.0),(4,1,1,30.0)] {
                            let x = grid_x + if rl { if row == 0 {30.0}else{0.0} } else if row == 0 {0.0}else{20.0};
                            let y = if (column == 1) != rtl {30.0}else{0.0};
                            assert_eq!(rect(&session,nodes[index]),Rect{x,y,width:cell_width,height:30.0},"cell {index}: {mode}/{direction}/{align}/{captions}");
                        }
                        let first = rect(&session,nodes[1]);
                        let offset = match align { "top"=>12.0,"middle"=>6.0,_=>0.0 };
                        let ink_x = first.x + offset;
                        assert_eq!(rect(&session,nodes[5]).x,ink_x,"vertical-align follows own line-over (right) for {mode}/{direction}/{align}");
                        if captions {
                            let before=crate::selector::query_selector(session.document(),session.document().root(),"#before").unwrap().unwrap();
                            let after=crate::selector::query_selector(session.document(),session.document().root(),"#after").unwrap().unwrap();
                            assert_eq!(rect(&session,before),Rect{x:if rl{57.0}else{0.0},y:0.0,width:5.0,height:60.0});
                            assert_eq!(rect(&session,after),Rect{x:if rl{0.0}else{55.0},y:0.0,width:7.0,height:60.0});
                        }
                        let warm = session.display_list(200,200,&FixedText).unwrap().clone();
                        let fresh = display_list(session.document(),200,200,&FixedText).unwrap();
                        assert_eq!(warm,fresh,"retained source projection {mode}/{direction}/{align}/{captions}");
                        session.document_mut().set_attribute(nodes[0],"style",if rtl{"direction:ltr"}else{"direction:rtl"}).unwrap();
                        let updated = session.display_list(200,200,&FixedText).unwrap().clone();
                        assert_eq!(updated,display_list(session.document(),200,200,&FixedText).unwrap(),"direction invalidates retained track ownership");
                    }
                }
            }
        }
    }

    #[test]
    fn specification_vertical_table_indefinite_inline_space_uses_nearest_port_and_fixed_constraints() {
        for mode in ["vertical-rl","vertical-lr"] {
            for (outer,inner,expected) in [
                ("","max-height:12px",12.0),
                ("height:8px;overflow:auto","",8.0),
                ("height:20px;overflow:auto","max-height:12px",12.0),
                ("","min-height:8px;max-height:4px",8.0),
            ] {
                let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{mode};border-spacing:0;font:10px/3px monospace}}td{{padding:0}}#outer{{{outer}}}#inner{{{inner}}}</style><div id=outer><div id=inner><table id=table><tr><td>aa aa aa aa aa aa aa aa</td></tr></table></div></div>");
                let document=crate::html::parse(&markup,96).unwrap();
                let table=crate::selector::query_selector(&document,document.root(),"#table").unwrap().unwrap();
                let mut session=crate::session::RenderSession::new(document);
                session.display_list(200,200,&FixedText).unwrap();
                assert_eq!(session.layout_rect(table).unwrap().height,expected,"fallback used for actual wrapping {mode}/{outer}/{inner}");
                let warm=session.display_list(200,200,&FixedText).unwrap().clone();
                assert_eq!(warm,display_list(session.document(),200,200,&FixedText).unwrap());
            }
        }
        for mode in ["vertical-rl","vertical-lr"] {
            let content="aa ".repeat(100);
            let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}#container{{height:120px}}table{{writing-mode:{mode};border-spacing:0;font:10px/3px monospace}}td{{padding:0}}</style><div id=container><table id=table><tr><td>{content}</td></tr></table></div>");
            let document=crate::html::parse(&markup,64).unwrap();
            let table=crate::selector::query_selector(&document,document.root(),"#table").unwrap().unwrap();
            let mut session=crate::session::RenderSession::new(document);
            session.display_list(100,100,&FixedText).unwrap();
            assert_eq!(session.layout_rect(table).unwrap().height,120.0,"a definite containing block is used directly, before fallback viewport caps");
        }
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}#outer{height:4px;overflow:auto}#port{max-height:10px;overflow:auto}#inner{height:auto}table{writing-mode:vertical-rl;border-spacing:0;font:10px/3px monospace}td{padding:0}</style><div id=outer><div id=port><div id=inner><table id=table><tr><td>aa aa aa aa aa aa aa aa</td></tr></table></div></div></div>",96).unwrap();
        let table=crate::selector::query_selector(&document,document.root(),"#table").unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        session.display_list(200,200,&FixedText).unwrap();
        assert_eq!(session.layout_rect(table).unwrap().height,10.0,"nearest port owns the fallback, rather than every ancestor scrollport");
    }

