    #[test]
    fn specification_vertical_caption_asymmetric_auto_margins_use_the_complete_border_box() {
        for mode in ["vertical-rl", "vertical-lr"] {
            for direction in ["ltr", "rtl"] {
                for (margins, expected_y) in [("auto 4px 7px 3px", 21.0), ("9px 4px auto 3px", 9.0)] {
                    let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{mode};direction:{direction};height:60px;width:50px;border-spacing:0;font-size:0;line-height:0}}td{{width:50px;height:60px;padding:0}}caption{{width:5px;height:20px;padding:1px 2px 5px 6px;border-style:solid;border-width:2px 3px 4px 7px;margin:{margins}}}</style><table id=table><caption id=caption></caption><tr><td></td></tr></table>");
                    let document=crate::html::parse(&markup,64).unwrap();
                    let find=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
                    let table=find("#table");let caption=find("#caption");
                    let mut session=crate::session::RenderSession::new(document);
                    session.display_list(200,200,&FixedText).unwrap();
                    // Physical border-box width is 5 + (2+6) + (3+7) = 23.
                    // Its height is 20 + (1+5) + (2+4) = 32, leaving 28px
                    // for the two inline margins; one is fixed, one is auto.
                    assert_eq!(session.layout_rect(table),Some(Rect{x:if mode=="vertical-rl"{0.0}else{30.0},y:0.0,width:50.0,height:60.0}),"grid {mode}/{direction}/{margins}");
                    assert_eq!(session.layout_rect(caption),Some(Rect{x:if mode=="vertical-rl"{53.0}else{3.0},y:expected_y,width:23.0,height:32.0}),"caption used edges {mode}/{direction}/{margins}");
                    let warm=session.display_list(200,200,&FixedText).unwrap().clone();
                    assert_eq!(warm,display_list(session.document(),200,200,&FixedText).unwrap(),"asymmetric caption retained source {mode}/{direction}/{margins}");
                    session.document_mut().set_attribute(caption,"style",if expected_y==21.0 {"margin:9px 4px auto 3px"}else{"margin:auto 4px 7px 3px"}).unwrap();
                    let changed=session.display_list(200,200,&FixedText).unwrap().clone();
                    assert_eq!(session.layout_rect(caption).unwrap().y,if expected_y==21.0 {9.0}else{21.0});
                    assert_eq!(changed,display_list(session.document(),200,200,&FixedText).unwrap(),"auto margin source mutation {mode}/{direction}");
                }
            }
        }
    }

    #[test]
    fn specification_orthogonal_table_cells_use_own_inline_percentages_and_natural_transverse_ink() {
        for (table_mode, cell_mode) in [("horizontal-tb","vertical-rl"),("horizontal-tb","vertical-lr"),("vertical-rl","horizontal-tb"),("vertical-lr","horizontal-tb")] {
            for direction in ["ltr","rtl"] {
                for align in ["top","middle","bottom"] {
                    for extra in [0.0,2.0] {
                        let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{table_mode};direction:{direction};width:80px;height:30px;border-spacing:0;font-size:0;line-height:0}}td{{writing-mode:{cell_mode};width:80px;height:30px;padding:0;vertical-align:{align}}}i{{display:block;width:8px;height:10px;padding:calc(10% + {extra}px);background:green}}</style><table id=table><tr><td id=cell><i id=ink></i></td></tr></table>");
                        let document=crate::html::parse(&markup,64).unwrap();
                        let find=|name|crate::selector::query_selector(&document,document.root(),name).unwrap().unwrap();
                        let cell=find("#cell");let ink=find("#ink");
                        let mut session=crate::session::RenderSession::new(document);
                        session.display_list(200,200,&FixedText).unwrap();
                        let cell=session.layout_rect(cell).unwrap();let ink=session.layout_rect(ink).unwrap();
                        assert_eq!((cell.width,cell.height),(80.0,30.0));
                        let cell_vertical=cell_mode!="horizontal-tb";
                        let padding=(if cell_vertical {3.0}else{8.0})+extra;
                        assert_eq!((ink.width,ink.height),(8.0+2.0*padding,10.0+2.0*padding),"percentage basis {table_mode}/{cell_mode}/{direction}/{align}/{extra}");
                        let (available,natural,coordinate,start)=if cell_vertical {(80.0,ink.width,ink.x,cell.x)}else{(30.0,ink.height,ink.y,cell.y)};
                        let free=available-natural;
                        let offset=match align {"middle"=>free*0.5,"top" if cell_vertical=>free,"bottom" if !cell_vertical=>free,_=>0.0};
                        assert_eq!(coordinate,start+offset,"real transverse content alignment {table_mode}/{cell_mode}/{direction}/{align}/{extra}");
                        let warm=session.display_list(200,200,&FixedText).unwrap().clone();
                        assert_eq!(warm,display_list(session.document(),200,200,&FixedText).unwrap());
                    }
                }
            }
        }
    }

