                let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}table{{writing-mode:{mode};direction:{direction};border-collapse:collapse;font-size:0;line-height:0}}td{{padding:0;width:20px;height:30px;box-sizing:border-box;border:solid green;border-width:2px 4px 6px 8px}}i{{display:block;width:8px;height:10px}}</style><table id=table><tr><td id=cell><i></i></td></tr></table>");
