                    let retained=session.display_list(100,100,&FixedText).unwrap().clone();
                    assert_eq!(retained,display_list(session.document(),100,100,&FixedText).unwrap(),"winning border retained replay {mode}/{direction}/{side}");
                    let table_rect=session.layout_rect(table).unwrap();
