                let document=crate::html::parse(&alloc::format!("<style>body,ul{{margin:0;padding:0}}ul{{padding-left:20px;list-style-type:square;list-style-position:{position};font-size:12px;list-style-image:{image}}}</style><ul><li>entry</li></ul>"),64).unwrap();
