    #[test]
    fn specification_table_collapse_keeps_outer_borders_with_atomic_content() {
        for (table_tag, row_tag, cell_tag) in [("table", "tr", "td"), ("x-table", "x-tr", "x-td")] {
            let markup = alloc::format!("<style>html,body{{margin:0}}{table_tag}{{display:table;border:5px solid black;border-spacing:0}}{row_tag}{{display:table-row}}{cell_tag}{{display:table-cell;padding:0}}span{{display:inline-block;vertical-align:top;margin:3px;width:100px;height:100px}}</style><{table_tag} id=table><{row_tag}><{cell_tag}><span>A</span></{cell_tag}><{cell_tag}><span></span><span></span></{cell_tag}></{row_tag}><{row_tag} id=row><{cell_tag}><span>B</span></{cell_tag}><{cell_tag}><span></span></{cell_tag}></{row_tag}></{table_tag}>");
            let document = crate::html::parse(&markup, 128).unwrap();
            let mut session = crate::session::RenderSession::new(document);
            let table = crate::selector::query_selector(session.document(), session.document().root(), "#table").unwrap().unwrap();
            let row = crate::selector::query_selector(session.document(), session.document().root(), "#row").unwrap().unwrap();
            session.display_list(800, 600, &RecordingText::default()).unwrap();
            assert_eq!(session.layout_rect(table).unwrap().height, 222.0, "{table_tag}: two 106px rows and both outer borders");
            session.document_mut().set_attribute(row, "style", "visibility:collapse").unwrap();
            let retained = session.display_list(800, 600, &RecordingText::default()).unwrap().clone();
            assert_eq!(session.layout_rect(table).unwrap().height, 116.0, "{table_tag}: projection keeps both outer borders");
            assert_eq!(retained, display_list(session.document(), 800, 600, &RecordingText::default()).unwrap());
        }
    }

