    #[test]
    fn specification_table_width_spans_use_same_length_baselines_dynamic_and_retained_geometry() {
        for reverse in [false, true] {
            let rows = [
                "<tr id=left><td colspan=2 style='width:80px'></td><td></td></tr>",
                "<tr><td></td><td colspan=2 style='width:80px'></td></tr>",
            ];
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}table{{border-spacing:0}}td{{padding:0;height:5px}}#stable{{width:40px;height:5px;background:green}}</style><div id=changed>before</div><div id=stable></div><table id=table><tr><td id=a style='width:20px'></td><td id=b style='width:20px'></td><td id=c style='width:20px'></td></tr>{}{}</table>",rows[usize::from(reverse)],rows[usize::from(!reverse)]),128).unwrap();
            let mut session = crate::session::RenderSession::new(document);
            session
                .display_list(300, 100, &RecordingText::default())
                .unwrap();
            let nodes = ["#a", "#b", "#c"].map(|selector| {
                crate::selector::query_selector(
                    session.document(),
                    session.document().root(),
                    selector,
                )
                .unwrap()
                .unwrap()
            });
            assert_eq!(
                nodes.map(|node| session.layout_rect(node).unwrap().width),
                [40.0; 3],
                "equal-span cells read their common prior baseline, reverse={reverse}"
            );
            let left = crate::selector::query_selector(
                session.document(),
                session.document().root(),
                "#left",
            )
            .unwrap()
            .unwrap();
            let cell = session.document().first_child(left).unwrap().unwrap();
            session
                .document_mut()
                .set_attribute(cell, "style", "width:100px")
                .unwrap();
            session
                .display_list(300, 100, &RecordingText::default())
                .unwrap();
            assert_eq!(
                nodes.map(|node| session.layout_rect(node).unwrap().width),
                [50.0, 50.0, 40.0],
                "dynamic span constraints recompute the same shared measures"
            );
            let changed = crate::selector::query_selector(
                session.document(),
                session.document().root(),
                "#changed",
            )
            .unwrap()
            .unwrap();
            let text = session.document().first_child(changed).unwrap().unwrap();
            session.document_mut().replace_data(text, "after").unwrap();
            let retained = session
                .display_list(300, 100, &RecordingText::default())
                .unwrap()
                .clone();
            let fresh =
                display_list(session.document(), 300, 100, &RecordingText::default()).unwrap();
            assert_eq!(
                retained, fresh,
                "retained table ownership keeps assigned measures and canonical source styles"
            );
            assert!(
                session.layout_cache_stats().hits > 0,
                "eligible ordinary sibling reuse remains available beside tables"
            );
        }
    }

    #[test]
    fn specification_table_width_math_policy_preserves_percentages_and_live_track_replay() {
        for mode in ["auto", "fixed"] {
            for column in [false, true] {
                let columns = if column { "<col id=hint><col>" } else { "" };
                let cell = if column { "" } else { "id=hint" };
                let markup = alloc::format!("<style>html,body{{margin:0}}table{{width:200px;border-collapse:collapse;table-layout:{mode}}}td{{padding:0;height:10px}}</style><table id=table>{columns}<tr><td {cell}></td><td></td></tr></table>");
                let document = crate::html::parse(&markup, 64).unwrap();
                let mut session = crate::session::RenderSession::new(document);
                let hint = crate::selector::query_selector(session.document(), session.document().root(), "#hint").unwrap().unwrap();
                let table = crate::selector::query_selector(session.document(), session.document().root(), "#table").unwrap().unwrap();
                let first = crate::selector::query_selector(session.document(), session.document().root(), "td:first-child").unwrap().unwrap();
                let second = crate::selector::query_selector(session.document(), session.document().root(), "td:last-child").unwrap().unwrap();
                for (value, expected) in [("calc(20% + 80px)", 100.0), ("40px", 40.0), ("calc(40% + 0px)", 80.0), ("calc(20% + 80px)", 100.0)] {
                    session.document_mut().set_attribute(hint, "style", &alloc::format!("width:{value}")).unwrap();
                    let retained = session.display_list(300, 100, &FixedText).unwrap().clone();
                    assert_eq!(session.layout_rect(table).unwrap().width, 200.0, "{mode}/{column}/{value}: table");
                    assert_eq!(session.layout_rect(first).unwrap().width, expected, "{mode}/{column}/{value}: first");
                    assert_eq!(session.layout_rect(second).unwrap().width, 200.0 - expected, "{mode}/{column}/{value}: second");
                    let fresh = display_list(session.document(), 300, 100, &FixedText).unwrap();
                    assert_eq!(retained, fresh, "{mode}/{column}/{value}: retained and fresh tracks");
                }
            }
        }
    }

