    #[test]
    fn specification_table_width_collapsed_border_box_constraints_use_winning_half_edges() {
        for direction in ["ltr", "rtl"] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}table{{direction:{direction};border-collapse:collapse;border:20px solid blue}}td{{box-sizing:border-box;width:50px;border:2px solid red;padding:0;height:10px}}</style><table><tr><td id=cell></td></tr></table>"),64).unwrap();
            let mut session = crate::session::RenderSession::new(document);
            session.display_list(200, 100, &FixedText).unwrap();
            let cell = crate::selector::query_selector(
                session.document(),
                session.document().root(),
                "#cell",
            )
            .unwrap()
            .unwrap();
            assert_eq!(session.layout_rect(cell).unwrap().width,50.0,"border-box constraint subtracts winning halves before adding them once, {direction}");
        }
    }
