    #[test]
    fn specification_table_missing_cells_paint_layers_without_overlapping_rowspans() {
        for collapse in [false, true] {
            for hide in [false, true] {
                let markup = alloc::format!("<style>body{{margin:0}}table{{width:60px;table-layout:fixed;border-spacing:0;border-collapse:{};empty-cells:{}}}col{{width:20px;background:green}}tr{{background:red}}td{{padding:0;height:8px}}td>i{{display:block;height:8px}}</style><table><col span=3><tr><td rowspan=2><i></i></td><td><i></i></td><td><i></i></td></tr><tr><td><i></i></td></tr></table>", if collapse { "collapse" } else { "separate" }, if hide { "hide" } else { "show" });
                let document = crate::html::parse(&markup, 64).unwrap();
                let list = display_list(&document, 100, 100, &FixedText).unwrap();
                let columns = list.0.iter().filter_map(|command| match command {
                    Command::FillRect { rect, color } if (color.r,color.g,color.b) == (0,128,0) => Some(*rect), _ => None,
                }).collect::<Vec<_>>();
                assert_eq!(columns.len(), if hide && !collapse { 4 } else { 5 }, "{collapse}/{hide}: {columns:?}");
                // The rowspan covers both rows exactly once; the uncovered
                // final column in row two receives only the missing cell.
                assert_eq!(columns.iter().filter(|rect| rect.x == 0.0).count(), 1, "{columns:?}");
                let missing = columns.iter().filter(|rect| rect.x == 40.0 && rect.y == 8.0).collect::<Vec<_>>();
                assert_eq!(missing.len(), if hide && !collapse { 0 } else { 1 }, "{columns:?}");
                if let Some(rect) = missing.first() { assert_eq!((rect.width, rect.height), (20.0, 8.0)); }
            }
        }
    }

