    #[test]
    fn specification_table_paint_layers_keep_cell_surfaces_and_borders_below_overlapping_content() {
        for collapse in ["separate","collapse"] {
            for generated in [false,true] {
                let cells=if generated {"<div id=first></div><div id=second></div>"}else{"<div id=first><i></i></div><div id=second>B</div>"};
                let pseudo=if generated {"#first,#second{display:contents}#first::before{content:'A';display:table-cell;width:40px;height:20px;background:yellow;border:4px solid blue}#second::before{content:'B';display:table-cell;width:40px;height:20px;background:lime;border:4px solid blue}"}else{"#first,#second{display:table-cell;border:4px solid blue}#first{background:yellow}#second{background:lime}#first>i{display:block;position:relative;left:38px;width:40px;height:20px;background:black}"};
                let markup=alloc::format!("<!doctype html><style>html,body{{margin:0}}#table{{display:table;width:80px;table-layout:fixed;border-spacing:0;border-collapse:{collapse};border:2px solid blue}}#first,#second{{width:40px;height:20px}}{pseudo}</style><div id=table>{cells}</div><div style='height:10px;background:red'></div>");
                let document=crate::html::parse(&markup,128).unwrap();
                let mut session=crate::session::RenderSession::new(document);
                let cached=session.display_list(200,120,&RecordingText::default()).unwrap().clone();
                let yellow=cached.0.iter().position(|command|matches!(command,Command::FillRect{color,..}if color.r==255&&color.g==255&&color.b==0)).unwrap();
                let lime=cached.0.iter().position(|command|matches!(command,Command::FillRect{color,..}if color.r==0&&color.g==255&&color.b==0)).unwrap();
                let blue_borders=cached.0.iter().enumerate().filter_map(|(index,command)|match command {
                    Command::FillRect{color,..}if color.r==0&&color.g==0&&color.b==255=>Some(index),
                    Command::StrokeBorder{color,..}if color.r==0&&color.g==0&&color.b==255=>Some(index),
                    Command::StrokeBoxBorder(border)if border.colors.iter().any(|color|color.r==0&&color.g==0&&color.b==255)=>Some(index),_=>None}).collect::<Vec<_>>();
                assert!(!blue_borders.is_empty());
                assert!(blue_borders.iter().all(|index|*index>yellow&&*index>lime),"{collapse} all table borders follow all cell backgrounds");
                let ink=cached.0.iter().position(|command|if generated {matches!(command,Command::GlyphRun{glyphs,..}if glyphs.iter().any(|glyph|glyph.id==u16::from(b'A')))}else{matches!(command,Command::FillRect{color,..}if *color==Rgba{r:0,g:0,b:0,a:255})}).unwrap();
                assert!(blue_borders.iter().all(|index|*index<ink),"{collapse} borders precede real cell content, including pseudo text");
                assert_eq!(cached,display_list(session.document(),200,120,&RecordingText::default()).unwrap());
                let table=crate::selector::query_selector(session.document(),session.document().root(),"#table").unwrap().unwrap();
                session.document_mut().set_attribute(table,"style","border-color:red").unwrap();
                let changed=session.display_list(200,120,&RecordingText::default()).unwrap().clone();
                assert_eq!(changed,display_list(session.document(),200,120,&RecordingText::default()).unwrap());
                session.set_canvas_background(None);
                let replay=session.display_list(200,120,&RecordingText::default()).unwrap().clone();
                let rules=stylesheets(session.document()).unwrap();
                let fresh=display_list_with_retained_layout_and_root(session.document(),200,120,&RecordingText::default(),&rules,None,None,&[],&RefCell::new(css::StyleCache::default()),None,None,None).unwrap();
                assert_eq!(replay,fresh,"surface-stage identity survives actual retained/fresh rendering");
            }
        }
    }

    #[test]
    fn specification_table_generated_cell_dynamic_inheritance_and_replay_preserve_source_identity() {
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}#host{display:table;border-spacing:0}#origin{display:contents;color:teal;border:3px solid blue}#origin::before{content:'A';display:table-cell;width:24px;height:20px;border:inherit}#cell{display:table-cell;width:24px;height:20px}#stable{width:20px;height:10px;background:green}</style><div id=host><div id=origin colspan=99><div id=cell>B</div></div></div><div id=stable></div>",128).unwrap();
        let mut session=crate::session::RenderSession::new(document);let origin=crate::selector::query_selector(session.document(),session.document().root(),"#origin").unwrap().unwrap();
        session.display_list(400,200,&RecordingText::default()).unwrap();
        for style in ["display:contents;color:red;border:5px solid lime","display:none","display:contents;color:teal;border:3px solid blue"] {
            session.document_mut().set_attribute(origin,"style",style).unwrap();
            let cached=session.display_list(400,200,&RecordingText::default()).unwrap().clone();
            let fresh=display_list(session.document(),400,200,&RecordingText::default()).unwrap();assert_eq!(cached,fresh,"dynamic generated sources stay canonical on replay");
            let count=cached.0.iter().flat_map(|command|match command {Command::GlyphRun{glyphs,..}=>glyphs.as_ref(),_=>&[]}).filter(|glyph|glyph.id==u16::from(b'A')).count();assert_eq!(count,usize::from(style!="display:none"));
            if style!="display:none" {
                let rect=session.pseudo_layout_rect(origin,css::PseudoElement::Before).unwrap();
                assert_eq!(rect.width,if style.contains("5px") {34.0}else{30.0},"raw origin colspan does not span a generated cell");
            }
        }
        // Generated rules conservatively prevent local mutation reuse. A
        // genuine canvas-only paint invalidation leaves styles and positions
        // unchanged and must replay the eligible ordinary sibling.
        for canvas in [None, Some(Rgba { r: 12, g: 34, b: 56, a: 255 }), None] {
            let revision=session.paint_revision();
            session.set_canvas_background(canvas);
            assert_ne!(session.paint_revision(),revision,"canvas changes invalidate the full painted list");
            let replay=session.display_list(400,200,&RecordingText::default()).unwrap().clone();
            let rules=stylesheets(session.document()).unwrap();
            let fresh=display_list_with_retained_layout_and_root(session.document(),400,200,&RecordingText::default(),
                &rules,None,None,&[],&RefCell::new(css::StyleCache::default()),None,None,canvas).unwrap();
            assert_eq!(replay,fresh,"fresh and retained rendering use the same host canvas");
            assert!(session.layout_cache_stats().hits>0,"eligible ordinary sibling replay is retained across canvas-only changes");
        }

    }

    #[test]
    fn specification_table_replaced_used_roles_precede_wrappers_without_changing_computed_display() {
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}#host{display:table;border-spacing:0}#row{display:table-row}img,#cell{display:table-cell;padding:0}#cell{width:20px;height:20px}</style><div id=host><div id=row><img id=image src='sample' alt='A'> <div id=cell>B</div></div></div>",96).unwrap();
        let host=crate::selector::query_selector(&document,document.root(),"#host").unwrap().unwrap();
        let image_node=crate::selector::query_selector(&document,document.root(),"#image").unwrap().unwrap();
        let image=Arc::new(ImageData{width:8,height:6,pixels:alloc::vec![255;8*6*4]});
        for ready in [false,true] {
            let images=|_:&str|if ready {ImageState::Ready(image.clone())}else{ImageState::Failed};
            let rules=stylesheets(&document).unwrap();let cache=RefCell::new(css::StyleCache::default());let uses=core::cell::Cell::new(0);let text=FixedText;
            let layout=Layout::new(&document,&text,&uses,&rules,Some(&images),Rect{x:0.0,y:0.0,width:300.0,height:100.0},None,&[],&cache,None);
            let style=layout.computed_style_from_tree(host).unwrap();
            let mut rows=Vec::new();let mut cells=Vec::new();let mut children=Vec::new();let mut groups=Vec::new();
            layout.table_rows(host,&style,&mut rows,&mut cells,&mut children,&mut groups,300.0,0,None).unwrap();
            assert_eq!(rows.len(),1);assert_eq!(cells.len(),2);
            assert_eq!(matches!(&cells[0],TableCellContent::Anonymous{..}),ready,"ready replacement is used inline before anonymous cells");
            assert_eq!(matches!(&cells[0],TableCellContent::Node{node,..} if *node==image_node),!ready,"non-replaced alternative text retains its table-cell role");
            assert_eq!(layout.computed_style_from_tree(image_node).unwrap().display,Display::TableCell,"layout projection never changes CSSOM computed display");
            let mut geometry=LayoutGeometry::default();
            display_list_with_styles(&document,300,100,&text,&rules,Some(&images),Some(&mut geometry),&[]).unwrap();
            assert!(geometry.hits.iter().any(|hit|hit.node==image_node&&!hit.virtual_generated&&hit.rect.width==if ready {8.0}else{2.0}),"actual replacement status selects the genuine intrinsic formatter");
        }
    }

    #[test]
    fn specification_box_nonuniform_borders_paint_before_descendants_without_shifting_geometry() {
        // CSS2 Appendix E: the child's top border covers the coincident parent
        // bottom border. Different side widths do not change painting order.
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}#host{width:20px;height:101px;border-bottom:5px solid red}#first{border-bottom:5px solid black;margin-bottom:96px}#last{border-top:5px solid black}</style><div id=host><div id=first></div><div id=last></div></div>",64).unwrap();
        let list=display_list(&document,100,150,&NoShape).unwrap();
        let mut red=None;let mut black=Vec::new();
        for (index,command) in list.0.iter().enumerate() {
            if let Command::FillRect{rect,color}=command {
                if (color.r,color.g,color.b,color.a)==(255,0,0,255){red=Some((index,*rect));}
                if (color.r,color.g,color.b,color.a)==(0,0,0,255){black.push((index,*rect));}
            }
        }
        let red=red.unwrap();assert_eq!(black.len(),2);
        assert_eq!((red.1.x,red.1.y,red.1.width,red.1.height),(0.0,101.0,20.0,5.0));
        assert_eq!((black[0].1.y,black[1].1.y),(0.0,101.0));
        assert!(black.iter().all(|(index,_)|*index>red.0),"parent border belongs before both child borders, including an overlapping border");
        // Patterned/rounded borders use one immutable carrier. Replacing its
        // final geometry must keep the same order and retained command ranges.
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}#host{width:20px;height:10px;border-top:2px solid lime;border-bottom:5px solid red;border-radius:2px}#child{width:20px;height:15px;background:black}</style><div id=host><div id=child></div></div>",64).unwrap();
        let host=crate::selector::query_selector(&document,document.root(),"#host").unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        for height in [10,20,10] {
            session.document_mut().set_attribute(host,"style",&alloc::format!("height:{height}px")).unwrap();
            let cached=session.display_list(100,150,&NoShape).unwrap().clone();
            let fresh=display_list(session.document(),100,150,&NoShape).unwrap();assert_eq!(cached,fresh);
            let border=cached.0.iter().enumerate().find_map(|(index,command)|if let Command::StrokeBoxBorder(value)=command {Some((index,value.rect))}else{None}).unwrap();
            let child=cached.0.iter().enumerate().find_map(|(index,command)|match command {Command::FillRect{rect,color} if (color.r,color.g,color.b,color.a)==(0,0,0,255)=>Some((index,*rect)),_=>None}).unwrap();
            assert_eq!(border.1.height,height as f32+7.0);assert_eq!(child.1.y,2.0);assert!(border.0<child.0);
        }
    }

    #[test]
    fn specification_table_contents_wrapper_uses_cached_principal_inline_parent_and_real_inheritance() {
        let mut document=crate::html::parse("<!doctype html><style>html,body{margin:0}#principal{display:inline;color:red}#contents{display:contents;color:teal}#nested{display:contents}.cell{display:table-cell;width:20px;height:20px;padding:0;border-spacing:0}</style><span id=principal><span id=contents><span id=nested><span class=cell>A</span><span class=cell>B</span></span></span></span>",128).unwrap();
        let principal=crate::selector::query_selector(&document,document.root(),"#principal").unwrap().unwrap();let contents=crate::selector::query_selector(&document,document.root(),"#nested").unwrap().unwrap();
        for display in ["inline","block","inline"] {
            document.set_attribute(principal,"style",&alloc::format!("display:{display};color:red")).unwrap();
            let rules=stylesheets(&document).unwrap();let cache=RefCell::new(css::StyleCache::default());let uses=core::cell::Cell::new(0);let text=FixedText;
            let layout=Layout::new(&document,&text,&uses,&rules,None,Rect{x:0.0,y:0.0,width:100.0,height:80.0},None,&[],&cache,None);
            let style=layout.computed_style_from_tree(contents).unwrap();assert_eq!((style.color.r,style.color.g,style.color.b),(0,128,128));
            let children=layout.flow_box_children(contents,&style,100.0,0).unwrap();assert_eq!(children.len(),1);
            let FlattenedBoxChildKind::AnonymousTable(table)=&children[0].kind else {panic!("proper cells need a real anonymous table parent")};
            assert_eq!(table.style.display,if display=="inline"{Display::InlineTable}else{Display::Table});
            assert_eq!((table.style.color.r,table.style.color.g,table.style.color.b),(0,128,128),"anonymous inheritance still comes from the contents origin, not the principal parent");
            assert_eq!(layout.anonymous_table_intrinsic(table,1,false).unwrap(),(40.0,20.0));
        }
    }

    #[test]
    fn table_cell_measurement_uses_real_box_flow_without_retaining_glyph_payloads() {
        for content in [
            "abc def ghi jkl",
            "<span style='font-size:12px'>abc def</span> <b>ghi jkl</b>",
            "<div style='white-space:pre-wrap'>abc def\nghi\tjkl</div>",
            "<div style='float:left;width:12px;height:30px'></div>abc def ghi jkl",
            "<div style='height:8px'></div><p style='margin:3px 0'>abc def</p>",
            "<span style='display:inline-block;width:12px;height:22px'></span>abc def",
        ] {
            let markup = alloc::format!("<style>html,body{{margin:0}}main{{display:flow-root;width:36px;padding:2px;border:1px solid black}}main::before{{content:'prefix ';counter-increment:item}}body{{counter-reset:item}}</style><main>{content}</main>");
            let document = crate::html::parse(&markup, 128).unwrap();
            let rules = stylesheets(&document).unwrap();
            let text = RecordingText::default();
            let main = crate::selector::query_selector(&document, document.root(), "main").unwrap().unwrap();
            let html = crate::selector::query_selector(&document, document.root(), "html").unwrap().unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document, 120, 200, &text, &rules, None,
                Some(&mut geometry), &[]).unwrap();
            let rect = geometry.hits.iter().find(|hit| hit.node == main).unwrap().rect;
            let styles = core::cell::RefCell::new(css::StyleCache::default());
            let uses = core::cell::Cell::new(0);
            let mut layout = Layout::new(&document, &text, &uses, &rules, None,
                Rect { x: 0.0, y: 0.0, width: 120.0, height: 200.0 }, None, &[], &styles, None);
            layout.prepare_quote_positions(html).unwrap();
            layout.prepare_counter_positions(html).unwrap();
            let style = layout.computed_style_from_tree(main).unwrap();
            let (measured, _) = layout.measure_table_cell_height(&TableCellContent::Node { node: main, style: style.clone() },
                &[], &style, rect.width, 0).unwrap();
            assert!((measured - rect.height).abs() < 0.001,
                "real used-width formatter measurement for {content:?}: {measured} != {rect:?}");
            let mut scratch = layout.measurement_layout();
            scratch.box_for(main, &style, Some(style.clone()), 0.0, 0.0, 120.0, 0).unwrap();
            assert!(scratch.commands.iter().all(|command| !matches!(command,
                Command::GlyphRun { glyphs, .. } if !glyphs.is_empty())));
            assert!(scratch.geometry.is_none());
        }
    }

    #[test]
    fn specification_svg_geometry_shares_actual_command_budget_and_optional_metrics() {
        let mut operation=SvgGeometryOperation::new(MAX_DISPLAY_LIST_BYTES-128,0,0,0).unwrap();
        assert!(operation.arena.path_data("M0 0 C80 90 -40 90 40 0",Some(5.0)).is_err(),"command-owned bytes leave only the actual remaining path budget");
        let mut operation=SvgGeometryOperation::new(0,0,0,0).unwrap();
        let source=operation.arena.path_data("M0 0 L1 1",None).unwrap().unwrap();
        assert!(operation.arena.bounds(source).is_some());
        assert!(operation.charge_commands(MAX_DISPLAY_LIST_BYTES,0,0).is_err(),"live source geometry and commands cannot each admit a separate full ceiling");
        for transform in ["none","translateX(2px)"] {
            let document=crate::html::parse(&alloc::format!("<svg width=100 height=100><g><text x=10 y=30 style='transform-box:view-box;transform:{transform}'>X</text></g></svg>"),32).unwrap();
            let rules=stylesheets(&document).unwrap();
            let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,120,120,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{glyphs,..} if !glyphs.is_empty())),"optional missing glyph cells cannot reject otherwise paintable SVG text");
        }
    }

    #[test]
    fn specification_svg_gradient_transform_alias_uses_author_cascade_and_template() {
        for (declaration,expected) in [("",0.5),("transform:none",0.0),("transform:translateX(0.25px)",0.25),("transform:revert",0.0)] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#g{{{declaration}}}</style><svg width=100 height=100><defs><linearGradient id=base gradientTransform='translate(.5)'><stop stop-color=red /><stop offset=1 stop-color=blue /></linearGradient><linearGradient id=g href='#base' /></defs><rect width=100 height=100 fill='url(#g)' /></svg>"),64).unwrap();
            let list=display_list(&document,120,120,&RecordingText::default()).unwrap();
            assert!(list.0.iter().any(|command|matches!(command,Command::SvgPath{fill:Some(crate::paint::SvgPaint::Gradient(gradient)),..} if gradient.transform.e==expected)),"{declaration}: gradient presentation/template enters first author stylesheet and CSS overrides it");
        }
    }

    #[test]
    fn specification_transform_box_css_svg_reference_drives_paint_hit_and_mutation() {
        for (keyword,svg_width,translation) in [("content-box",40.0,20.0),("fill-box",40.0,20.0),
            ("border-box",50.0,25.0),("stroke-box",50.0,25.0),("view-box",200.0,100.0)] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}svg{{display:block}}#shape{{transform-box:{keyword};transform-origin:0 0;transform:translateX(50%)}}</style><svg width=200 height=120 viewBox='0 0 200 120'><rect id=shape x=20 y=30 width=40 height=50 fill=green stroke=blue stroke-width=10 /></svg>"),64).unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let shape=crate::selector::query_selector(session.document(),session.document().root(),"#shape").unwrap().unwrap();
            for width in [40.0,80.0] {
                if width==80.0 {session.document_mut().set_attribute(shape,"width","80").unwrap();}
                let list=session.display_list(300,150,&RecordingText::default()).unwrap().clone();
                let reference=session.layout_transform_reference_box(shape,None).unwrap();
                assert!(reference.1);
                let expected_width=if keyword=="view-box" {svg_width}else{svg_width+width-40.0};
                assert_eq!(reference.0.width,expected_width,"{keyword}: actual fill/stroke/viewport authority");
                let expected=if keyword=="view-box" {translation}else{translation+(width-40.0)/2.0};
                assert!(list.0.iter().any(|command|matches!(command,Command::SvgPath{transform,..} if transform.e==expected)),"{keyword}: the actual shape carries its used reference matrix");
                assert_eq!(session.hit_test(20.0+expected+width/2.0,55.0),Some(shape),"SVG hit ownership uses the painted local matrix");
                assert_eq!(session.display_list(300,150,&RecordingText::default()).unwrap(),&list);
                assert_eq!(display_list(session.document(),300,150,&RecordingText::default()).unwrap(),list);
            }
        }
        for (keyword,expected) in [("content-box",35.0),("fill-box",35.0),("border-box",50.0),("stroke-box",50.0),("view-box",50.0)] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}#box{{width:70px;height:50px;padding:10px;border:5px solid;background:green;transform-origin:0 0;transform-box:{keyword};transform:translateX(50%)}}</style><div id=box></div>"),32).unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let node=crate::selector::query_selector(session.document(),session.document().root(),"#box").unwrap().unwrap();
            let list=session.display_list(200,150,&RecordingText::default()).unwrap();
            assert!(list.0.iter().any(|command|matches!(command,Command::PushTransform(matrix) if matrix.e==expected)),"{keyword}: CSS layout aliases select actual content/border geometry");
            assert_eq!(session.hit_test(expected+50.0,40.0),Some(node));
        }
    }

    #[test]
    fn specification_transform_table_wrapper_keeps_caption_geometry_sparse_and_current() {
        for transform in ["none","scale(2)"] {
        for keyword in ["content-box","border-box","fill-box","stroke-box","view-box"] {
            let document=crate::html::parse(&alloc::format!("<style>html,body{{margin:0}}table{{width:80px;table-layout:fixed;border-spacing:0}}td{{height:20px;padding:0}}caption{{font-size:0;line-height:0}}#table{{margin-top:7px;margin-left:11px;transform-box:{keyword};transform:{transform}}}#top{{height:10px}}#bottom{{height:15px;caption-side:bottom}}</style><table id=table><caption id=top></caption><caption id=bottom></caption><tr><td></td></tr></table><table id=plain><tr><td></td></tr></table>"),96).unwrap();
            let mut session=crate::session::RenderSession::new(document);
            let table=crate::selector::query_selector(session.document(),session.document().root(),"#table").unwrap().unwrap();
            let plain=crate::selector::query_selector(session.document(),session.document().root(),"#plain").unwrap().unwrap();
            let top=crate::selector::query_selector(session.document(),session.document().root(),"#top").unwrap().unwrap();
            for caption_height in [10.0,30.0] {
                if caption_height==30.0 {session.document_mut().set_attribute(top,"style","height:30px").unwrap();}
                let list=session.display_list(200,150,&RecordingText::default()).unwrap().clone();
                let wrapper=Rect{x:11.0,y:7.0,width:80.0,height:caption_height+35.0};
                assert_eq!(session.layout_transform_reference_box(table,None),Some((wrapper,false)),"{keyword}: initial percentage origins still need the actual wrapper with transform:none");
                assert_eq!(session.layout_rect(table).unwrap(),Rect{x:11.0,y:7.0+caption_height,width:80.0,height:20.0},"ordinary CSSOM box geometry remains the grid");
                assert_eq!(session.computed_style(table).unwrap().css_transform_reference_box(wrapper),wrapper);
                if transform!="none" {
                    let matrix=Affine{a:2.0,b:0.0,c:0.0,d:2.0,e:-51.0,f:-(wrapper.y+wrapper.height/2.0)};
                    assert!(list.0.iter().any(|command|matches!(command,Command::PushTransform(value) if *value==matrix)),"actual table paint uses the caption-inclusive origin: {keyword}");
                    let point=matrix.apply(50.0,7.0+caption_height+10.0);
                    let mut saw_table=false;
                    session.for_each_hit_test(point.0,point.1,|node|{saw_table|=node==table;true});
                    assert!(saw_table,"table hit geometry follows the same wrapper transform");
                }

                assert_eq!(session.layout_transform_reference_box(plain,None),None,"no per-table carrier for unchanged grid geometry");
                assert_eq!(session.layout_rect(plain).unwrap().y,wrapper.y+wrapper.height);
                assert_eq!(session.display_list(200,150,&RecordingText::default()).unwrap(),&list);
                assert_eq!(display_list(session.document(),200,150,&RecordingText::default()).unwrap(),list);
            }
        }
        }
    }

    #[test]
    fn table_captions_keep_own_side_box_metrics_and_wrapper_flow() {
        let document = crate::html::parse(
            "<style>html,body{margin:0}#table{display:table;width:100px;table-layout:fixed;border-spacing:0;caption-side:bottom}.caption{display:table-caption}#top{caption-side:top;height:20px;background:blue}#bottom{height:10px;width:50px;padding:1px;border:1px solid black;margin:4px 2px;background:red}#another{height:7px;background:yellow}#row{display:table-row}#cell{display:table-cell;height:5px;padding:0;background:green}#next{height:3px;background:black}</style><div id=table><div id=bottom class=caption></div><div id=top class=caption></div><div style='display:contents'><div id=another class=caption></div></div><div id=row><div id=cell></div></div></div><div id=next></div>",
            128,
        ).unwrap();
        let list = display_list(&document, 200, 200, &FixedText).unwrap();
        let rect = |rgb| list.0.iter().find_map(|command| match command {
            Command::FillRect {rect,color} if (color.r,color.g,color.b)==rgb => Some(*rect),
            _=>None,
        }).unwrap();
        assert_eq!(rect((0,0,255)), Rect {x:0.0,y:0.0,width:100.0,height:20.0});
        assert_eq!(rect((0,128,0)), Rect {x:0.0,y:20.0,width:100.0,height:5.0});
        assert_eq!(rect((255,0,0)), Rect {x:2.0,y:29.0,width:54.0,height:14.0});
        assert_eq!(rect((255,255,0)), Rect {x:0.0,y:47.0,width:100.0,height:7.0});
        let next = crate::selector::query_selector(&document,document.root(),"#next").unwrap().unwrap();
        let mut geometry = LayoutGeometry::default();
        let rules = stylesheets(&document).unwrap();
        display_list_with_styles(&document,200,200,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
        assert!(geometry.hits.iter().any(|hit| hit.node == next && hit.rect.y == 54.0));

        let document = crate::html::parse(
            "<style>html,body{margin:0}table{border-spacing:0;border-bottom:4px solid green}caption{width:100px;height:10px}</style><table><caption></caption></table>", 64,
        ).unwrap();
        let list = display_list(&document, 200, 100, &FixedText).unwrap();
        assert!(list.0.iter().any(|command| matches!(command,
            Command::FillRect {rect,color} if color.r == 0 && color.g == 128 && color.b == 0
                && rect.width == 100.0 && rect.height == 4.0)),
            "a definite caption minimum width must size the automatic table grid");
    }

    #[test]
    fn specification_table_separated_relative_spacing_preserves_contiguous_group_geometry() {
        let document = crate::xml::parse("<html xmlns='http://www.w3.org/1999/xhtml'><head><style><![CDATA[html,body{margin:0}body{font-size:16px}table{border-spacing:0em 3em;background:red}td{padding:0;width:600px;height:2em;background:white}]]></style></head><body><table id='t'><thead><tr><td id='a'></td></tr></thead><tbody><tr><td id='b'></td></tr></tbody></table></body></html>", 64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(&document,800,600,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
        for (name, expected) in [("t", Rect{x:0.0,y:0.0,width:600.0,height:208.0}),
            ("a", Rect{x:0.0,y:48.0,width:600.0,height:32.0}),
            ("b", Rect{x:0.0,y:128.0,width:600.0,height:32.0})] {
            let node = crate::selector::get_element_by_id(&document,document.root(),name).unwrap().unwrap();
            assert!(geometry.hits.iter().any(|hit| hit.node == node && hit.rect == expected), "{name} requires one spacing gap between contiguous groups");
        }
    }

