    #[test]
    fn specification_table_sizing_interpolates_adjacent_guesses_without_expanding_definite_cells() {
        // FixedText advances each byte by two pixels: both words have MCW=8,
        // and their unwrapped max-content width is 26. A definite first column
        // must wrap its three words instead of claiming that unwrapped width.
        for (table_width, first_width) in [(20.0,12.0),(30.0,12.0),(40.0,12.0)] {
            let document = crate::html::parse(&alloc::format!(
                "<!doctype html><style>html,body{{margin:0}}table{{width:{table_width}px;border-collapse:collapse}}td{{padding:0}}</style><table><tr><td id=a style='width:12px'>word word word</td><td id=b>word word word</td></tr></table>"),64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document,800,600,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
            for (name,width) in [("a",first_width),("b",table_width-first_width)] {
                let node = crate::selector::get_element_by_id(&document,document.root(),name).unwrap().unwrap();
                assert!(geometry.hits.iter().any(|hit|hit.node==node && (hit.rect.width-width).abs()<0.01),"table {table_width}: {name}");
            }
        }
    }

    #[test]
    fn specification_replaced_dimensions_use_cascade_natural_ratios_and_constraint_transfers() {
        let image = Arc::new(ImageData { width:200,height:100,pixels:alloc::vec![255;200*100*4] });
        let images = |_: &str| ImageState::Ready(image.clone());
        for (css, expected) in [
            ("width:auto;height:auto", (200.0,100.0)),
            ("width:100px;height:auto;aspect-ratio:1", (100.0,100.0)),
            ("width:100px;height:auto;aspect-ratio:auto 1", (100.0,50.0)),
            ("width:auto;height:auto;max-width:50px", (50.0,25.0)),
            ("width:100px;height:auto;box-sizing:border-box;border:5px solid green;aspect-ratio:1", (100.0,100.0)),
        ] {
            let document = crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}img{{display:block}}</style><img id=i src=pixel.png width=160 height=80 style='{css}'>"),64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document,800,600,&FixedText,&rules,Some(&images),Some(&mut geometry),&[]).unwrap();
            let node = crate::selector::get_element_by_id(&document,document.root(),"i").unwrap().unwrap();
            assert!(geometry.hits.iter().any(|hit| hit.node == node && (hit.rect.width,hit.rect.height) == expected), "{css}: actual replaced box");
        }
        for (markup, expected) in [("<canvas id=i width=40 height=20 style='width:20px;height:auto'></canvas>",(20.0,10.0)),
            ("<video id=i>fallback must not render</video>",(300.0,150.0))] {
            let document = crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}canvas,video{{display:block}}</style>{markup}"),64).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            let list = display_list_with_styles(&document,800,600,&FixedText,&rules,None,Some(&mut geometry),&[]).unwrap();
            let node = crate::selector::get_element_by_id(&document,document.root(),"i").unwrap().unwrap();
            assert!(geometry.hits.iter().any(|hit| hit.node == node && (hit.rect.width,hit.rect.height) == expected), "{markup}");
            assert!(!list.0.iter().any(|command| matches!(command, Command::GlyphRun {..})), "replaced fallback children stay suppressed");
        }
    }

