    #[test]
    fn container_units_follow_consuming_axes_and_preserve_exact_pixel_values() {
        for (container_mode, element_mode, expected) in [
            ("horizontal-tb", "horizontal-tb", (30.0, 40.0)),
            ("horizontal-tb", "vertical-rl", (40.0, 30.0)),
            ("vertical-rl", "horizontal-tb", (50.0, 20.0)),
            ("vertical-rl", "vertical-rl", (20.0, 50.0)),
        ] {
            let source = alloc::format!("<style>body{{margin:0}}#outer{{container-type:size;width:500px;height:400px}}#inner{{container-type:inline-size;width:300px;height:200px;writing-mode:{container_mode}}}#target{{width:10cqi;height:10cqb;writing-mode:{element_mode}}}</style><div id=outer><div id=inner><div id=target></div></div></div>");
            let document = crate::html::parse(&source, 128).unwrap();
            let rules = stylesheets(&document).unwrap();
            let mut geometry = LayoutGeometry::default();
            display_list_with_styles(&document, 800, 600, &FixedText, &rules, None, Some(&mut geometry), &[]).unwrap();
            let node = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
            let hit = geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap();
            assert_eq!((hit.rect.width, hit.rect.height), expected, "container {container_mode}, element {element_mode}");
        }
        let document = crate::html::parse("<style>body{margin:0}#container{container-type:size;width:30px;height:30px}#target{width:50cqw;height:50cqh}</style><div id=container><div id=target></div></div>", 64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(&document, 100, 100, &FixedText, &rules, None, Some(&mut geometry), &[]).unwrap();
        let node = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
        let hit = geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap();
        assert_eq!((hit.rect.width, hit.rect.height), (15.0, 15.0));
        let document = crate::html::parse("<style>body{margin:0}#target{writing-mode:vertical-rl;width:10cqi;height:10cqb}</style><div id=target></div>", 64).unwrap();
        let mut rules = stylesheets(&document).unwrap();
        rules.environment = css::MediaEnvironment { width:100.0, height:200.0, ..rules.environment };
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(&document, 100, 200, &FixedText, &rules, None, Some(&mut geometry), &[]).unwrap();
        let node = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
        let hit = geometry.hits.iter().find(|hit| hit.node == node && !hit.virtual_generated).unwrap();
        assert_eq!((hit.rect.width, hit.rect.height), (20.0, 10.0), "small-viewport fallback uses the consuming axes");
    }

    #[test]
    fn empty_inline_lines_and_generated_spaces_share_normal_flow_geometry() {
        fn ink(markup: &str) -> Vec<(u16, f32, f32)> {
            let document = crate::html::parse(markup, 128).unwrap();
            let list = display_list(&document, 320, 200, &RecordingText::default()).unwrap();
            let mut result = Vec::new();
            for command in list.0 {
                if let Command::GlyphRun { origin_x, baseline_y, glyphs, .. } = command {
                    result.extend(glyphs.iter().filter(|glyph| glyph.id != u16::from(b' '))
                        .map(|glyph| (glyph.id, origin_x + glyph.x, baseline_y + glyph.y)));
                }
            }
            result
        }
        let prefix = "<style>body{margin:0}p{margin:0}</style>";
        assert_eq!(
            ink(&alloc::format!("{prefix}<span></span> <span></span>\n<p>next</p>")),
            ink(&alloc::format!("{prefix}<p>next</p>")),
            "empty undecorated spans must not insert a line or interrupt margins"
        );
        assert_ne!(
            ink(&alloc::format!("{prefix}<span style='padding:1px'></span><p>next</p>")),
            ink(&alloc::format!("{prefix}<p>next</p>")),
            "nonzero inline decoration keeps its line"
        );
        assert_eq!(
            ink("<style>body{margin:0}</style><p><span></span> <span></span></p><p>next</p>"),
            ink("<style>body{margin:0}</style><p>next</p>"),
            "empty line boxes keep the adjoining margin collapse chain"
        );
        assert_eq!(
            ink("<style>body{margin:0}.item{contain:style;counter-increment:n;margin-left:40px}.item::before{content:'[' counter(n) '] '}</style><div class=item>\n A1\n <div class=item>B1</div><div class=item>B2</div></div><div class=item>A2</div>"),
            ink("<style>body{margin:0}.item{margin-left:40px}</style><div class=item>[1] A1<div class=item>[1] B1</div><div class=item>[2] B2</div></div><div class=item>[2] A2</div>"),
            "generated text and adjacent authored whitespace collapse in one inline flow"
        );
        assert_eq!(
            ink("<style>body{margin:0}p{margin:0}p::before{content:'A\\A   B';white-space:pre-line}</style><p></p>"),
            ink("<style>body{margin:0}p{margin:0}</style><p>A<br>B</p>"),
            "a generated inline uses its own white-space processing policy"
        );
        assert_eq!(
            ink("<style>body{margin:0}p{margin:0}</style><p>A<span style='white-space:pre'>  B  </span>C</p>"),
            ink("<style>body{margin:0}p{margin:0;white-space:pre}</style><p>A  B  C</p>"),
            "preserved spaces in a descendant inline keep their advance"
        );
    }

    #[test]
    fn style_containment_scopes_counter_mutations_and_quote_depth_without_map_copies() {
        for containment in ["contain:style", "container-type:inline-size", "container-type:size"] {
            let source = alloc::format!(
                "<style>#root{{counter-reset:n 5}}.show::before{{content:counters(n,'.') '|'}}#scope{{width:100px;height:80px;{containment}}}#inside{{counter-increment:n 2}}#scope::after{{content:counters(n,'.') '|'}}#last{{counter-increment:n}}</style><div id=root><div class=show></div><section id=scope class=show><div id=inside class=show></div></section><div id=last class=show></div></div>"
            );
            let shaped = painted_text_runs(&source);
            assert_eq!(shaped.concat(), "5|5|5.2|5.2|6|", "{containment}: {shaped:?}");
            let source = alloc::format!(
                "<style>body{{quotes:'<' '>' '[' ']'}}#root::before{{content:open-quote}}#root::after{{content:close-quote}}#scope{{width:100px;height:80px;{containment}}}#scope::before{{content:open-quote}}#last::before{{content:open-quote}}#last::after{{content:close-quote}}</style><div id=root><section id=scope></section><div id=last></div></div>"
            );
            assert_eq!(painted_text_runs(&source).concat(), "<[[]>", "{containment}");
        }
        let shaped = painted_text_runs(
            "<style>#root{counter-reset:n 5}#scope{display:contents;contain:style}#inside{counter-increment:n 2}#last::before{content:counter(n)}</style><div id=root><section id=scope><div id=inside></div></section><div id=last></div></div>"
        );
        assert_eq!(shaped.concat(), "7", "display:contents has no principal containment box");
    }

