    #[test]
    fn vertical_floats_use_line_edges_wrap_columns_and_clear_in_block_direction() {
        for (mode, first, next, cleared) in [
            ("vertical-lr", 0.0, 20.0, 40.0),
            ("vertical-rl", 80.0, 60.0, 50.0),
        ] {
            let markup = alloc::format!(
                "<main style='writing-mode:{mode};width:100px;height:100px'>\n                 <i id=a style='float:left;width:20px;height:30px'></i>\n                 <i id=b style='float:left;width:20px;height:30px'></i>\n                 <i id=c style='float:left;width:20px;height:30px'></i>\n                 <i id=d style='float:left;width:20px;height:30px'></i>\n                 <div id=e style='clear:left;width:10px;height:10px'></div></main>"
            );
            let (document, geometry) = intrinsic_keyword_geometry(&markup);
            for (selector, x, y, width, height) in [
                ("#a", first, 0.0, 20.0, 30.0),
                ("#b", first, 30.0, 20.0, 30.0),
                ("#c", first, 60.0, 20.0, 30.0),
                ("#d", next, 0.0, 20.0, 30.0),
                ("#e", cleared, 0.0, 10.0, 10.0),
            ] {
                let rect = intrinsic_keyword_rect(&document, &geometry, selector);
                assert_eq!(
                    (rect.x, rect.y, rect.width, rect.height),
                    (x, y, width, height),
                    "{mode} {selector}"
                );
            }
            let markup = alloc::format!(
                "<main style='writing-mode:{mode};width:100px;height:100px'>\n                 <i id=a style='float:right;width:20px;height:30px'></i>\n                 <i id=b style='float:right;width:20px;height:30px'></i></main>"
            );
            let (document, geometry) = intrinsic_keyword_geometry(&markup);
            for (selector, y) in [("#a", 70.0), ("#b", 40.0)] {
                let rect = intrinsic_keyword_rect(&document, &geometry, selector);
                assert_eq!((rect.x, rect.y), (first, y), "{mode} line-right {selector}");
            }
        }
        let (document, geometry) = intrinsic_keyword_geometry(
            "<main style='width:100px;height:100px'>\n             <i id=a style='float:left;width:30px;height:20px'></i>\n             <i id=b style='float:left;width:30px;height:20px'></i>\n             <i id=c style='float:left;width:30px;height:20px'></i>\n             <i id=d style='float:left;width:30px;height:20px'></i>\n             <div id=e style='clear:both;width:10px;height:10px'></div></main>",
        );
        for (selector, x, y) in [
            ("#a", 0.0, 0.0),
            ("#b", 30.0, 0.0),
            ("#c", 60.0, 0.0),
            ("#d", 0.0, 20.0),
            ("#e", 0.0, 40.0),
        ] {
            let rect = intrinsic_keyword_rect(&document, &geometry, selector);
            assert_eq!((rect.x, rect.y), (x, y), "horizontal control {selector}");
        }
    }

    #[test]
    fn vertical_float_formatting_context_avoids_occupied_inline_interval() {
        for (mode, float_x, block_x) in [("vertical-lr", 0.0, 0.0), ("vertical-rl", 80.0, 90.0)] {
            let markup = alloc::format!(
                "<main style='writing-mode:{mode};width:100px;height:100px'>\n                 <i id=a style='float:left;width:20px;height:40px'></i>\n                 <div id=b style='display:flow-root;width:10px;height:20px'></div></main>"
            );
            let (document, geometry) = intrinsic_keyword_geometry(&markup);
            let float = intrinsic_keyword_rect(&document, &geometry, "#a");
            let block = intrinsic_keyword_rect(&document, &geometry, "#b");
            assert_eq!((float.x, float.y), (float_x, 0.0), "{mode}");
            assert_eq!(
                (block.x, block.y, block.width, block.height),
                (block_x, 40.0, 10.0, 20.0),
                "{mode}"
            );
        }
        let (document, geometry) = intrinsic_keyword_geometry(
            "<main style='width:100px;height:100px'><i id=a style='float:left;width:40px;height:20px'></i><div id=b style='display:flow-root;width:20px;height:10px'></div></main>",
        );
        let block = intrinsic_keyword_rect(&document, &geometry, "#b");
        assert_eq!(
            (block.x, block.y, block.width, block.height),
            (40.0, 0.0, 20.0, 10.0)
        );
    }

    #[test]
    fn vertical_floats_share_paragraph_occupancy_and_formatting_context_containment() {
        for mode in ["vertical-lr", "vertical-rl"] {
            let markup = alloc::format!(
                "<main style='writing-mode:{mode};width:100px;height:100px'>\n                 <i id=a style='float:left;width:20px;height:40px'></i>\n                 <span id=b>xx</span></main>"
            );
            let (document, geometry) = intrinsic_keyword_geometry(&markup);
            let float = intrinsic_keyword_rect(&document, &geometry, "#a");
            let text = intrinsic_keyword_rect(&document, &geometry, "#b");
            assert_eq!(
                text.y,
                float.y + float.height,
                "{mode} text starts after line-left float"
            );
            assert!(
                text.x < float.x + float.width && text.x + text.width > float.x,
                "{mode} text remains in the same block-axis interval"
            );
            let markup = alloc::format!(
                "<main id=parent style='display:flow-root;writing-mode:{mode};width:100px'>\n                 <i id=a style='float:left;width:20px;height:40px'></i></main>"
            );
            let (document, geometry) = intrinsic_keyword_geometry(&markup);
            let parent = intrinsic_keyword_rect(&document, &geometry, "#parent");
            let float = intrinsic_keyword_rect(&document, &geometry, "#a");
            assert_eq!(parent.height, 40.0, "{mode} contains float inline extent");
            assert!(float.x >= parent.x && float.x + float.width <= parent.x + parent.width);
        }
        let (document, geometry) = intrinsic_keyword_geometry(
            "<main style='width:100px;height:100px'><i id=a style='float:left;width:40px;height:20px'></i><span id=b>xx</span></main>",
        );
        let float = intrinsic_keyword_rect(&document, &geometry, "#a");
        let text = intrinsic_keyword_rect(&document, &geometry, "#b");
        assert_eq!(
            text.x,
            float.x + float.width,
            "horizontal paragraph control"
        );
    }

