    #[test]
    fn float_rule_three_allows_overhang_until_an_opposing_float_intersects() {
        let left = colored_boxes_in(
            "<div style='float:left;width:500px;height:500px'><div style='float:right;width:50px;height:300px'></div><div style='margin-right:100px'><div style='float:left;width:425px;height:10px;background:green'></div></div></div>",
            600,
            550,
        );
        assert_eq!(
            left.iter()
                .map(|rect| (rect.x, rect.y, rect.width))
                .collect::<Vec<_>>(),
            [(0.0, 0.0, 425.0)],
            "the overhanging left float fits before the opposing float"
        );

        let right = colored_boxes_in(
            "<div style='float:right;width:500px;height:500px'><div style='float:left;width:50px;height:300px'></div><div style='margin-left:100px'><div style='float:right;width:425px;height:10px;background:green'></div></div></div>",
            600,
            550,
        );
        assert_eq!(
            right
                .iter()
                .map(|rect| (rect.x, rect.y, rect.width))
                .collect::<Vec<_>>(),
            [(175.0, 0.0, 425.0)],
            "the overhanging right float fits after the opposing float"
        );
    }

    #[test]
    fn float_rule_seven_repositions_same_side_float_outside_its_containing_block() {
        fn blue_boxes(markup: &str) -> Vec<Rect> {
            let markup = alloc::format!("<style>body{{margin:0}}</style>{markup}");
            let document = crate::html::parse(&markup, 32).unwrap();
            display_list(&document, 600, 550, &FixedText)
                .unwrap()
                .0
                .into_iter()
                .filter_map(|command| match command {
                    Command::FillRect { rect, color }
                        if (color.r, color.g, color.b) == (0, 0, 255) =>
                    {
                        Some(rect)
                    }
                    _ => None,
                })
                .collect()
        }

        let left = blue_boxes(
            "<div style='float:left;width:500px;height:500px'><div style='float:left;width:50px;height:300px'></div><div style='margin-left:100px'><div style='float:left;width:425px;height:10px;background:blue'></div></div></div>",
        );
        assert_eq!(
            left.iter()
                .map(|rect| (rect.x, rect.y, rect.width, rect.height))
                .collect::<Vec<_>>(),
            [(100.0, 300.0, 425.0, 10.0)],
            "a left float that would overhang its containing block moves below the preceding left float"
        );

        let right = blue_boxes(
            "<div style='float:left;width:500px;height:500px'><div style='float:right;width:50px;height:300px'></div><div style='margin-right:100px'><div style='float:right;width:425px;height:10px;background:blue'></div></div></div>",
        );
        assert_eq!(
            right
                .iter()
                .map(|rect| (rect.x, rect.y, rect.width, rect.height))
                .collect::<Vec<_>>(),
            [(-25.0, 300.0, 425.0, 10.0)],
            "the right-float rule is symmetric even when the candidate overhangs left"
        );
    }

#[test]
fn specification_margin_collapse_parent_top_propagates_through_nested_boxes() {
    let boxes = colored_boxes_in(
        "<div style='height:10px;margin-bottom:20px;background:green'></div><div style='margin-top:5px'><div style='margin-top:30px;margin-bottom:-10px;height:5px;background:green'></div></div><div style='margin-top:15px;height:5px;background:green'></div>",
        100, 200,
    );
    assert_eq!(boxes.iter().map(|rect| (rect.y, rect.height)).collect::<Vec<_>>(),
        [(0.0, 10.0), (40.0, 5.0), (50.0, 5.0)]);
    // Newly exposed UA logical margins collapse with body exactly like
    // authored margins; the root's own margin stays outside that chain.
    for (body_margin, child, expected) in [
        (8, "<pre style='font:5px/1 Ahem;background:green'>X</pre>", 8.0),
        (16, "<p style='background:green'>X</p>", 16.0),
    ] {
        let markup = alloc::format!("<style>body{{margin:{body_margin}px}}</style>{child}");
        let document = crate::html::parse(&markup, 64).unwrap();
        let rules = stylesheets(&document).unwrap();
        let mut geometry = LayoutGeometry::default();
        display_list_with_styles(&document, 200, 200, &FixedText, &rules, None, Some(&mut geometry), &[]).unwrap();
        let body = crate::selector::query_selector(&document, document.root(), "body").unwrap().unwrap();
        let child = document.first_child(body).unwrap().unwrap();
        assert_eq!(geometry.hits.iter().find(|hit| hit.node == body).unwrap().rect.y, expected);
        assert_eq!(geometry.hits.iter().find(|hit| hit.node == child).unwrap().rect.y, expected);
    }
}

#[test]
fn specification_margin_collapse_empty_chains_retain_both_signed_extrema() {
    let boxes = colored_boxes_in(
        "<div style='height:10px;margin-bottom:20px;background:green'></div><div style='margin-top:-7px;margin-bottom:30px'></div><div style='margin-top:-12px;margin-bottom:5px'></div><div style='margin-top:4px;height:5px;background:green'></div>",
        100, 100,
    );
    assert_eq!(boxes.iter().map(|rect| (rect.y, rect.height)).collect::<Vec<_>>(),
        [(0.0, 10.0), (28.0, 5.0)]);
    let negative = colored_boxes_in(
        "<div style='margin-top:-5px'><div style='margin-top:-20px;height:30px;background:green'></div></div><div style='height:5px;background:green'></div>",
        100, 100,
    );
    assert_eq!(negative.iter().map(|rect| (rect.y, rect.height)).collect::<Vec<_>>(),
        [(-20.0, 30.0), (10.0, 5.0)]);
    // Zero used height alone is insufficient: a definite minimum prevents
    // the parent's top and bottom margins becoming adjoining.
    let minimum = colored_boxes_in(
        "<div style='min-height:10px;margin-top:20px;margin-bottom:30px'></div><div style='height:5px;background:green'></div>",
        100, 100,
    );
    assert_eq!(minimum[0].y, 60.0);
}

#[test]
fn specification_margin_collapse_edges_contexts_clearance_and_root_are_boundaries() {
    for (boundary, expected) in [
        ("", 20.0),
        ("padding-top:1px", 26.0),
        ("border-top:1px solid transparent", 26.0),
        ("display:flow-root", 25.0),
        ("overflow:hidden", 25.0),
        ("height:50px", 20.0),
        ("min-height:50px", 20.0),
        ("position:relative", 20.0),
    ] {
        let markup = alloc::format!("<div style='margin-top:5px;{boundary}'><div style='height:10px;margin-top:20px;background:green'></div></div>");
        let boxes = colored_boxes_in(&markup, 100, 200);
        assert_eq!(boxes[0].y, expected, "boundary: {boundary}");
    }
    let clear = colored_boxes_in(
        "<div style='float:left;width:10px;height:50px'></div><div><div style='clear:left;margin-top:20px;height:10px;background:green'></div></div>",
        100, 150,
    );
    assert_eq!(clear[0].y, 50.0);
    let root = crate::html::parse("<div>X</div>", 64).unwrap();
    let html = root.first_child(root.root()).unwrap().unwrap();
    let body = crate::selector::query_selector(&root, root.root(), "body").unwrap().unwrap();
    let mut block = Style::initial();
    block.display = Display::Block;
    assert!(margin_context_root(&root, html, &block, &block), "actual document-element margins never collapse with children");
    assert!(!margin_context_root(&root, body, &block, &block), "a body rendering entry is not the CSS root");
}

