    #[test]
    fn specification_inline_continuations_coalesce_generated_edges_and_keep_authored_breaks() {
        for (boundary, white_space) in [("", "normal"),("<br>","normal"),("\n","pre-line")] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}p{{margin:0;line-height:24px;white-space:{white_space}}}#target::before{{content:'X';padding:20px 5px;border:1px solid blue;margin:0 3px}}#target::after{{content:'Y';padding:40px 4px}}span{{padding:30px 7px}}em{{display:inline-block;font-style:normal}}</style><p id=target>A<span>B<em>C</em>D</span>{boundary}F</p>"),128).unwrap();
            let target=crate::selector::query_selector(&document,document.root(),"#target").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,300,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==target&&!hit.virtual_generated).unwrap().rect;
            let expected=if boundary.is_empty(){24.0}else{48.0};
            assert!((rect.height-expected).abs()<0.01,"actual BR/preserved segment breaks delimit lines; source and UCD end sentinels do not: boundary={boundary:?}, rect={rect:?}");
            let baselines:Vec<_>=list.0.iter().filter_map(|command|match command {
                Command::GlyphRun{baseline_y,glyphs,..} if glyphs.iter().any(|glyph|glyph.id==u16::from(b'X')||glyph.id==u16::from(b'Y'))=>Some(*baseline_y),_=>None,
            }).collect();
            assert_eq!(baselines.len(),2);
            assert!((baselines[1]-baselines[0]-if boundary.is_empty(){0.0}else{24.0}).abs()<0.01,"generated prefix/suffix share actual line continuation");
        }
    }

    #[test]
    fn specification_generated_block_clearance_bfc_margins_and_paint_share_ordinary_boxes() {
        for properties in [
            "display:block;height:0;clear:both;visibility:hidden",
            "display:block;height:8px;clear:left;margin-top:7px;margin-bottom:9px;background:blue",
            "display:flow-root;width:50px;height:12px;background:blue",
            "display:flow-root;width:70px;height:12px;background:blue",
            "display:block;height:12px;overflow:hidden;background:blue",
            "display:block;height:12px;margin:6px 3px 8px;background:blue;opacity:.5;transform:translateX(2px)",
            "display:block;float:right;width:30px;height:20px;background:blue",
        ] {
            let render = |generated: bool| {
                let rule=if generated { alloc::format!("#target::after{{content:'X';{properties}}}") }
                    else { alloc::format!(".probe{{{properties}}}") };
                let child=if generated { "" } else { "<div class=probe>X</div>" };
                let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}#target{{width:100px;border:1px solid green}}.float{{float:left;width:40px;height:30px;background:red}}#next{{height:5px;background:yellow}}{rule}</style><div id=target><div class=float></div>{child}</div><div id=next></div>"),128).unwrap();
                let target=crate::selector::query_selector(&document,document.root(),"#target").unwrap().unwrap();
                let next=crate::selector::query_selector(&document,document.root(),"#next").unwrap().unwrap();
                let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
                let list=display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
                let rect=|node|geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
                let paint:Vec<Command>=list.0.iter().filter(|command|matches!(command,
                    Command::FillRect{..}|Command::StrokeBorder{..}|Command::StrokeBoxBorder(_)|Command::PushLayer{..}|Command::PopLayer|Command::PushTransform(_)|Command::PopTransform)).cloned().collect();
                (rect(target),rect(next),paint)
            };
            assert_eq!(render(true),render(false),"generated and actual child boxes share clear, float avoidance, margin and paint algorithms: {properties}");
        }
    }

    #[test]
    fn specification_generated_positioned_sources_share_static_geometry_negative_order_and_replay() {
        for (container,position,insets) in [
            ("position:relative;z-index:0", "absolute", "left:0;top:0"),
            ("position:relative", "absolute", "left:0;top:0"),
            ("position:relative;z-index:0", "absolute", "left:0"),
            ("position:relative;z-index:0", "fixed", "left:0;top:0"),
        ] {
            let render=|generated:bool| {
                let before=alloc::format!("position:{position};{insets};width:20px;height:20px;background:red;z-index:-2");
                let after=alloc::format!("position:{position};{insets};width:12px;height:12px;background:blue;z-index:-1");
                let rule=if generated { alloc::format!("#target::before{{content:'';{before}}}#target::after{{content:'';{after}}}") }
                    else { alloc::format!("#before{{{before}}}#after{{{after}}}") };
                let body=if generated { "<div class=middle></div>" }
                    else { "<div id=before></div><div class=middle></div><div id=after></div>" };
                let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0;background:white}}#target{{width:100px;height:50px;background:green;{container}}}.middle{{height:10px;background:yellow}}{rule}</style><div id=target>{body}</div>"),128).unwrap();
                let list=display_list(&document,200,200,&RecordingText::default()).unwrap();
                list.0.into_iter().filter(|command|matches!(command,Command::FillRect{..})).collect::<Vec<_>>()
            };
            assert_eq!(render(true),render(false),"native and pseudo positioned sources share deferred containing-block resolution and negative stacking order: {container}; {position}; {insets}");
        }
        let document=crate::html::parse("<!doctype html><style>body{margin:0}p{margin:0;height:24px}#target{position:relative;z-index:0;width:100px;height:50px;background:green}#target::before{content:'';position:absolute;left:0;top:0;width:20px;height:20px;background:red;z-index:-2}#target::after{content:'';position:fixed;left:2px;top:3px;width:12px;height:12px;background:blue;z-index:1}</style><p id=changed>before</p><div id=target></div>",128).unwrap();
        let changed=crate::selector::query_selector(&document,document.root(),"#changed").unwrap().unwrap();
        let text=document.first_child(changed).unwrap().unwrap();
        let mut session=crate::session::RenderSession::new(document);
        session.display_list(200,200,&RecordingText::default()).unwrap();
        session.document_mut().replace_data(text,"changed").unwrap();
        let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
        let fresh=display_list(session.document(),200,200,&RecordingText::default()).unwrap();
        assert_eq!(retained,fresh,"deferred pseudo positioning and negative escapes preserve retained source identity");
    }

    #[test]
    fn specification_generated_positioned_batch_stacking_preserves_scope_provenance_and_replay() {
        let document=crate::html::parse("<!doctype html><style>body{margin:0}p{margin:0;height:24px}#target{position:relative;z-index:0;width:100px;height:80px;background:green}#target::before{content:'';position:absolute;left:0;top:0;width:20px;height:20px;background:black;z-index:-3}#target::after{content:'';position:absolute;left:0;top:0;width:20px;height:20px;background:#ff00ff;z-index:-1}.clip{position:relative;overflow:hidden;width:20px;height:20px}.negative{position:absolute;left:0;top:0;width:40px;height:40px;background:red;z-index:-2}.one{position:absolute;left:0;top:0;width:20px;height:20px;background:yellow;z-index:-1}.ordinary{width:10px;height:10px;background:blue}.transformed{transform:translateX(5px);width:10px;height:10px}.transformed span{display:block;width:10px;height:10px;background:#00ffff}</style><p id=changed>before</p><div id=target><div class=clip><div class=negative></div></div><div class=one></div><div class=ordinary></div><div class=transformed><span></span></div></div>",256).unwrap();
        let node=|selector|crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
        let negative=node(".negative");let ordinary=node(".ordinary");let transformed=node(".transformed span");
        let changed=node("#changed");let text=document.first_child(changed).unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        let list=display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let mut colors=Vec::new();let mut clips=0usize;let mut clipping_layers=Vec::new();
        for command in &list.0 {
            match command {
                Command::PushClip(_) | Command::PushBoxClip(_)=>clips+=1,
                Command::PopClip=>clips-=1,
                Command::PushLayer{clip,..}=>{clipping_layers.push(*clip);if *clip{clips+=1;}},
                Command::PopLayer=>{if clipping_layers.pop().unwrap(){clips-=1;}},
                Command::FillRect{color,..}=>{
                    let rgb=(color.r,color.g,color.b);
                    if matches!(rgb,(0,0,0)|(255,0,0)|(255,255,0)|(255,0,255)){colors.push(rgb);}
                    if rgb==(255,0,0){assert!(clips>0,"negative descendant retains its overflow ancestor's actual paint clip");}
                    if rgb==(0,0,255){assert_eq!(clips,0,"ordinary sibling does not inherit the escaped descendant's clip");}
                }
                _=>{}
            }
        }
        assert_eq!(colors,[(0,0,0),(255,0,0),(255,255,0),(255,0,255)],"z order and equal-z before/real/after encounter order share one batch");
        let index=|node|geometry.hits.iter().position(|hit|hit.node==node&&!hit.virtual_generated).unwrap();
        let negative_hit=index(negative);let ordinary_hit=index(ordinary);let transformed_hit=index(transformed);
        assert!(geometry.rounded_clips.iter().any(|clip|clip.hits.contains(&negative_hit)));
        assert!(!geometry.rounded_clips.iter().any(|clip|clip.hits.contains(&ordinary_hit)),"split clip ranges must not broaden across unrelated siblings");
        assert!(geometry.transforms.iter().any(|transform|transform.hits.contains(&transformed_hit)));
        assert!(!geometry.transforms.iter().any(|transform|transform.hits.contains(&ordinary_hit)),"transform provenance survives hit permutation");
        let mut session=crate::session::RenderSession::new(document);
        session.display_list(200,200,&RecordingText::default()).unwrap();
        session.document_mut().replace_data(text,"changed").unwrap();
        let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
        let fresh=display_list(session.document(),200,200,&RecordingText::default()).unwrap();
        assert_eq!(retained,fresh,"multiple negative real/pseudo siblings and nested scopes retain identical replay order");
    }

    #[test]
    fn specification_inline_continuations_button_used_layout_preserves_computed_display_and_edges() {
        for display in ["inline", "inline-block", "inline-table", "block", "flow-root", "list-item", "table", "table-cell"] {
            let markup=alloc::format!("<!doctype html><style>body{{margin:0}}button{{display:{display};font:10px/10px monospace;padding:10px;border:2px solid black;margin:0}}button span{{float:left;width:20px;height:30px}}</style><button id=b><span></span>X</button>");
            let document=crate::html::parse(&markup,128).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#b").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();
            let authored=css::compute_node(&document,node,None,&rules).unwrap();
            let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
            assert!(rect.width>=44.0&&rect.width<100.0,"button auto inline size is fit-content, including physical edges: {display}; {rect:?}");
            assert!(rect.height>=54.0,"button establishes a formatting context containing its float: {display}; {rect:?}");
            assert_eq!(css::compute_node(&document,node,None,&rules).unwrap().display,authored.display,"used layout must not rewrite computed CSS display");
            let mut session=crate::session::RenderSession::new(document);
            let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
            assert_eq!(list,retained);
            assert_eq!(session.display_list(200,200,&RecordingText::default()).unwrap(),&retained);
        }
        for position in ["absolute","fixed"] {
            let document=crate::html::parse(&alloc::format!("<style>body{{margin:0}}button{{position:{position};left:0;right:0;top:0;bottom:0;padding:10px;border:2px solid black;font:10px/10px monospace}}</style><button id=b>X</button>"),64).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#b").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
            assert!(rect.width>=24.0&&rect.width<100.0&&rect.height>=34.0&&rect.height<100.0,"positioned button uses replaced natural dimensions instead of inset stretching: {rect:?}");
        }
    }

    #[test]
    fn specification_inline_continuations_encountered_floats_move_owned_line_sources_and_replay() {
        for side in ["left","right"] {
            for generated in [false,true] {
                let float=if generated {""} else {"<i id=f></i>"};
                let pseudo=if generated {alloc::format!("p::after{{content:'';float:{side};width:20px;height:30px;background:blue}}")} else {String::new()};
                let document=crate::html::parse(&alloc::format!("<style>body{{margin:0}}p{{margin:0;width:100px;font:10px/10px monospace}}i{{float:{side};width:20px;height:30px;background:blue}}{pseudo}</style><p><span id=t>AB</span>{float}</p>"),128).unwrap();
                let text_node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
                let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
                let list=display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
                let text=geometry.hits.iter().find(|hit|hit.node==text_node&&!hit.virtual_generated).unwrap().rect;
                assert_eq!(text.y,0.0,"encountered float preserves the existing line");
                assert_eq!(text.x,if side=="left"{20.0}else{0.0},"ordinary and generated floats shorten the same current line");
                let mut session=crate::session::RenderSession::new(document);
                let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
                assert_eq!(retained,list);
                assert_eq!(session.display_list(200,200,&RecordingText::default()).unwrap(),&retained);
                let source=session.document().first_child(text_node).unwrap().unwrap();
                session.document_mut().replace_data(source,"CD").unwrap();
                let replay=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
                let fresh=display_list(session.document(),200,200,&RecordingText::default()).unwrap();
                assert_eq!(replay,fresh,"float line source provenance survives retained invalidation");
            }
        }
        for align in ["right", "center"] {
            for side in ["left", "right"] {
                let document=crate::html::parse(&alloc::format!("<style>body{{margin:0}}p{{margin:0;width:100px;font:10px/10px monospace;text-align:{align}}}i{{float:{side};width:20px;height:30px;background:blue}}</style><p><span id=t>AB</span><i id=f></i></p>"),128).unwrap();
                let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
                display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
                let rect=|selector| {let node=crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect};
                assert_eq!(rect("#f").x,if side=="left"{0.0}else{80.0},"line alignment cannot move the encountered float itself");
                let text=rect("#t");
                let left=if side=="left"{20.0}else{0.0};
                let free=80.0-text.width;
                assert!((text.x-(left+if align=="right"{free}else{free*0.5})).abs()<0.01,"line alignment uses the shortened line: {align}; {side}; {text:?}");
            }
        }
        let document=crate::html::parse("<style>body{margin:0}p{margin:0;width:100px;font:10px/10px monospace}i{float:left;width:10px;height:30px;background:blue}</style><p><span id=t>AB</span><i id=one></i><i id=two></i><span id=u>C</span><br><span id=v>D</span></p>",128).unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let rect=|selector| {let node=crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect};
        assert_eq!(rect("#t").x,20.0,"multiple later floats cumulatively displace only in-flow sources");
        assert_eq!(rect("#one").x,0.0,"a later float cannot displace an earlier float subtree");
        assert_eq!(rect("#two").x,10.0);
        assert!(rect("#u").x>=32.0);
        assert_eq!(rect("#v").x,20.0,"real BR ends the old line but retains float occupancy");
        assert!(rect("#v").y>=10.0);
        let document=crate::html::parse("<style>body{margin:0}p{margin:0;width:30px;font:10px/10px monospace}i{float:left;width:25px;height:30px}</style><p><span id=t>AB</span><i id=f></i></p>",64).unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let node=crate::selector::query_selector(&document,document.root(),"#f").unwrap().unwrap();
        let float=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
        assert!(float.y>=10.0,"a float which does not fit beside existing content starts below the current line");
    }

    #[test]
    fn specification_inline_continuations_later_float_logical_axes_and_bounded_batch_provenance() {
        for writing in ["vertical-rl","vertical-lr"] {
            let mut positions = Vec::new();
            for before in [true,false] {
                let children=if before {"<i id=f></i><span id=t>AB</span><span id=u>C</span>"}else{"<span id=t>AB</span><i id=f></i><span id=u>C</span>"};
                let document=crate::html::parse(&alloc::format!("<style>body{{margin:0}}main{{writing-mode:{writing};width:60px;height:100px;font:10px/10px monospace}}i{{float:left;width:30px;height:20px;background:blue}}</style><main>{children}</main>"),128).unwrap();
                let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
                display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
                let mut boxes=Vec::new();
                for selector in ["#t","#f","#u"] {
                    let node=crate::selector::query_selector(&document,document.root(),selector).unwrap().unwrap();
                    boxes.push(geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect);
                }
                assert_eq!(boxes[0].y,20.0,"the open line starts beyond the float's logical inline edge: {writing}; before={before}");
                assert_eq!(boxes[2].y,32.0,"subsequent source keeps its advance after the same float: {writing}; before={before}");
                positions.push(boxes);
                let mut session=crate::session::RenderSession::new(document);
                session.display_list(200,200,&RecordingText::default()).unwrap();
                let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();
                let fresh=display_list(session.document(),200,200,&RecordingText::default()).unwrap();
                assert_eq!(retained,fresh,"physical float-source movement survives retained replay: {writing}; before={before}");
            }
            assert_eq!(positions[0],positions[1],"float admission before/after an open line shares logical axes: {writing}");
        }
        let mut markup=String::from("<style>body{margin:0}p{margin:0;width:500px;font:10px/10px monospace}i{float:left;width:1px;height:30px;background:blue}</style><p><span id=t>AB</span>");
        for _ in 0..200 {markup.push_str("<i></i>");}markup.push_str("</p>");
        let document=crate::html::parse(&markup,512).unwrap();
        let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,600,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        assert_eq!(geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect.x,200.0,"many float admissions commit the one original source segment once");
        let mut floats=geometry.hits.iter().filter(|hit|!hit.virtual_generated&&matches!(document.kind(hit.node),Ok(NodeKind::Element{name,..}) if name=="i")).map(|hit|hit.rect.x).collect::<Vec<_>>();
        floats.sort_by(|a,b|a.total_cmp(b));
        assert_eq!(floats,(0..200).map(|index|index as f32).collect::<Vec<_>>(),"in-flow source relocation never moves preceding float subtrees");
    }

    #[test]
    fn specification_inline_continuations_offscreen_atomic_geometry_survives_zero_available_width() {
        for body in ["margin:0;padding:2000px","margin:0;width:0"] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{{body}}}button{{padding:10px;border:2px solid black}}</style><button id=button>X</button>"),64).unwrap();
            let button=crate::selector::query_selector(&document,document.root(),"#button").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            let list=display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let hit=geometry.hits.iter().find(|hit|hit.node==button&&!hit.virtual_generated).expect("offscreen inline atomic control still publishes real geometry");
            assert!(hit.rect.width>=24.0&&hit.rect.height>=24.0,"zero available inline width cannot erase intrinsic control borders/padding: {body}; {:?}",hit.rect);
            if body.contains("2000") {
                assert!(hit.rect.x>=2000.0&&hit.rect.y>=2000.0);
                assert!(!list.0.iter().any(|command|matches!(command,Command::GlyphRun{..})),"offscreen geometry does not require painting invisible glyph runs");
            }
            let mut session=crate::session::RenderSession::new(document);session.display_list(200,200,&RecordingText::default()).unwrap();
            let retained=session.display_list(200,200,&RecordingText::default()).unwrap().clone();let fresh=display_list(session.document(),200,200,&RecordingText::default()).unwrap();
            assert_eq!(retained,fresh);
        }
    }

    #[test]
    fn specification_svg_instance_styles_drive_actual_source_geometry_paint_and_nested_replay() {
        let document=crate::html::parse("<!doctype html><style>body{margin:0}svg{display:block}.source #template,.source #a,#before + #template,#template:has(+ #after){fill:red}use #a{fill:red}#template:not(:first-child) #a{fill:red}#template > rect:nth-child(2){fill:blue}#a:lang(en){fill:lime}#a:lang(fr){fill:red}@scope (.source){#b{fill:red}}</style><svg width='200' height='100'><rect id='back' width='200' height='100' fill='yellow'/><defs><g class='source' lang='fr'><rect id='before'/><g id='template'><rect id='a' width='20' height='20'/><rect id='b' x='30' width='20' height='20'/></g><rect id='after'/></g><g id='outer'><use href='#template'/></g></defs><use id='u' href='#template' x='20' y='10' fill='green' lang='en'/></svg>",128).unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let node=|id|crate::selector::query_selector(session.document(),session.document().root(),&alloc::format!("#{id}")).unwrap().unwrap();
        let owner=node("u");let a=node("a");let b=node("b");let back=node("back");
        for (language,href,first) in [("en","#template",Rgba{r:0,g:255,b:0,a:255}),("fr","#template",Rgba{r:255,g:0,b:0,a:255}),("en","#outer",Rgba{r:0,g:255,b:0,a:255})] {
            session.document_mut().set_attribute(owner,"lang",language).unwrap();session.document_mut().set_attribute(owner,"href",href).unwrap();
            let rules=stylesheets(session.document()).unwrap();assert!(unsupported_svg_features(session.document(),&rules).unwrap().is_empty());
            let list=session.display_list(200,100,&RecordingText::default()).unwrap().clone();
            let fills=list.0.iter().filter_map(|command|match command {Command::SvgPath{fill:Some(crate::paint::SvgPaint::Color(color)),..}=>Some(*color),_=>None}).collect::<Vec<_>>();
            assert_eq!(fills,[Rgba{r:255,g:255,b:0,a:255},first,Rgba{r:0,g:0,b:255,a:255}],"{language}/{href}: source ancestry/siblings stop at each reference boundary, actual descendants and inherited host language remain");
            assert_eq!(session.hit_test(25.0,15.0),Some(owner));assert_eq!(session.hit_test(55.0,15.0),Some(owner));
            assert_eq!(session.hit_test(45.0,15.0),Some(back),"unpainted gaps do not gain aggregate use coverage");
            assert_eq!(session.display_list(200,100,&RecordingText::default()).unwrap(),&list);
            assert_eq!(display_list(session.document(),200,100,&RecordingText::default()).unwrap(),list);
            assert_eq!(css::compute_node(session.document(),a,None,&rules).unwrap().svg_fill,css::SvgPaint::Color(Rgba{r:255,g:0,b:0,a:255}),"instance sampling never changes source CSSOM");
        }
        session.document_mut().set_attribute(b,"style","fill:cyan").unwrap();
        let list=session.display_list(200,100,&RecordingText::default()).unwrap().clone();
        assert_eq!(list.0.iter().filter_map(|command|match command {Command::SvgPath{fill:Some(crate::paint::SvgPaint::Color(color)),..}=>Some(*color),_=>None}).last(),Some(Rgba{r:0,g:255,b:255,a:255}),"source mutation updates the instance without a cloned node or stale source style");
        assert_eq!(display_list(session.document(),200,100,&RecordingText::default()).unwrap(),list);
    }

    #[test]
    fn specification_symbol_source_and_instance_mandatory_ua_share_cascade_and_clips() {
        for authored_display in ["none", "block"] {
            let markup=alloc::format!("<!doctype html><style>body{{margin:0}}svg{{display:block}}#template{{display:{authored_display}!important;width:200px;height:200px}}#nested{{display:block!important}}</style><svg width='200' height='100'><rect id='back' width='200' height='100' fill='red'/><defs><symbol id='template' width='40' height='20' viewBox='0 0 40 20'><rect width='80' height='20' fill='green'/><symbol id='nested'><rect width='200' height='100' fill='blue'/></symbol></symbol></defs><use id='u' href='#template' x='20' y='10'/></svg>");
            let document=crate::html::parse(&markup,128).unwrap();let mut session=crate::session::RenderSession::new(document);
            let node=|selector|crate::selector::query_selector(session.document(),session.document().root(),selector).unwrap().unwrap();
            let template=node("#template");let owner=node("#u");let back=node("#back");let nested=node("#nested");
            for (overflow,inside,outside) in [("",Some(owner),Some(back)),("overflow:visible",Some(owner),Some(owner)),("overflow:revert",Some(owner),Some(back))] {
                session.document_mut().set_attribute(template,"style",overflow).unwrap();
                let rules=stylesheets(session.document()).unwrap();
                let source=css::compute_node(session.document(),template,None,&rules).unwrap();
                assert_eq!(source.display,Display::None,"source symbol must stay absent despite author !important");
                assert_eq!((source.width,source.height),(Some(200.0),Some(200.0)),"source CSSOM retains CSS sizing while the actual symbol consumes its 40x20 attributes");
                assert_eq!(source.overflow_x,if overflow=="overflow:visible" {css::Overflow::Visible}else{css::Overflow::Hidden},"hidden is the overridable UA baseline, including revert");
                let host=css::compute_node(session.document(),owner,None,&rules).unwrap();
                let instance=css::compute_svg_instance_root(session.document(),template,&host,&rules,None).unwrap();
                assert_eq!(instance.display,Display::Inline,"direct instance root must render despite author !important");
                assert_eq!(css::compute_node(session.document(),nested,Some(&instance),&rules).unwrap().display,Display::None,"nested symbol is still a definition");
                assert!(unsupported_svg_features(session.document(),&rules).unwrap().is_empty());
                let list=session.display_list(200,100,&RecordingText::default()).unwrap().clone();
                assert_eq!(list.0.iter().filter(|command|matches!(command,Command::SvgPath{..})).count(),2,"nested definition must not paint");
                assert_eq!(session.hit_test(30.0,15.0),inside);
                assert_eq!(session.hit_test(70.0,15.0),outside,"default and overridden clipping use actual instance hit ownership");
                assert_eq!(session.display_list(200,100,&RecordingText::default()).unwrap(),&list);
                assert_eq!(display_list(session.document(),200,100,&RecordingText::default()).unwrap(),list);
                assert_eq!(css::compute_node(session.document(),template,None,&rules).unwrap().display,Display::None,"instance computation does not overwrite source CSSOM");
            }
        }
    }

    #[test]
    fn specification_use_instance_viewports_share_geometry_paint_hit_and_mutation() {
        for root in ["svg","symbol"] {
            let markup=alloc::format!("<!doctype html><style>body{{margin:0}}svg{{display:block}}#u{{transform-box:fill-box;transform:scale(1);transform-origin:100% 100%}}</style><svg width='400' height='200'><rect id='back' width='400' height='200' fill='red'/><defs><{root} id='template' width='40' height='20' viewBox='0 0 100 50' overflow='hidden'><rect id='ink' width='100%' height='100%' fill='green'/></{root}><g id='plain'><rect width='10%' height='20%' fill='blue'/></g></defs><use id='u' href='#template' x='20' y='30'/><use id='ignored' href='#plain' x='250' y='40' width='1' height='1'/></svg>");
            let document=crate::html::parse(&markup,128).unwrap();let mut session=crate::session::RenderSession::new(document);
            let node=|selector|crate::selector::query_selector(session.document(),session.document().root(),selector).unwrap().unwrap();
            let owner=node("#u");let plain=node("#ignored");let template=node("#template");let ink=node("#ink");let back=node("#back");
            for (declaration,attribute_width,attribute_height,expected,viewport_width,viewport_height) in [
                ("width:calc(50% - 20px);height:60px","45%","30%",Rect{x:50.0,y:30.0,width:120.0,height:60.0},180.0,60.0),
                ("width:1000px;height:1000px","auto","auto",Rect{x:20.0,y:30.0,width:40.0,height:20.0},40.0,20.0),
                ("width:200px;height:200px","25%","25%",Rect{x:20.0,y:30.0,width:100.0,height:50.0},100.0,50.0),
            ] {
                session.document_mut().set_attribute(owner,"style",declaration).unwrap();
                session.document_mut().set_attribute(owner,"width",attribute_width).unwrap();
                session.document_mut().set_attribute(owner,"height",attribute_height).unwrap();
                let rules=stylesheets(session.document()).unwrap();
                assert!(unsupported_svg_features(session.document(),&rules).unwrap().is_empty(),"{root}/{declaration}: admission describes the actual joined source consumers");
                let list=session.display_list(400,200,&RecordingText::default()).unwrap().clone();
                let mut bounds=Vec::new();
                for command in &list.0 {if let Command::SvgPath{data,transform,..}=command {
                    let raw=lumen_common::svg_path::parse_svg_path(data).unwrap().object_bounds().unwrap();
                    bounds.push(transform.bounds(Rect{x:raw[0],y:raw[1],width:raw[2],height:raw[3]}));
                }}
                let host=css::compute_node(session.document(),owner,None,&rules).unwrap();
                let source=css::compute_svg_instance_root(session.document(),template,&host,&rules,None).unwrap();
                let NodeKind::Element{attributes,..}=session.document().kind(template).unwrap() else {unreachable!()};
                let (_,projection,_)=crate::svg::instance_viewport_with_computed_geometry(root,attributes,&source.svg_geometry,
                    Some(viewport_width),Some(viewport_height),crate::svg::ViewBox{min_x:0.0,min_y:0.0,width:400.0,height:200.0}).unwrap();
                let reference=session.layout_transform_reference_box(owner,None).unwrap().0;
                let canonical=host.transform_matrix(reference).unwrap().then(Affine{e:20.0,f:30.0,..Affine::IDENTITY})
                    .then(projection).bounds(Rect{x:0.0,y:0.0,width:100.0,height:50.0});
                assert_eq!(canonical.width,expected.width);assert_eq!(canonical.height,expected.height);
                assert_eq!(bounds,[Rect{x:0.0,y:0.0,width:400.0,height:200.0},canonical,Rect{x:250.0,y:40.0,width:40.0,height:40.0}],"{root}/{declaration}: exact paint coordinates share canonical matrix composition; ordinary graphics ignore host dimensions");
                assert_eq!(session.hit_test(expected.x+expected.width/2.0,expected.y+expected.height/2.0),Some(owner));
                assert_eq!(session.hit_test(260.0,50.0),Some(plain));
                assert_eq!(session.display_list(400,200,&RecordingText::default()).unwrap(),&list);
                assert_eq!(display_list(session.document(),400,200,&RecordingText::default()).unwrap(),list);
            }
            session.document_mut().set_attribute(owner,"style","width:1000px;height:1000px").unwrap();
            session.document_mut().set_attribute(owner,"width","auto").unwrap();
            session.document_mut().set_attribute(owner,"height","auto").unwrap();
            session.document_mut().set_attribute(template,"width","80").unwrap();session.document_mut().set_attribute(template,"height","40").unwrap();
            let list=session.display_list(400,200,&RecordingText::default()).unwrap().clone();
            assert_eq!(display_list(session.document(),400,200,&RecordingText::default()).unwrap(),list,"referenced-root mutation invalidates the shared source operation");
            assert_eq!(session.hit_test(90.0,60.0),Some(owner));
            session.document_mut().set_attribute(ink,"width","200%").unwrap();
            let clipped=session.display_list(400,200,&RecordingText::default()).unwrap().clone();
            assert_eq!(session.hit_test(60.0,50.0),Some(owner));
            assert_eq!(session.hit_test(110.0,50.0),Some(back),"{root}: source geometry overflows the instance viewport, whose actual clip also constrains hit ownership");
            assert_eq!(display_list(session.document(),400,200,&RecordingText::default()).unwrap(),clipped);
            if root=="symbol" {
                session.document_mut().set_attribute(template,"refX","center").unwrap();
                session.document_mut().set_attribute(template,"refY","center").unwrap();
                let list=session.display_list(400,200,&RecordingText::default()).unwrap().clone();
                let bounds=list.0.iter().filter_map(|command|match command {Command::SvgPath{data,transform,..}=>{
                    let raw=lumen_common::svg_path::parse_svg_path(data).unwrap().object_bounds().unwrap();
                    Some(transform.bounds(Rect{x:raw[0],y:raw[1],width:raw[2],height:raw[3]}))},_=>None}).collect::<Vec<_>>();
                assert_eq!(bounds[1],Rect{x:-20.0,y:10.0,width:160.0,height:40.0},"reference point changes the actual symbol viewport and projected contents together");
                assert_eq!(session.hit_test(10.0,20.0),Some(owner));
                assert_eq!(display_list(session.document(),400,200,&RecordingText::default()).unwrap(),list);
            }
        }
    }

