    #[test]
    fn specification_svg_xml_line_and_text_coordinates_replay_actual_owner_context() {
        let document=crate::html::parse("<!doctype html><style>html,body{margin:0}svg{display:block}#owner{font-size:10px}</style><svg width=200 height=100><g id=owner><line x1='calc(10% + 1em)' y1='1em' x2='calc(100% - 2em)' y2='2em' stroke=green /><text x='calc(10% + 1em)' y='calc(50% + 1em)'>a</text></g></svg>",96).unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let owner=crate::selector::query_selector(session.document(),session.document().root(),"#owner").unwrap().unwrap();
        for (font,path,x,y) in [(10,"M30 10L180 20",30.0,60.0),(20,"M40 20L160 40",40.0,70.0)] {
            session.document_mut().set_attribute(owner,"style",&alloc::format!("font-size:{font}px")).unwrap();
            assert!(session.unsupported_svg_features().unwrap().is_empty());
            let list=session.display_list(200,100,&RecordingText::default()).unwrap().clone();
            assert!(list.0.iter().any(|command|matches!(command,Command::SvgPath{data,..} if data.as_ref()==path)),"line endpoints must use actual owner font and horizontal viewport basis");
            assert!(list.0.iter().any(|command|matches!(command,Command::GlyphRun{origin_x,baseline_y,..} if *origin_x==x && *baseline_y==y)),"text position shares numeric context with paint and source geometry");
            assert_eq!(session.display_list(200,100,&RecordingText::default()).unwrap(),&list);
            assert_eq!(display_list(session.document(),200,100,&RecordingText::default()).unwrap(),list);
        }
        let line=crate::selector::query_selector(session.document(),session.document().root(),"line").unwrap().unwrap();
        session.document_mut().set_attribute(line,"x1","1s").unwrap();
        assert!(!session.unsupported_svg_features().unwrap().is_empty(),"dimensionally invalid XML coordinates must remain rejected");
    }

