    #[test]
    fn nested_q_quote_positions_use_parent_language_at_each_depth() {
        let document = crate::html::parse(
            r#"<html lang="en" id="root"><body><p><q id="outer">two <q id="middle" lang="ja">three <q id="inner" lang="fr">four</q></q></q></p></body></html>"#,
            128,
        )
        .unwrap();
        let rules = stylesheets(&document).unwrap();
        let text = RecordingText::default();
        let style_cache = core::cell::RefCell::new(css::StyleCache::default());
        let mut positions = Vec::new();
        let mut quote_depth = 0;
        let mut visited = 0;
        let root = crate::selector::query_selector(&document, document.root(), "#root")
            .unwrap()
            .unwrap();
        collect_quote_positions(
            &document,
            &rules,
            &text,
            &style_cache,
            root,
            None,
            None,
            &QuoteSystem::Auto(None),
            &mut quote_depth,
            &mut visited,
            &mut positions,
            0,
        )
        .unwrap();
        let node = |id| {
            crate::selector::query_selector(&document, root, &alloc::format!("#{id}"))
                .unwrap()
                .unwrap()
        };
        let outer = &positions.iter().find(|entry| entry.node == node("outer")).unwrap().position;
        let middle = &positions.iter().find(|entry| entry.node == node("middle")).unwrap().position;
        let inner = &positions.iter().find(|entry| entry.node == node("inner")).unwrap().position;
        assert_eq!(outer.before, 0);
        assert_eq!(middle.before, 1);
        assert_eq!(inner.before, 2);
        assert_eq!(quote_mark(&outer.system, outer.before, true), Some("“"));
        assert_eq!(quote_mark(&middle.system, middle.before, true), Some("‘"));
        assert_eq!(quote_mark(&inner.system, inner.before, true), Some("『"));
        assert_eq!(
            quote_mark(&inner.system, inner.after - 1, false),
            Some("』")
        );
        assert_eq!(
            quote_mark(&middle.system, middle.after - 1, false),
            Some("’")
        );
        assert_eq!(quote_mark(&outer.system, outer.after - 1, false), Some("”"));
    }

    #[test]
    fn specification_quote_positions_follow_live_identity_after_fragment_collection() {
        // Native fieldset-dynamic-oof-container-crash.html replaces body content
        // after the parser's temporary fragment has retired its arena slots.
        let mut document = crate::html::parse("<!doctype html><html lang=en><body></body></html>", 256).unwrap();
        let body = crate::selector::query_selector(&document, document.root(), "body").unwrap().unwrap();
        let retired = document.create(NodeKind::DocumentFragment).unwrap();
        for _ in 0..32 {
            let child = document.create(NodeKind::Text(String::from("retired"))).unwrap();
            document.append(retired, child).unwrap();
        }
        let fragment = crate::html::parse_fragment_in(&mut document, body,
            "<fieldset><q id=outer>outer <q id=inner lang=ja>inner</q></q></fieldset>").unwrap();
        document.append(body, fragment).unwrap();
        document.destroy_subtree(retired).unwrap();
        let outer = crate::selector::query_selector(&document, body, "#outer").unwrap().unwrap();
        let inner = crate::selector::query_selector(&document, body, "#inner").unwrap().unwrap();
        assert!(inner.index() >= document.node_count(), "live identity is deliberately outside dense live-count storage");
        let text = RecordingText::default();
        let rules = stylesheets(&document).unwrap();
        let style_cache = core::cell::RefCell::new(css::StyleCache::default());
        let mut positions = Vec::new();
        let mut quote_depth = 0;
        let mut visited = 0;
        collect_quote_positions(&document, &rules, &text, &style_cache,
            document.document_element_at(document.root()).unwrap().unwrap(), None, None,
            &QuoteSystem::Auto(None), &mut quote_depth, &mut visited, &mut positions, 0).unwrap();
        assert_eq!(positions.len(), 2, "only the two generated quote origins consume records");
        assert!(positions.iter().all(|entry| entry.node == outer || entry.node == inner));
        let mut session = crate::session::RenderSession::new(document);
        let retained = session.display_list(800, 600, &text).expect("sparse arena quote layout").clone();
        assert!(text.0.borrow().iter().any(|run| run.contains('“')));
        assert!(text.0.borrow().iter().any(|run| run.contains('‘')));
        assert_eq!(retained, display_list(session.document(), 800, 600, &text).unwrap());
        assert_eq!(retained, session.display_list(800, 600, &text).unwrap().clone());
        session.document_mut().set_attribute(outer, "lang", "ja").unwrap();
        let changed = session.display_list(800, 600, &text).unwrap().clone();
        assert_eq!(changed, display_list(session.document(), 800, 600, &text).unwrap());
        assert_ne!(retained, changed, "quote language mutation is rebuilt using the live origin");
        session.document_mut().set_attribute(inner, "style", "display:none").unwrap();
        let hidden = session.display_list(800, 600, &text).unwrap().clone();
        assert_eq!(hidden, display_list(session.document(), 800, 600, &text).unwrap());
    }

