    #[test]
    fn specification_input_button_labels_share_live_attributes_intrinsic_axes_and_replay() {
        for (kind,value,expected) in [("button",None,""),("submit",None,"Submit"),("reset",None,"Reset"),("submit",Some(""),""),("reset",Some("AB"),"AB"),("BuTtOn",Some("AB"),"AB")] {
            let attribute=value.map_or(String::new(),|value|alloc::format!(" value='{value}'"));
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}input{{font:10px/10px monospace;padding:2px;border:1px solid black}}</style><input id=t type='{kind}'{attribute}>"),64).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
            assert_eq!(crate::forms::input_button_label(&document,node),Some(expected));
            let mut session=crate::session::RenderSession::new(document);
            session.display_list(300,200,&RecordingText::default()).unwrap();
            let rect=session.client_rects(node)[0];
            assert_eq!(rect.width,expected.len() as f32*6.0+6.0,"missing/empty/default label intrinsic width: {kind}; {value:?}");
            session.document_mut().set_attribute(node,"value","ABCD").unwrap();
            let retained=session.display_list(300,200,&RecordingText::default()).unwrap().clone();
            assert_eq!(session.client_rects(node)[0].width,30.0,"Default-mode live attribute mutation invalidates label intrinsic size");
            assert_eq!(retained,display_list(session.document(),300,200,&RecordingText::default()).unwrap());
        }
        for writing in ["horizontal-tb","vertical-rl","vertical-lr"] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}input{{writing-mode:{writing};font:10px/10px monospace;padding:2px;border:1px solid black}}</style><input id=t type=button value=AB>"),64).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
            assert_eq!((rect.width,rect.height),if writing=="horizontal-tb"{(18.0,16.0)}else{(16.0,18.0)},"label intrinsic axes follow real writing mode");
            assert!(geometry.control_text_runs.is_empty(),"noneditable label creates no editable caret source");
        }
    }

    #[test]
    fn specification_input_button_labels_format_align_constrain_and_clip_without_dom_text() {
        let prefix="<!doctype html><style>body{margin:0}input{font:10px/10px monospace;padding:0;border:0}</style>";
        assert_eq!(painted_text_runs(&alloc::format!("{prefix}<input type=button value='1&#10;2'>")),painted_text_runs(&alloc::format!("{prefix}<input type=button value='1 2'>")),"normal white-space formats the value instead of text-input newline sanitization");
        assert_eq!(painted_text_runs(&alloc::format!("{prefix}<input type=button value=ab style='text-transform:uppercase'>")),painted_text_runs(&alloc::format!("{prefix}<input type=button value=AB>")));
        let document=crate::html::parse("<!doctype html><style>body{margin:0}input{font:10px/10px monospace;width:60px;height:40px;padding:2px;border:1px solid black;text-align:center;align-content:center;overflow:visible!important}</style><input id=t type=button value=AB>",64).unwrap();
        let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry { collect_rendered_text: true, ..LayoutGeometry::default() };
        let list=display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
        assert_eq!((rect.width,rect.height),(60.0,40.0),"border-box definite dimensions win over label fit-content");
        let computed=css::compute_node(&document,node,None,&rules).unwrap();
        assert_eq!((computed.overflow_x,computed.overflow_y),(css::Overflow::Clip,css::Overflow::Clip),"UA-important input clipping beats author-important overflow");
        let glyph=list.0.iter().find_map(|command|if let Command::GlyphRun{origin_x,baseline_y,..}=command{Some((*origin_x,*baseline_y))}else{None}).unwrap();
        assert_eq!(glyph.0,24.0,"ordinary horizontal content alignment centers label in content box");
        assert!(glyph.1>15.0&&glyph.1<25.0,"ordinary block alignment centers label vertically: {glyph:?}");
        assert!(geometry.rendered_text_boxes.is_empty(),"value label is not a DOM innerText source");
    }

    #[test]
    fn specification_input_button_labels_respect_constraints_preserved_lines_and_overflow_states() {
        for (style,width) in [("min-width:50px;max-width:80px",50.0),("width:200px;max-width:80px",80.0),("width:10px;min-width:50px",50.0)] {
            let document=crate::html::parse(&alloc::format!("<!doctype html><style>body{{margin:0}}input{{font:10px/10px monospace;padding:2px;border:1px solid black;min-height:30px;{style}}}</style><input id=t type=button value=AB>"),64).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
            display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
            let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
            assert_eq!((rect.width,rect.height),(width,30.0),"label intrinsic size participates in ordinary constraints and border-box edges");
        }
        let document=crate::html::parse("<!doctype html><style>body{margin:0}input{font:10px/10px monospace;padding:0;border:0;white-space:pre}</style><input id=t type=button value='A&#10;B' placeholder=ignored>",64).unwrap();
        let node=crate::selector::query_selector(&document,document.root(),"#t").unwrap().unwrap();
        let rules=stylesheets(&document).unwrap();let mut geometry=LayoutGeometry::default();
        display_list_with_styles(&document,200,200,&RecordingText::default(),&rules,None,Some(&mut geometry),&[]).unwrap();
        let rect=geometry.hits.iter().find(|hit|hit.node==node&&!hit.virtual_generated).unwrap().rect;
        assert_eq!((rect.width,rect.height),(6.0,20.0),"preserved newline creates real label line boxes and max-content width");
        assert_eq!(crate::forms::input_button_label(&document,node),Some("A\nB"),"formatting never sanitizes the Default-mode value attribute");
        for kind in ["button","submit","reset","text","range","checkbox","radio"] {
            let document=crate::html::parse(&alloc::format!("<input type={kind} style='overflow:visible!important'>"),16).unwrap();
            let node=crate::selector::query_selector(&document,document.root(),"input").unwrap().unwrap();
            let rules=stylesheets(&document).unwrap();let style=css::compute_node(&document,node,None,&rules).unwrap();
            let expected=if ["range","checkbox","radio"].contains(&kind){css::Overflow::Visible}else{css::Overflow::Clip};
            assert_eq!((style.overflow_x,style.overflow_y),(expected,expected),"input UA-important exact state exemptions: {kind}");
        }
    }

