    #[test]
    fn specification_upright_used_direction_reaches_nested_inline_edges_generated_ink_and_bidi_scopes() {
        for mode in ["vertical-rl","vertical-lr"] {
            for bidi in ["normal","embed","isolate","bidi-override","isolate-override"] {
                let document=crate::html::parse(&alloc::format!("<!doctype html><style>html,body{{margin:0}}#flow{{writing-mode:{mode};text-orientation:upright;direction:ltr;width:60px;height:100px;font:12px/16px monospace}}#scope{{unicode-bidi:{bidi};margin-inline-start:3px;padding-inline-end:5px;border-inline-start:2px solid red}}#scope::before{{content:'C';color:blue}}#scope::after{{content:'D';color:green}}#atomic{{display:inline-block;writing-mode:horizontal-tb;direction:rtl;width:20px}}</style><div id=flow><span id=scope><span>A</span><span style='color:red'>B</span><span id=atomic>אב</span></span></div>"),96).unwrap();
                let flow=crate::selector::query_selector(&document,document.root(),"#flow").unwrap().unwrap();
                let scope=crate::selector::query_selector(&document,document.root(),"#scope").unwrap().unwrap();
                let atomic=crate::selector::query_selector(&document,document.root(),"#atomic").unwrap().unwrap();
                let text=DirectionText(core::cell::RefCell::new(Vec::new()));
                let mut session=crate::session::RenderSession::new(document);
                let expected=session.display_list(160,160,&text).unwrap().clone();
                let expected_rects=(session.client_rects(scope).to_vec(),session.client_rects(atomic).to_vec());
                session.document_mut().set_attribute(flow,"style","direction:rtl").unwrap();
                let actual=session.display_list(160,160,&text).unwrap().clone();
                assert_eq!(actual,expected,"used inline direction {mode}/{bidi}: edges, generated runs and nested scopes");
                assert_eq!((session.client_rects(scope).to_vec(),session.client_rects(atomic).to_vec()),expected_rects,"actual hit fragments {mode}/{bidi}");
                assert_eq!(session.computed_style(flow).unwrap().direction,Direction::Rtl,"computed direction remains inherited/CSSOM authority");
                assert_eq!(session.computed_style(atomic).unwrap().used_direction(),Direction::Rtl,"horizontal atomic content retains its own computed RTL");
                assert!(text.0.borrow().iter().any(|(value,rtl)|value=="אב"&&*rtl),"orthogonal horizontal source shapes RTL");
                assert_eq!(session.display_list(160,160,&text).unwrap(),&actual,"warm replay");
                assert_eq!(display_list(session.document(),160,160,&text).unwrap(),actual,"fresh source replay");
            }
        }
    }

