    #[test]
    fn text_spacing_synthetic_caps_expansion_preserves_marks_and_inline_advance() {
        struct CapsText;
        impl TextShaper for CapsText {
            fn shape(&self, text: &str, _: f32) -> Result<ShapedRun, ()> {
                let mut glyphs = Vec::new();
                let mut x = 0.0;
                for (cluster, grapheme) in lumen_common::ucd::graphemes(text) {
                    let mut expansion = 0;
                    for character in grapheme.chars() {
                        if character == 'ß' {
                            for extra in 0..2 {
                                glyphs.push(Glyph {
                                    id: 'S' as u16,
                                    face: 0,
                                    cluster: cluster as u32,
                                    caps_expansion: extra,
                                    x,
                                    y: 0.0,
                                    size_scale: 0.8,
                                });
                                x += 6.0;
                            }
                            expansion = 1;
                        } else {
                            let mark = character == '\u{301}';
                            glyphs.push(Glyph {
                                id: character as u16,
                                face: 0,
                                cluster: cluster as u32,
                                caps_expansion: expansion,
                                x: if mark { x - 6.0 } else { x },
                                y: 0.0,
                                size_scale: 1.0,
                            });
                            if !mark {
                                x += 6.0;
                            }
                        }
                    }
                }
                Ok(ShapedRun {
                    glyphs: glyphs.into(),
                    width: x,
                })
            }
            fn ascent(&self, _: f32) -> f32 {
                10.0
            }
            fn line_height(&self, _: f32) -> f32 {
                12.0
            }
        }
        let document = crate::html::parse("<style>body{margin:0}p{margin:0;white-space:pre;font-variant-caps:small-caps;letter-spacing:2px;word-spacing:3px}</style><p>Aß\u{301} Z<i style='display:inline-block;width:4px;height:4px;background:red'></i></p>", 32).unwrap();
        let list = display_list(&document, 200, 30, &CapsText).unwrap();
        let glyphs = list
            .0
            .iter()
            .find_map(|command| match command {
                Command::GlyphRun { glyphs, .. } => Some(glyphs),
                _ => None,
            })
            .unwrap();
        assert_eq!(
            glyphs.iter().map(|glyph| glyph.x).collect::<Vec<_>>(),
            [0.0, 8.0, 16.0, 16.0, 24.0, 35.0]
        );
        let rect = list
            .0
            .iter()
            .find_map(|command| match command {
                Command::FillRect { rect, color } if color.r == 255 && color.g == 0 => Some(rect),
                _ => None,
            })
            .unwrap();
        assert_eq!(rect.x, 41.0);
    }

